/// Registers this device's FCM token on the user's profile document, so a
/// backend function can target them.
///
/// `arrayUnion` keeps one entry per device and ignores a token that is
/// already there, so calling this on every sign-in costs nothing. Clear the
/// stale ones from the send side: FCM reports the tokens it rejected.
Future<void> saveDeviceToken({
  required String userId,
  required String token,
}) {
  return safeFirebaseCall<void>(
    call: () => _profileRef(userId).set(
      {
        'fcmTokens': FieldValue.arrayUnion([token]),
      },
      SetOptions(merge: true),
    ),
  );
}

/// Registers this device's push token against the signed-in user — the
/// access token on the request is what says who that is.
///
/// Adapt the endpoint and the payload: most backends also want the platform,
/// a device id or the app version so they can clean up stale tokens.
Future<void> saveDeviceToken({required String token}) {
  return safeApiCall<void>(
    apiCall: () async {
      await _dio.post<dynamic>('/auth/device-token', data: {
        'token': token,
      });
    },
  );
}

