/// How often the flag is re-read while the app stays in the foreground.
const _pollInterval = Duration(minutes: 5);

/// Polls the availability endpoint, and again whenever the app returns to the
/// foreground — the moment that matters most, since someone coming back after
/// an hour away is the likeliest to meet a deploy.
///
/// The endpoint must be reachable **without a token**: a signed-out user, or
/// one whose session expired during the outage, still has to be told the app
/// is down. Add it to `_kPublicEndpoints` in `dio_client.dart`.
final maintenanceStatusProvider = StreamProvider<MaintenanceStatus>((ref) {
  final dio = ref.watch(dioClientProvider);
  final controller = StreamController<MaintenanceStatus>();

  Future<void> poll() async {
    final status = await _fetchStatus(dio);
    if (!controller.isClosed) controller.add(status);
  }

  final timer = Timer.periodic(_pollInterval, (_) => poll());
  final lifecycle = AppLifecycleListener(onResume: poll);

  ref.onDispose(() {
    timer.cancel();
    lifecycle.dispose();
    controller.close();
  });

  poll();
  return controller.stream;
});

/// Never throws. A status that cannot be read is reported as "up" — see
/// [MaintenanceGate] on why this fails open.
Future<MaintenanceStatus> _fetchStatus(Dio dio) async {
  try {
    final response = await dio.get<Map<String, dynamic>>('/config/maintenance');
    final data = response.data;
    if (data == null) return const MaintenanceStatus.up();
    return MaintenanceStatus.fromMap(data);
  } catch (_) {
    return const MaintenanceStatus.up();
  }
}

/// Proportional UI scaling for an entire Flutter app from a single wrapper
/// widget.
///
/// Wrap your root widget (typically [WidgetsApp]/`MaterialApp`) in a [MoAdapt]
/// and every logical dimension in the subtree — text, padding, margins, icon
/// sizes, border radii, widget widths and heights — is scaled proportionally
/// to the screen, relative to a reference design size. No `.w`/`.h`/`.sp`
/// accessors and no changes to child widgets are required.
library;

import 'dart:math' as math;
import 'dart:ui' as ui;

import 'package:flutter/widgets.dart';

/// How [MoAdapt] derives its scale factor from the screen size and
/// [MoAdapt.designSize].
enum MoAdaptScaleMode {
  /// `screenWidth / designWidth`.
  ///
  /// The default. Ideal for portrait phone apps: the layout always spans the
  /// full width exactly as designed, and vertical content scrolls as usual.
  width,

  /// `screenHeight / designHeight`.
  height,

  /// The smaller of the width and height ratios.
  ///
  /// The whole design area always fits on screen. Recommended for apps that
  /// support landscape or tablets, where pure width scaling would magnify the
  /// UI too much.
  min,

  /// The larger of the width and height ratios.
  max,
}

/// Information about the scaling currently applied by a [MoAdapt] ancestor.
///
/// Obtain it with [MoAdapt.of] or [MoAdapt.maybeOf].
@immutable
class MoAdaptData {
  /// Creates scaling information. Used internally by [MoAdapt].
  const MoAdaptData({
    required this.scale,
    required this.designSize,
    required this.screenSize,
    required this.adaptedSize,
  });

  /// The factor by which every logical pixel in the subtree is magnified.
  ///
  /// A value of `2.0` means a `SizedBox(width: 10)` occupies 20 real logical
  /// pixels on screen.
  final double scale;

  /// The reference design size this scaling is based on.
  final Size designSize;

  /// The real logical size of the screen (what `MediaQuery` would report
  /// outside of [MoAdapt]).
  final Size screenSize;

  /// The logical size the subtree is laid out at ([screenSize] divided by
  /// [scale]). This is what `MediaQuery.sizeOf` reports inside [MoAdapt].
  final Size adaptedSize;

  /// Converts [value] so that it occupies `value` real logical pixels on
  /// screen despite the ambient scaling.
  ///
  /// Useful for the rare widget that should *not* scale, e.g.
  /// `SizedBox(width: MoAdapt.of(context).unscale(48))` renders exactly 48
  /// real logical pixels wide.
  double unscale(double value) => value / scale;

  @override
  bool operator ==(Object other) {
    return other is MoAdaptData &&
        other.scale == scale &&
        other.designSize == designSize &&
        other.screenSize == screenSize &&
        other.adaptedSize == adaptedSize;
  }

  @override
  int get hashCode => Object.hash(scale, designSize, screenSize, adaptedSize);

  @override
  String toString() =>
      'MoAdaptData(scale: $scale, designSize: $designSize, '
      'screenSize: $screenSize, adaptedSize: $adaptedSize)';
}

/// Scales an entire widget subtree proportionally to the screen size, based
/// on a reference [designSize].
///
/// Place it once, as the parent of your app:
///
/// ```dart
/// void main() {
///   runApp(
///     const MoAdapt(
///       designSize: Size(412, 924),
///       child: MyApp(), // your existing MaterialApp, unchanged
///     ),
///   );
/// }
/// ```
///
/// Everything below is laid out in design-space coordinates and rendered
/// through a single uniform transform, so all fixed logical dimensions —
/// `fontSize: 16`, `EdgeInsets.all(12)`, `SizedBox(height: 24)`, icon sizes,
/// border radii — grow and shrink together with the screen. The transform is
/// applied at paint time as a vector operation, so text and shapes stay
/// pixel-crisp at any scale.
///
/// [MoAdapt] also rewrites the ambient [MediaQuery] (size, device pixel
/// ratio, safe-area padding, view insets) into design-space units, so
/// `SafeArea`, dialogs, bottom sheets, and keyboard avoidance keep working
/// consistently, and pointer events are mapped through the transform for
/// correct hit testing.
///
/// The system text scale factor (accessibility setting) still applies on top
/// of the proportional scaling. To opt out of that, clamp the text scaler in
/// your app's `builder` as usual.
class MoAdapt extends StatelessWidget {
  /// Creates a proportional scaling wrapper around [child].
  const MoAdapt({
    super.key,
    required this.designSize,
    required this.child,
    this.scaleMode = MoAdaptScaleMode.width,
    this.minScale,
    this.maxScale,
    this.enabled = true,
  });

  /// The logical size of the reference design, e.g. `Size(412, 924)` for an
  /// iPhone-14-sized Figma frame.
  final Size designSize;

  /// The widget subtree to scale — typically your `MaterialApp`.
  final Widget child;

  /// How the scale factor is computed. Defaults to [MoAdaptScaleMode.width].
  final MoAdaptScaleMode scaleMode;

  /// If non-null, the scale factor never goes below this value.
  final double? minScale;

  /// If non-null, the scale factor never goes above this value.
  ///
  /// Useful to keep the UI from becoming oversized on tablets and desktop
  /// windows, e.g. `maxScale: 1.3`.
  final double? maxScale;

  /// Whether scaling is applied. When false the subtree renders 1:1, which is
  /// handy for A/B-ing the effect. The widget tree structure is identical in
  /// both states, so toggling it does not lose any state.
  final bool enabled;

  /// The [MoAdaptData] from the closest [MoAdapt] ancestor.
  ///
  /// Throws in debug mode if there is no [MoAdapt] above [context]; see
  /// [maybeOf] for a null-safe variant.
  static MoAdaptData of(BuildContext context) {
    final MoAdaptData? data = maybeOf(context);
    assert(data != null,
        'MoAdapt.of() was called with a context that has no MoAdapt ancestor.');
    return data!;
  }

  /// The [MoAdaptData] from the closest [MoAdapt] ancestor, or null if there
  /// is none.
  static MoAdaptData? maybeOf(BuildContext context) {
    return context
        .dependOnInheritedWidgetOfExactType<_MoAdaptScope>()
        ?.data;
  }

  double _scaleFor(Size screenSize) {
    if (!enabled || screenSize.isEmpty) {
      return 1.0;
    }
    final double widthScale = screenSize.width / designSize.width;
    final double heightScale = screenSize.height / designSize.height;
    double scale = switch (scaleMode) {
      MoAdaptScaleMode.width => widthScale,
      MoAdaptScaleMode.height => heightScale,
      MoAdaptScaleMode.min => math.min(widthScale, heightScale),
      MoAdaptScaleMode.max => math.max(widthScale, heightScale),
    };
    if (minScale != null) {
      scale = math.max(scale, minScale!);
    }
    if (maxScale != null) {
      scale = math.min(scale, maxScale!);
    }
    return scale;
  }

  @override
  Widget build(BuildContext context) {
    assert(designSize.width > 0 && designSize.height > 0,
        'designSize must have positive width and height.');
    assert(minScale == null || minScale! > 0,
        'minScale must be greater than zero.');
    assert(maxScale == null || maxScale! > 0,
        'maxScale must be greater than zero.');
    assert(minScale == null || maxScale == null || minScale! <= maxScale!,
        'minScale must not exceed maxScale.');
    // Derive metrics directly from the FlutterView so MoAdapt works whether
    // or not an ambient MediaQuery exists, and rebuilds on metric changes
    // (resize, rotation, keyboard).
    return MediaQuery.fromView(
      view: View.of(context),
      child: Builder(builder: _buildScaled),
    );
  }

  Widget _buildScaled(BuildContext context) {
    final MediaQueryData mediaQuery = MediaQuery.of(context);
    final Size screenSize = mediaQuery.size;
    final double scale = _scaleFor(screenSize);
    final Size adaptedSize =
        Size(screenSize.width / scale, screenSize.height / scale);

    return MediaQuery(
      // Present all metrics in design-space units so that SafeArea, dialogs,
      // scaffold keyboard avoidance, and MediaQuery-driven layouts agree with
      // the scaled coordinate system.
      data: mediaQuery.copyWith(
        size: adaptedSize,
        devicePixelRatio: mediaQuery.devicePixelRatio * scale,
        padding: mediaQuery.padding / scale,
        viewPadding: mediaQuery.viewPadding / scale,
        viewInsets: mediaQuery.viewInsets / scale,
        systemGestureInsets: mediaQuery.systemGestureInsets / scale,
        displayFeatures: <ui.DisplayFeature>[
          for (final ui.DisplayFeature feature in mediaQuery.displayFeatures)
            ui.DisplayFeature(
              bounds: Rect.fromLTRB(
                feature.bounds.left / scale,
                feature.bounds.top / scale,
                feature.bounds.right / scale,
                feature.bounds.bottom / scale,
              ),
              type: feature.type,
              state: feature.state,
            ),
        ],
      ),
      child: _MoAdaptScope(
        data: MoAdaptData(
          scale: scale,
          designSize: designSize,
          screenSize: screenSize,
          adaptedSize: adaptedSize,
        ),
        // Lay the subtree out at the design-space size, then scale it to fill
        // the screen exactly. Both axes use the same factor, so the transform
        // is uniform (no distortion), and FittedBox transforms pointer events
        // so taps land where they visually appear.
        child: FittedBox(
          fit: BoxFit.fill,
          alignment: Alignment.topLeft,
          child: SizedBox.fromSize(
            size: adaptedSize,
            child: child,
          ),
        ),
      ),
    );
  }
}

class _MoAdaptScope extends InheritedWidget {
  const _MoAdaptScope({required this.data, required super.child});

  final MoAdaptData data;

  @override
  bool updateShouldNotify(_MoAdaptScope oldWidget) => data != oldWidget.data;
}

/// Replaces the whole app while the backend reports maintenance.
///
/// Mount it in `MaterialApp.builder`, not inside a route — `builder` wraps the
/// Navigator, so the gate sits above every screen the router can reach,
/// including anything pushed after the flag flips:
///
/// ```dart
/// MaterialApp.router(
///   builder: (context, child) => MaintenanceGate(child: child!),
///   routerConfig: router,
/// )
/// ```
///
/// **It fails open.** While the first status is in flight, and if it cannot be
/// read at all — offline, endpoint down, rules denied — the app runs normally.
/// A fault in the check must not be able to lock out every user at once. The
/// trade-off is the other direction: a backend that is completely unreachable
/// shows your usual error states rather than this screen.
class MaintenanceGate extends ConsumerWidget {
  /// Wraps [child], which is the app.
  const MaintenanceGate({required this.child, super.key});

  /// The app being gated.
  final Widget child;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    // `.value` rather than `when`: loading and error both read as null, and
    // null reads as "up". That single `??` is the fail-open rule.
    final status = ref.watch(maintenanceStatusProvider).value ??
        const MaintenanceStatus.up();

    if (!status.isActive) return child;

    // Replaced, not covered. With no Navigator mounted there is nothing left
    // to tap, nothing for the back button to pop, and no route that can push
    // itself on top of the gate. In-memory state goes with it, which is the
    // point — everyone is meant to be out.
    return MaintenanceView(status: status);
  }
}

/// The screen shown in place of the app.
///
/// Public so your own route can reuse it, and so the gate stays one `if`. It
/// is [ErrorView] in a [Scaffold] — restyle it here rather than teaching the
/// gate about layout.
class MaintenanceView extends ConsumerWidget {
  /// Renders [status] full-screen.
  const MaintenanceView({required this.status, super.key});

  /// The status that closed the gate, for its title and message.
  final MaintenanceStatus status;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return Scaffold(
      body: SafeArea(
        child: ErrorView(
          icon: Icons.construction_outlined,
          title: status.title ?? 'Under maintenance',
          message: status.message ??
              'The app is unavailable for a moment while we finish some work. '
              'Please try again shortly.',
          // Re-reads the flag. Harmless on a live listener, and the only way
          // out for a source that is polled.
          onRetry: () => ref.invalidate(maintenanceStatusProvider),
        ),
      ),
    );
  }
}

/// The app's logger — call sites talk to this, not to the `logger` package.
final appLogger = AppLogger._();

class AppLogger {
  AppLogger._([this._tag]);

  final String? _tag;

  /// A logger that stamps every record with `[name]`, so logs stay filterable.
  ///
  /// ```dart
  /// final _log = appLogger.scoped('FCM');
  /// _log.i('Token refreshed'); // [FCM] Token refreshed
  /// ```
  AppLogger scoped(String name) => AppLogger._(name);

  /// The noisiest level — debug builds only.
  void t(String message, {Object? error, StackTrace? stackTrace}) =>
      _write(Level.trace, message, error, stackTrace);

  void d(String message, {Object? error, StackTrace? stackTrace}) =>
      _write(Level.debug, message, error, stackTrace);

  void i(String message, {Object? error, StackTrace? stackTrace}) =>
      _write(Level.info, message, error, stackTrace);

  void w(String message, {Object? error, StackTrace? stackTrace}) =>
      _write(Level.warning, message, error, stackTrace);

  void e(String message, {Object? error, StackTrace? stackTrace}) =>
      _write(Level.error, message, error, stackTrace);

  void _write(
    Level level,
    String message,
    Object? error,
    StackTrace? stackTrace,
  ) {
    _logger.log(
      level,
      _tag == null ? message : '[$_tag] $message',
      error: error,
      stackTrace: stackTrace,
    );
  }
}

final _logger = Logger(
  // One line per record in release — it is headed for Crashlytics breadcrumbs
  // and device logs, where PrettyPrinter's box art is only noise.
  printer: kReleaseMode
      ? SimplePrinter(printTime: true, colors: false)
      : PrettyPrinter(
          methodCount: 0,
          errorMethodCount: 12,
          colors: true,
          printEmojis: true,
          dateTimeFormat: DateTimeFormat.onlyTimeAndSinceStart,
        ),
  output: MultiOutput(_sinks),
  // Warnings and errors survive into release; use Level.off to silence it.
  level: kReleaseMode ? Level.warning : Level.trace,
);

/// Writes through `dart:developer`, so DevTools' Logging view gets one
/// filterable record per event instead of a wall of console text.
class _DeveloperOutput extends LogOutput {
  @override
  void output(OutputEvent event) {
    developer.log(
      _redact(event.lines.join('\n')),
      name: 'app',
      time: event.origin.time,
      level: _developerLevels[event.level] ?? 0,
    );
  }
}

/// `dart:developer` grades severity on package:logging's scale, which [Level]
/// does not line up with.
const _developerLevels = <Level, int>{
  Level.trace: 300,
  Level.debug: 500,
  Level.info: 800,
  Level.warning: 900,
  Level.error: 1000,
  Level.fatal: 1200,
};

/// Every sink runs this, so a stray `appLogger.d(response.data.toString())`
/// cannot put a credential in the logs.
final _sensitiveKeyPattern = RegExp(
  r'("?(?:password|newPassword|token|authorization|refreshToken|accessToken)"?\s*:\s*)'
  r'("[^"]*"|[^,}\]\n]+)',
  caseSensitive: false,
);

final _bearerPattern = RegExp(r'Bearer\s+\S+', caseSensitive: false);

String _redact(String message) => message
    .replaceAllMapped(
      _sensitiveKeyPattern,
      (match) => '${match.group(1)}***REDACTED***',
    )
    .replaceAll(_bearerPattern, 'Bearer ***REDACTED***');

/// Watches the one `config/maintenance` document.
///
/// A live listener, so flipping the flag empties every open app within a
/// second — no restart, no polling, one document read per change per device.
///
/// The rule for it has to allow **unauthenticated** reads:
///
/// ```
/// match /config/maintenance {
///   allow read: if true;
///   allow write: if false;   // console or admin SDK only
/// }
/// ```
///
/// A rule requiring sign-in would hide the flag from signed-out users, who are
/// exactly the ones you cannot afford to let through during an outage — and
/// the denial fails open.
final maintenanceStatusProvider = StreamProvider<MaintenanceStatus>((ref) {
  return ref
      .watch(firebaseDbProvider)
      .collection('config')
      .doc('maintenance')
      .snapshots()
      .map((snapshot) {
        final data = snapshot.data();
        if (data == null) return const MaintenanceStatus.up();
        return MaintenanceStatus.fromMap(data);
      });
});

/// What a value is meant to be — drives the rule and the tidying it gets.
enum InputType {
  text,
  email,
  url,
  phone,
  password,
  username,
  number,
  creditCard,
  cardExpiry,
  cvv,
  filePath;

  /// How the type is named in a message — 'card number', not 'creditCard'.
  String get label => switch (this) {
    InputType.text => 'text',
    InputType.email => 'email',
    InputType.url => 'URL',
    InputType.phone => 'phone number',
    InputType.password => 'password',
    InputType.username => 'username',
    InputType.number => 'number',
    InputType.creditCard => 'card number',
    InputType.cardExpiry => 'expiry date',
    InputType.cvv => 'security code',
    InputType.filePath => 'file path',
  };
}

/// The outcome of validating one value.
class ValidationResult {
  const ValidationResult({
    required this.isValid,
    required this.sanitizedValue,
    this.error,
  });

  /// A value that passed, carrying its cleaned form.
  factory ValidationResult.valid(String sanitized) =>
      ValidationResult(isValid: true, sanitizedValue: sanitized);

  /// A value that failed, keeping the original so it can be shown back.
  factory ValidationResult.invalid(String error, String original) =>
      ValidationResult(isValid: false, sanitizedValue: original, error: error);

  final bool isValid;

  /// Trimmed and normalised for its type — what you store. Untouched on
  /// failure.
  final String sanitizedValue;

  /// A message to show under the field, or null when [isValid].
  final String? error;

  @override
  String toString() => isValid
      ? 'ValidationResult.valid($sanitizedValue)'
      : 'ValidationResult.invalid($error)';
}

/// The rule [InputType.password] is checked against. Set
/// [ValidationService.passwordPolicy] once at startup to change it app-wide.
class PasswordPolicy {
  const PasswordPolicy({
    this.minLength = 6,
    this.maxLength = 128,
    this.requiredClasses = 3,
  });

  final int minLength;
  final int maxLength;

  /// How many of upper case, lower case, digit and symbol must appear (0-4).
  final int requiredClasses;

  /// Length over composition, in the spirit of NIST 800-63B.
  static const PasswordPolicy lengthOnly = PasswordPolicy(
    minLength: 12,
    requiredClasses: 0,
  );
}

/// Validates and cleans user input.
///
/// It does not screen for SQL keywords — a blocklist rejects real input like
/// "O'Brien" and buys no safety, since parameterised queries stop injection.
/// It does not HTML-escape either: Flutter renders text, so escaping on the
/// way in corrupts stored values. Use [escapeHtml] where you build HTML.
class ValidationService {
  const ValidationService._();

  /// The rule [InputType.password] is measured against. Assign once at startup.
  static PasswordPolicy passwordPolicy = const PasswordPolicy();

  static final _emailRegex = RegExp(
    r"^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$",
  );
  static final _usernameRegex = RegExp(r'^[a-zA-Z0-9_-]{3,20}$');
  static final _phoneShapeRegex = RegExp(r'^\+?[\d\-() .]+$');
  static final _cvvRegex = RegExp(r'^\d{3,4}$');

  static final _upperRegex = RegExp(r'[A-Z]');
  static final _lowerRegex = RegExp(r'[a-z]');
  static final _digitRegex = RegExp(r'[0-9]');
  static final _symbolRegex = RegExp(r'[^A-Za-z0-9]');

  static final _nonDigits = RegExp(r'\D');
  static final _whitespace = RegExp(r'\s');

  /// Stripped rather than rejected — they arrive by paste accident, and there
  /// is nothing a user can do about an error naming them.
  static final _controlChars = RegExp(r'[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]');

  static final _markupPatterns = [
    RegExp(
      r'<script|javascript:|data:text/html|onerror\s*=|onload\s*=|onclick\s*=|<iframe',
      caseSensitive: false,
    ),
  ];

  static final _pathTraversalPatterns = [RegExp(r'\.\./|\.\.\\|%2e%2e')];

  /// Checks [value] against the rule for [inputType].
  ///
  /// An empty value passes — whether a field is required is the form's call.
  /// Order is clean, length, safety, shape; the first failure is returned.
  static ValidationResult validate(
    String value, {
    required InputType inputType,
    int minLength = 1,
    int maxLength = 1000,
    bool trimWhitespace = true,
  }) {
    if (value.isEmpty) return ValidationResult.valid(value);

    final cleaned = _clean(value, inputType, trim: trimWhitespace);

    if (cleaned.isEmpty) {
      return ValidationResult.invalid('Cannot be blank', value);
    }
    if (cleaned.length < minLength) {
      return ValidationResult.invalid(
        'Must be at least $minLength characters',
        value,
      );
    }
    if (cleaned.length > maxLength) {
      return ValidationResult.invalid(
        'Must be at most $maxLength characters',
        value,
      );
    }

    final unsafe = _unsafeReason(cleaned, inputType);
    if (unsafe != null) return ValidationResult.invalid(unsafe, value);

    final wrongShape = _shapeError(cleaned, inputType);
    if (wrongShape != null) return ValidationResult.invalid(wrongShape, value);

    return ValidationResult.valid(cleaned);
  }

  /// Tidying only — it never removes characters that would have made the value
  /// invalid, so a bad value still fails instead of being repaired.
  static String _clean(String value, InputType type, {required bool trim}) {
    final withoutControls = value.replaceAll(_controlChars, '');

    // A password is opaque — trimming would measure the wrong string.
    if (type == InputType.password) return withoutControls;

    final cleaned = trim ? withoutControls.trim() : withoutControls;

    return switch (type) {
      InputType.email => cleaned.replaceAll(_whitespace, '').toLowerCase(),
      InputType.url ||
      InputType.username => cleaned.replaceAll(_whitespace, ''),
      _ => cleaned,
    };
  }

  /// The safety checks, each scoped to the type it applies to.
  static String? _unsafeReason(String value, InputType type) {
    if (type == InputType.filePath) {
      for (final pattern in _pathTraversalPatterns) {
        if (pattern.hasMatch(value)) {
          return 'Contains a path traversal sequence';
        }
      }
    }

    // Markup matters for values that end up inside a WebView or an HTML mail.
    // The false-positive rate on prose is near zero, so free text keeps it.
    if (type == InputType.text) {
      for (final pattern in _markupPatterns) {
        if (pattern.hasMatch(value)) return 'Contains scripts or markup';
      }
    }

    return null;
  }

  /// Whether the value is shaped like its type. Returns the message, or null
  /// when it is fine.
  static String? _shapeError(String value, InputType type) => switch (type) {
    InputType.email =>
      value.length <= 254 && _emailRegex.hasMatch(value)
          ? null
          : 'Invalid ${type.label}',
    InputType.url => _urlError(value),
    InputType.phone => _phoneError(value),
    InputType.username =>
      _usernameRegex.hasMatch(value)
          ? null
          : 'Use 3-20 letters, numbers, - or _',
    InputType.password => _passwordError(value),
    InputType.number =>
      num.tryParse(value) == null ? 'Invalid ${type.label}' : null,
    InputType.creditCard => _cardError(value),
    InputType.cardExpiry => _expiryError(value),
    InputType.cvv =>
      _cvvRegex.hasMatch(value.replaceAll(_nonDigits, ''))
          ? null
          : 'Invalid ${type.label}',
    InputType.text || InputType.filePath => null,
  };

  static String? _urlError(String value) {
    final uri = Uri.tryParse(value);
    if (uri == null || !uri.hasScheme) return 'Invalid URL';

    // Checked before the host so a `javascript:` or `file:` URL is reported as
    // the scheme problem it is. The allowlist is the point of validating a URL.
    if (uri.scheme != 'http' && uri.scheme != 'https') {
      return 'Only http and https links are allowed';
    }
    if (uri.host.isEmpty) return 'Invalid URL';
    return null;
  }

  static String? _phoneError(String value) {
    if (!_phoneShapeRegex.hasMatch(value)) return 'Invalid phone number';

    // E.164 tops out at 15 digits, and nothing shorter than 7 is dialable.
    final digits = value.replaceAll(_nonDigits, '').length;
    return digits < 7 || digits > 15 ? 'Invalid phone number' : null;
  }

  static String? _passwordError(String value) {
    final policy = passwordPolicy;

    if (value.length < policy.minLength) {
      return 'Password must be at least ${policy.minLength} characters';
    }
    if (value.length > policy.maxLength) {
      return 'Password must be at most ${policy.maxLength} characters';
    }
    if (policy.requiredClasses <= 0) return null;

    final classes = [
      _upperRegex,
      _lowerRegex,
      _digitRegex,
      _symbolRegex,
    ].where((pattern) => pattern.hasMatch(value)).length;

    if (classes < policy.requiredClasses) {
      return 'Password needs ${policy.requiredClasses} of: an upper case '
          'letter, a lower case letter, a number, a symbol';
    }
    return null;
  }

  static String? _cardError(String value) {
    final digits = value.replaceAll(_nonDigits, '');
    if (digits.length < 13 || digits.length > 19) return 'Invalid card number';
    return luhnCheck(digits) ? null : 'Invalid card number';
  }

  /// Accepts whatever the field's mask produced — `MM/YY`, `MMYY` or `MM/YYYY`.
  static String? _expiryError(String value) {
    final digits = value.replaceAll(_nonDigits, '');
    if (digits.length != 4 && digits.length != 6) return 'Invalid expiry date';

    final month = int.parse(digits.substring(0, 2));
    if (month < 1 || month > 12) return 'Invalid expiry date';

    final year = digits.length == 4
        ? 2000 + int.parse(digits.substring(2))
        : int.parse(digits.substring(2));

    // Day 0 of the next month is the last day of this one — a card is good
    // through the end of the month it names.
    final expiresAt = DateTime(year, month + 1, 0, 23, 59, 59);
    return expiresAt.isBefore(DateTime.now()) ? 'Card has expired' : null;
  }

  /// The Luhn checksum every card number carries. Public so a payment form can
  /// use it while typing.
  static bool luhnCheck(String cardNumber) {
    var sum = 0;
    var isEven = false;

    for (var i = cardNumber.length - 1; i >= 0; i--) {
      var digit = int.tryParse(cardNumber[i]);
      if (digit == null) return false;

      if (isEven) {
        digit *= 2;
        if (digit > 9) digit -= 9;
      }

      sum += digit;
      isEven = !isEven;
    }

    return sum % 10 == 0;
  }

  /// Escapes the five characters that matter in HTML. Call it where you build
  /// HTML, not on the way into your database, or you will store the escapes.
  static String escapeHtml(String text) => text
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');

  /// Validates a whole form at once, keyed the same way as [inputs]. A key
  /// missing from [types] is invalid, so an unwired field cannot pass.
  static Map<String, ValidationResult> validateMultiple(
    Map<String, String> inputs,
    Map<String, InputType> types, {
    Map<String, int> minLengths = const {},
    Map<String, int> maxLengths = const {},
  }) {
    return {
      for (final entry in inputs.entries)
        entry.key: switch (types[entry.key]) {
          null => ValidationResult.invalid(
            'No validation type defined',
            entry.value,
          ),
          final type => validate(
            entry.value,
            inputType: type,
            minLength: minLengths[entry.key] ?? 1,
            maxLength: maxLengths[entry.key] ?? 1000,
          ),
        },
    };
  }

  /// True when every result in [results] passed — the usual "can I submit?".
  static bool allValid(Map<String, ValidationResult> results) =>
      results.values.every((result) => result.isValid);

  /// The failures only, keyed by field, ready to hand to a form.
  static Map<String, String> errorsOf(Map<String, ValidationResult> results) =>
      {
        for (final entry in results.entries)
          if (!entry.value.isValid) entry.key: entry.value.error!,
      };
}

/// Where the flag comes from. Point this at whatever your backend already has
/// — a config endpoint, a document, Remote Config — and the rest of the file
/// needs no changes.
///
/// It is a `Stream` rather than a `Future` on purpose: the gate is meant to
/// close on an app that is already running, not only at launch. If your source
/// can only be polled, emit on a `Timer.periodic` and on
/// `AppLifecycleListener(onResume:)`.
///
/// Whatever you put here, make it readable **without a token**: a signed-out
/// user still has to be told the app is down.
final maintenanceStatusProvider = StreamProvider<MaintenanceStatus>((ref) {
  return Stream.value(const MaintenanceStatus.up());
});

```

> Add rules incrementally — only suppress warnings (`-dontwarn`) for libraries you actually use. Run `./gradlew assembleRelease` and check the output for new warnings after each addition.

