/// Feedback status for [AppToast].
enum AppToastType { success, error, warning, info }

/// One consistent feedback surface for the whole app.
///
/// ```dart
/// AppToast.success(context, 'Saved');
/// AppToast.show(
///   context,
///   'Check your connection and try again.',
///   title: 'Could not save',
///   type: AppToastType.error,
///   actionLabel: 'Retry',
///   onAction: _save,
/// );
/// ```
///
/// From a Riverpod notifier you already have a context inside `ref.listen` —
/// or use `ref.listenAction`, which calls this for you.
///
/// **It draws its own card on the root [Overlay], not on a [SnackBar].** A
/// SnackBar buys positioning and timing but fixes the motion: 250ms, no scale,
/// and an exit that holds full opacity for 72% of the slide before cutting out.
/// On an outlined card with a shadow that reads as a snap rather than as a
/// dismissal, and none of it is tunable. Owning the [AnimationController] buys
/// a curve on both ends — and it lets a second toast crossfade into the card
/// already on screen instead of making the user watch a full exit first.
class AppToast {
  const AppToast._();

  /// How much of the status color tints the card's surface. Enough to be felt,
  /// not enough to fight the text on it.
  static const double _surfaceTint = 0.07;

  /// The outline, which is what gives the card an edge in both themes — a
  /// shadow alone disappears against a dark background.
  static const double _borderOpacity = 0.30;

  /// The icon chip's fill. Matches [AppLeadingIcon]'s tonal fill, so the two
  /// read as siblings.
  static const double _chipFill = 0.12;

  /// Widest the card gets. Past this a toast on a tablet becomes a banner
  /// stretched across the screen, and the eye has to travel to read six words.
  static const double _maxWidth = 480;

  /// Arriving is slower than leaving. Coming in, the card has to be noticed and
  /// read, and easing it over a third of a second is what makes it look placed
  /// rather than popped; going out it has already done its job.
  static const Duration _enterDuration = Duration(milliseconds: 320);
  static const Duration _exitDuration = Duration(milliseconds: 200);

  /// How far the card rises, as a fraction of its own height. Short on purpose:
  /// a full-height slide reads as a drawer opening, this reads as it settling.
  static const double _rise = 0.35;

  /// Paired with the rise. Growing the last few percent into place is what
  /// makes it look like it came toward the user rather than up past them.
  static const double _enterScale = 0.94;

  /// The live toast, if any. One at a time by design: a stack of toasts is a
  /// log, and a log belongs on a screen rather than over one.
  static OverlayEntry? _entry;
  static ValueNotifier<_ToastSpec>? _live;

  /// Registered by the live overlay so [dismiss] can reach it without a key.
  static VoidCallback? _hideCurrent;

  static void show(
    BuildContext context,
    String message, {
    AppToastType type = AppToastType.info,
    String? title,
    Duration duration = const Duration(seconds: 4),
    String? actionLabel,
    VoidCallback? onAction,
    bool showClose = false,
  }) {
    final overlay = Overlay.maybeOf(context, rootOverlay: true);
    if (overlay == null) return;

    _feedback(type);

    final spec = _ToastSpec(
      message: message,
      title: title,
      type: type,
      duration: duration,
      actionLabel: actionLabel,
      onAction: onAction,
      showClose: showClose,
    );

    // A toast already on screen takes the new content where it stands. Playing
    // its exit first would make the user watch 200ms of a message they have
    // been replaced out of before the one they asked for starts arriving.
    final live = _live;
    if (_entry != null && live != null) {
      live.value = spec;
      return;
    }

    final notifier = ValueNotifier<_ToastSpec>(spec);
    final entry = OverlayEntry(
      builder: (_) => _ToastOverlay(spec: notifier, onGone: _release),
    );
    _live = notifier;
    _entry = entry;
    overlay.insert(entry);
  }

  static void success(BuildContext context, String message, {String? title}) =>
      show(context, message, title: title, type: AppToastType.success);

  static void error(BuildContext context, String message, {String? title}) =>
      show(context, message, title: title, type: AppToastType.error);

  static void warning(BuildContext context, String message, {String? title}) =>
      show(context, message, title: title, type: AppToastType.warning);

  static void info(BuildContext context, String message, {String? title}) =>
      show(context, message, title: title, type: AppToastType.info);

  /// Takes the current toast off screen early — for a screen that is about to
  /// be popped, or an action whose result has already been shown another way.
  /// It animates out; nothing happens if there is no toast up.
  static void dismiss() => _hideCurrent?.call();

  /// Called by the overlay once the card is off screen. Pulling the entry any
  /// earlier would cut the exit animation off at the knees.
  static void _release() {
    // Cleared before the removal so that a second call — a swipe and a timer
    // landing on the same frame — cannot remove the same entry twice.
    final entry = _entry;
    _entry = null;
    // The notifier belongs to the overlay from insertion on, and is disposed
    // there — the widget still has to unsubscribe from it after this runs.
    _live = null;
    entry?.remove();
  }

  /// Called when the overlay goes away without the exit ever running: the route
  /// under it popped, the navigator replaced, a hot restart. The entry died
  /// with its Overlay, so there is nothing to remove — but left pointing at a
  /// disposed notifier, [show] would treat every later toast as a replacement
  /// for a card that no longer exists and quietly do nothing.
  ///
  /// Identity-checked because the exit path nulls these fields a frame before
  /// the widget is disposed, and a toast shown in that gap owns them by then.
  static void _forget(ValueNotifier<_ToastSpec> spec) {
    if (!identical(_live, spec)) return;
    _entry = null;
    _live = null;
  }

  /// A toast usually lands while the user is looking somewhere else, so it
  /// says what happened by feel as well as by color — the worse the news, the
  /// heavier the tap.
  static void _feedback(AppToastType type) => switch (type) {
        AppToastType.success => HapticFeedback.lightImpact(),
        AppToastType.warning => HapticFeedback.mediumImpact(),
        AppToastType.error => HapticFeedback.heavyImpact(),
        AppToastType.info => HapticFeedback.selectionClick(),
      };

  static (Color, IconData) _resolve(AppToastType type, bool isDark) =>
      switch (type) {
        AppToastType.success => (
            isDark ? AppConstants.successDark : AppConstants.success,
            Icons.check_circle_outline,
          ),
        AppToastType.error => (
            isDark ? AppConstants.errorDark : AppConstants.error,
            Icons.error_outline,
          ),
        AppToastType.warning => (
            isDark ? AppConstants.warningDark : AppConstants.warning,
            Icons.warning_amber_rounded,
          ),
        AppToastType.info => (
            isDark ? AppConstants.infoDark : AppConstants.info,
            Icons.info_outline,
          ),
      };
}

/// Everything one call to [AppToast.show] asked for, in one object so that a
/// replacement is a single assignment the live overlay can animate across.
class _ToastSpec {
  const _ToastSpec({
    required this.message,
    required this.title,
    required this.type,
    required this.duration,
    required this.actionLabel,
    required this.onAction,
    required this.showClose,
  });

  final String message;
  final String? title;
  final AppToastType type;
  final Duration duration;
  final String? actionLabel;
  final VoidCallback? onAction;
  final bool showClose;
}

/// What actually sits in the overlay: the card, its entrance and exit, its
/// timer, and the swipe that cuts both short.
class _ToastOverlay extends StatefulWidget {
  const _ToastOverlay({required this.spec, required this.onGone});

  /// Listened to rather than passed by value, so [AppToast.show] can swap the
  /// content of a card that is already up without rebuilding the entry.
  final ValueNotifier<_ToastSpec> spec;

  /// Called once the card is off screen and the entry can be pulled.
  final VoidCallback onGone;

  @override
  State<_ToastOverlay> createState() => _ToastOverlayState();
}

class _ToastOverlayState extends State<_ToastOverlay>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  late final CurvedAnimation _curve;
  Timer? _timer;
  bool _entered = false;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(vsync: this)
      ..addStatusListener(_handleStatus);
    // Out on the mirror of the way in: decelerating into place, accelerating
    // away. Reversing easeOutCubic instead would have it crawl off the screen.
    _curve = CurvedAnimation(
      parent: _controller,
      curve: Curves.easeOutCubic,
      reverseCurve: Curves.easeInCubic,
    );
    widget.spec.addListener(_handleSpecChanged);
    AppToast._hideCurrent = _hide;
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // Durations are settled here and not in initState because "reduce motion"
    // is a MediaQuery — and a controller ignores a duration changed mid-flight,
    // so they have to be right before the first forward() rather than after it.
    final reduced = MediaQuery.disableAnimationsOf(context);
    _controller
      ..duration = reduced ? Duration.zero : AppToast._enterDuration
      ..reverseDuration = reduced ? Duration.zero : AppToast._exitDuration;
    if (!_entered) {
      _entered = true;
      _controller.forward();
      _restartTimer();
    }
  }

  @override
  void dispose() {
    if (AppToast._hideCurrent == _hide) AppToast._hideCurrent = null;
    AppToast._forget(widget.spec);
    _timer?.cancel();
    widget.spec.removeListener(_handleSpecChanged);
    widget.spec.dispose();
    _curve.dispose();
    _controller.dispose();
    super.dispose();
  }

  void _handleSpecChanged() {
    _restartTimer();
    // If it was on its way out, bring it back: the entry is about to be pulled
    // out from under content that has only just been handed to it.
    _controller.forward();
    setState(() {});
  }

  /// The controller only reaches `dismissed` again by completing a reverse, so
  /// this is the exit finishing and nothing else.
  void _handleStatus(AnimationStatus status) {
    if (status == AnimationStatus.dismissed) widget.onGone();
  }

  void _restartTimer() {
    _timer?.cancel();
    _timer = Timer(widget.spec.value.duration, _hide);
  }

  void _hide() {
    _timer?.cancel();
    if (mounted) _controller.reverse();
  }

  /// A flick already carried the card off screen, so there is no exit left to
  /// play — the entry goes straight away.
  void _handleSwipe() {
    _timer?.cancel();
    widget.onGone();
  }

  @override
  Widget build(BuildContext context) {
    final media = MediaQuery.of(context);
    // Above the keyboard while there is one, above the gesture bar when there
    // is not. A toast the keyboard covers is a toast nobody reads.
    final bottomInset = media.viewInsets.bottom > 0
        ? media.viewInsets.bottom
        : media.viewPadding.bottom;
    final spec = widget.spec.value;

    return Positioned(
      left: 0,
      right: 0,
      bottom: 0,
      child: Padding(
        padding: EdgeInsets.fromLTRB(
          AppConstants.space12,
          0,
          AppConstants.space12,
          bottomInset + AppConstants.space12,
        ),
        // Bottom-center on a wide window rather than pinned to one corner. The
        // strip around the card paints nothing and so absorbs nothing: taps
        // beside the toast reach the screen underneath it.
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: AppToast._maxWidth),
            child: FadeTransition(
              opacity: _curve,
              child: SlideTransition(
                position: Tween<Offset>(
                  begin: const Offset(0, AppToast._rise),
                  end: Offset.zero,
                ).animate(_curve),
                child: ScaleTransition(
                  scale: Tween<double>(begin: AppToast._enterScale, end: 1)
                      .animate(_curve),
                  // Grows out of the edge it rose from, not out of its middle.
                  alignment: Alignment.bottomCenter,
                  child: Dismissible(
                    // New content is a new card as far as the drag is
                    // concerned; rekeying clears an offset left by a swipe the
                    // user started and abandoned.
                    key: ObjectKey(spec),
                    // Flick it away sideways, which is what a card at the edge
                    // of the screen invites; down would be into the bezel.
                    direction: DismissDirection.horizontal,
                    // Nothing sits below it to resize into.
                    resizeDuration: null,
                    onDismissed: (_) => _handleSwipe(),
                    child: Semantics(
                      container: true,
                      liveRegion: true,
                      child: Material(
                        // The overlay is outside the app's Material, and the
                        // action button wants one to ink into.
                        type: MaterialType.transparency,
                        // The card resolves its own colors from the context it
                        // is built in. Passing them down from show() looks
                        // equivalent and is not: it builds a frame later, and a
                        // theme that changed in between would leave a
                        // light-palette green on a dark card.
                        child: _ToastCard(
                          message: spec.message,
                          title: spec.title,
                          type: spec.type,
                          actionLabel: spec.actionLabel,
                          onAction: spec.onAction,
                          showClose: spec.showClose,
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

/// The card [AppToast] puts in the overlay. Private on purpose: a toast is
/// shown through [AppToast.show], never built by hand.
class _ToastCard extends StatelessWidget {
  const _ToastCard({
    required this.message,
    required this.title,
    required this.type,
    required this.actionLabel,
    required this.onAction,
    required this.showClose,
  });

  final String message;
  final String? title;
  final AppToastType type;
  final String? actionLabel;
  final VoidCallback? onAction;
  final bool showClose;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final colorScheme = theme.colorScheme;
    final isDark = theme.brightness == Brightness.dark;
    final (accent, icon) = AppToast._resolve(type, isDark);
    final heading = title;
    final hasAction = actionLabel != null && onAction != null;

    return Container(
      padding: const EdgeInsets.all(AppConstants.space12),
      decoration: BoxDecoration(
        // Tinted rather than colored: the status is carried by the icon and the
        // outline, so the text keeps the contrast the theme guarantees it.
        color: Color.alphaBlend(
          accent.withValues(alpha: AppToast._surfaceTint),
          isDark
              ? colorScheme.surfaceContainerHighest
              : colorScheme.surfaceContainerLowest,
        ),
        borderRadius: AppConstants.borderRadius16,
        border: Border.all(
          color: accent.withValues(alpha: AppToast._borderOpacity),
        ),
        boxShadow: [
          BoxShadow(
            color: colorScheme.shadow.withValues(alpha: isDark ? 0.45 : 0.12),
            blurRadius: AppConstants.space24,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Row(
        // Top, not center: with a title and two lines of body the icon belongs
        // beside the first line, not floating halfway down the card.
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            padding: const EdgeInsets.all(AppConstants.space8),
            decoration: BoxDecoration(
              color: accent.withValues(alpha: AppToast._chipFill),
              borderRadius: AppConstants.borderRadius8,
            ),
            child: Icon(icon, color: accent, size: AppConstants.iconSmall),
          ),
          const SizedBox(width: AppConstants.space12),
          Expanded(
            child: Padding(
              // Centers a single line against the icon chip without moving a
              // two-line one off the top.
              padding: const EdgeInsets.symmetric(vertical: AppConstants.space4),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (heading != null)
                    Text(
                      heading,
                      style: theme.textTheme.titleSmall?.copyWith(
                        color: colorScheme.onSurface,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  Text(
                    message,
                    // A toast is glanceable by definition; anything longer than
                    // this belongs in an AppBanner, which persists.
                    maxLines: 3,
                    overflow: TextOverflow.ellipsis,
                    style: theme.textTheme.bodyMedium?.copyWith(
                      color: heading == null
                          ? colorScheme.onSurface
                          : colorScheme.onSurfaceVariant,
                    ),
                  ),
                ],
              ),
            ),
          ),
          if (hasAction) ...[
            const SizedBox(width: AppConstants.space8),
            TextButton(
              onPressed: () {
                HapticFeedback.selectionClick();
                AppToast.dismiss();
                onAction!();
              },
              style: TextButton.styleFrom(
                foregroundColor: accent,
                visualDensity: VisualDensity.compact,
                padding: const EdgeInsets.symmetric(
                  horizontal: AppConstants.space12,
                ),
                shape: RoundedRectangleBorder(
                  borderRadius: AppConstants.borderRadius8,
                ),
              ),
              child: Text(
                actionLabel!,
                style: theme.textTheme.labelLarge?.copyWith(
                  color: accent,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
          ],
          if (showClose)
            IconButton(
              onPressed: AppToast.dismiss,
              icon: const Icon(Icons.close, size: AppConstants.iconSmall),
              color: colorScheme.onSurfaceVariant,
              visualDensity: VisualDensity.compact,
              tooltip: 'Dismiss',
            ),
        ],
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:just_audio/just_audio.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';

/// Where an [AppAudioPlayer] reads its audio from — one type for the three
/// things `just_audio` loads differently.
class AppAudioSource {
  /// A remote file, streamed. Progressive download — the player reports
  /// buffered progress under the playhead.
  const AppAudioSource.url(this.path) : _kind = _AppAudioKind.url;

  /// A file in the app bundle, e.g. `assets/audio/intro.mp3`. Remember the
  /// `assets:` entry in pubspec.yaml.
  const AppAudioSource.asset(this.path) : _kind = _AppAudioKind.asset;

  /// A file on the device, by absolute path — a recording, a download.
  const AppAudioSource.file(this.path) : _kind = _AppAudioKind.file;

  final String path;
  final _AppAudioKind _kind;

  @override
  bool operator ==(Object other) =>
      other is AppAudioSource && other.path == path && other._kind == _kind;

  @override
  int get hashCode => Object.hash(path, _kind);
}

enum _AppAudioKind { url, asset, file }

/// How much of the player is drawn.
///
/// - [full]: artwork and titles above, progress, then a centered transport row
///   — a screen's main player.
/// - [compact]: one row — play/pause, progress, remaining. Drops into a list
///   tile or a chat bubble.
enum AppAudioPlayerStyle { full, compact }

/// What repeats when the clip ends.
enum AppAudioRepeat { off, one }

/// An audio player built on
/// [just_audio](https://pub.dev/packages/just_audio), configured rather than
/// wired: it owns the `AudioPlayer`, loads the source, and disposes both.
///
/// ```dart
/// AppAudioPlayer(
///   source: const AppAudioSource.url('https://example.com/episode.mp3'),
///   title: 'Episode 12',
///   subtitle: 'The one about Flutter',
/// )
/// ```
///
/// Every part is switchable, so the same widget is a voice-note bubble:
///
/// ```dart
/// AppAudioPlayer(
///   source: AppAudioSource.file(recording.path),
///   style: AppAudioPlayerStyle.compact,
///   showSkip: false,       // a 6-second voice note has nothing to skip
///   showSpeed: false,
///   showTimes: true,
/// )
/// ```
///
/// It plays audio and nothing else. Lock-screen controls and audio-session
/// handling are `just_audio_background`'s job.
class AppAudioPlayer extends StatefulWidget {
  const AppAudioPlayer({
    super.key,
    required this.source,
    this.title,
    this.subtitle,
    this.artwork,
    this.style = AppAudioPlayerStyle.full,
    this.showControls = true,
    this.showSkip = true,
    this.skipBackward = const Duration(seconds: 15),
    this.skipForward = const Duration(seconds: 30),
    this.showProgress = true,
    this.allowScrub = true,
    this.showTimes = true,
    this.showRemaining = false,
    this.showSpeed = false,
    this.speeds = const [0.75, 1.0, 1.25, 1.5, 2.0],
    this.initialSpeed = 1.0,
    this.repeat = AppAudioRepeat.off,
    this.autoPlay = false,
    this.onCompleted,
    this.onError,
    this.variant,
    this.padding = AppConstants.padding16,
  });

  final AppAudioSource source;

  final String? title;
  final String? subtitle;

  /// Drawn beside the titles in [AppAudioPlayerStyle.full] — an `AppImage`,
  /// an `AppAvatar`, an icon. Sized by whatever you pass.
  final Widget? artwork;

  final AppAudioPlayerStyle style;

  /// The transport row. Off leaves a progress bar that still scrubs — a
  /// waveform-style read-only clip with a draggable playhead.
  final bool showControls;

  /// The two skip buttons either side of play/pause.
  final bool showSkip;

  /// How far the back and forward buttons jump. Podcasts conventionally go
  /// back further than they go forward, which is why these differ by default;
  /// set them equal for a symmetric transport.
  final Duration skipBackward;
  final Duration skipForward;

  /// The progress bar.
  final bool showProgress;

  /// Whether dragging the progress bar seeks. Off makes it a read-only
  /// indicator that still shows position.
  final bool allowScrub;

  /// The `0:12 / 3:40` line under the bar.
  final bool showTimes;

  /// Shows time left (`-3:28`) rather than total on the right. Position on
  /// the left is unaffected.
  final bool showRemaining;

  /// The speed button. Off is right for a voice note; on for anything long.
  final bool showSpeed;

  /// What the speed button cycles through, in order.
  final List<double> speeds;

  /// Where the cycle starts. Need not be in [speeds] — the button moves to
  /// the next value above it.
  final double initialSpeed;

  final AppAudioRepeat repeat;

  /// Starts as soon as the source is loaded. Consider whether the screen has
  /// earned that before turning it on.
  final bool autoPlay;

  /// Called once each time playback reaches the end.
  final VoidCallback? onCompleted;

  /// Called when the source fails to load or play. Without it the widget
  /// shows its own inline error line.
  final void Function(Object error)? onError;

  /// Colors the playhead, the buffered track and the transport. Null follows
  /// [AppInputConfig.defaults], like the rest of the kit.
  final AppInputVariant? variant;

  final EdgeInsetsGeometry padding;

  /// `1:05`, or `1:02:03` once there is an hour to show. Exposed because a
  /// screen showing its own duration next to a player should format it the
  /// same way.
  static String formatDuration(Duration duration) {
    final total = duration.isNegative ? Duration.zero : duration;
    final hours = total.inHours;
    final minutes = total.inMinutes.remainder(60);
    final seconds = total.inSeconds.remainder(60);
    final paddedSeconds = seconds.toString().padLeft(2, '0');
    if (hours > 0) {
      return '$hours:${minutes.toString().padLeft(2, '0')}:$paddedSeconds';
    }
    return '$minutes:$paddedSeconds';
  }

  @override
  State<AppAudioPlayer> createState() => _AppAudioPlayerState();
}

class _AppAudioPlayerState extends State<AppAudioPlayer> {
  static const double _artworkSize = 56;
  static const double _bufferedOpacity = 0.24;
  static const double _trackOpacity = 0.12;
  static const double _trackHeight = 4;
  static const double _playDimension = 56;
  static const double _skipDimension = 44;

  final AudioPlayer _player = AudioPlayer();

  /// Held rather than streamed: the slider needs a maximum on every frame,
  /// and nesting a second StreamBuilder for it would rebuild the whole
  /// transport on each position tick.
  Duration _duration = Duration.zero;

  /// Where the thumb is while a drag is in flight. Position keeps arriving
  /// from the player during a scrub, and letting it win would drag the thumb
  /// back out from under the finger.
  double? _scrubbing;

  double _speed = 1;
  Object? _error;

  StreamSubscription<PlayerState>? _stateSubscription;

  /// `completed` is a state the player *stays* in, not an event, so it
  /// arrives on every rebuild until something seeks away from the end.
  /// Without this latch [AppAudioPlayer.onCompleted] fires repeatedly.
  bool _reportedCompletion = false;

  @override
  void initState() {
    super.initState();
    _speed = widget.initialSpeed;
    _stateSubscription = _player.playerStateStream.listen((state) {
      final finished = state.processingState == ProcessingState.completed;
      if (finished && !_reportedCompletion) {
        _reportedCompletion = true;
        widget.onCompleted?.call();
      } else if (!finished) {
        _reportedCompletion = false;
      }
    });
    _load();
  }

  @override
  void didUpdateWidget(AppAudioPlayer oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.source != oldWidget.source) {
      _duration = Duration.zero;
      _scrubbing = null;
      _load();
    }
    if (widget.repeat != oldWidget.repeat) {
      _player.setLoopMode(
        widget.repeat == AppAudioRepeat.one ? LoopMode.one : LoopMode.off,
      );
    }
  }

  @override
  void dispose() {
    _stateSubscription?.cancel();
    _player.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    setState(() => _error = null);
    try {
      await _player.setLoopMode(
        widget.repeat == AppAudioRepeat.one ? LoopMode.one : LoopMode.off,
      );
      await _player.setSpeed(_speed);

      final duration = switch (widget.source._kind) {
        _AppAudioKind.url => await _player.setUrl(widget.source.path),
        _AppAudioKind.asset => await _player.setAsset(widget.source.path),
        _AppAudioKind.file => await _player.setFilePath(widget.source.path),
      };

      // The widget can be gone by the time a remote source resolves.
      if (!mounted) return;
      setState(() => _duration = duration ?? Duration.zero);
      // `play()` completes when playback *finishes*, not when it starts, so
      // awaiting it here would hold `_load` open for the length of the clip.
      if (widget.autoPlay) unawaited(_player.play());
    } catch (error) {
      if (!mounted) return;
      setState(() => _error = error);
      widget.onError?.call(error);
    }
  }

  Duration get _position {
    final scrubbing = _scrubbing;
    if (scrubbing == null) return _player.position;
    return Duration(milliseconds: scrubbing.round());
  }

  void _togglePlay(PlayerState state) {
    HapticFeedback.selectionClick();
    if (state.processingState == ProcessingState.completed) {
      // A finished clip resumes from the start rather than sitting at the end
      // doing nothing, which is what a second tap on play otherwise does.
      _player.seek(Duration.zero);
      _player.play();
      return;
    }
    state.playing ? _player.pause() : _player.play();
  }

  void _skip(Duration by) {
    HapticFeedback.selectionClick();
    final target = _player.position + by;
    if (target < Duration.zero) {
      _player.seek(Duration.zero);
      return;
    }
    _player.seek(target > _duration ? _duration : target);
  }

  void _cycleSpeed() {
    HapticFeedback.selectionClick();
    if (widget.speeds.isEmpty) return;
    final next = widget.speeds.firstWhere(
      (speed) => speed > _speed,
      orElse: () => widget.speeds.first,
    );
    setState(() => _speed = next);
    _player.setSpeed(next);
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final accent = AppInputStyle.accentOf(context, widget.variant);
    final error = _error;

    if (error != null) {
      return Padding(
        padding: widget.padding,
        child: Row(
          children: [
            Icon(
              Icons.error_outline,
              size: AppConstants.iconMedium,
              color: theme.colorScheme.error,
            ),
            const SizedBox(width: AppConstants.space12),
            Expanded(
              child: Text(
                'This audio could not be played.',
                style: theme.textTheme.bodyMedium?.copyWith(
                  color: theme.colorScheme.error,
                ),
              ),
            ),
            TextButton(onPressed: _load, child: const Text('Retry')),
          ],
        ),
      );
    }

    return Padding(
      padding: widget.padding,
      child: widget.style == AppAudioPlayerStyle.compact
          ? _buildCompact(context, theme, accent)
          : _buildFull(context, theme, accent),
    );
  }

  // ── Layouts ────────────────────────────────────────────────────────────────

  Widget _buildFull(BuildContext context, ThemeData theme, Color accent) {
    final heading = widget.title;
    final note = widget.subtitle;
    final art = widget.artwork;

    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (heading != null || note != null || art != null) ...[
          Row(
            children: [
              if (art != null) ...[
                SizedBox.square(dimension: _artworkSize, child: art),
                const SizedBox(width: AppConstants.space12),
              ],
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    if (heading != null)
                      Text(
                        heading,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.titleMedium,
                      ),
                    if (note != null)
                      Text(
                        note,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: theme.textTheme.bodySmall?.copyWith(
                          color: theme.colorScheme.onSurfaceVariant,
                        ),
                      ),
                  ],
                ),
              ),
              if (widget.showSpeed) _speedButton(theme, accent),
            ],
          ),
          const SizedBox(height: AppConstants.space12),
        ],
        if (widget.showProgress) _progress(accent),
        if (widget.showTimes) _times(theme),
        if (widget.showControls) ...[
          const SizedBox(height: AppConstants.space8),
          _transport(theme, accent),
        ],
      ],
    );
  }

  Widget _buildCompact(BuildContext context, ThemeData theme, Color accent) {
    return Row(
      children: [
        if (widget.showControls) ...[
          _playButton(theme, accent, dimension: _skipDimension),
          const SizedBox(width: AppConstants.space8),
        ],
        Expanded(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              if (widget.showProgress) _progress(accent),
              if (widget.showTimes) _times(theme),
            ],
          ),
        ),
        if (widget.showSpeed) ...[
          const SizedBox(width: AppConstants.space8),
          _speedButton(theme, accent),
        ],
      ],
    );
  }

  // ── Pieces ─────────────────────────────────────────────────────────────────

  Widget _progress(Color accent) {
    return StreamBuilder<Duration>(
      stream: _player.positionStream,
      builder: (context, snapshot) {
        final maxMs = _duration.inMilliseconds.toDouble();
        final positionMs = (snapshot.data ?? Duration.zero).inMilliseconds
            .toDouble();
        // Before the duration is known there is nothing to be a fraction of,
        // so the bar sits at zero rather than jumping when it arrives.
        final value = _scrubbing ?? (maxMs <= 0 ? 0.0 : positionMs);

        return SliderTheme(
          data: SliderTheme.of(context).copyWith(
            trackHeight: _trackHeight,
            activeTrackColor: accent,
            inactiveTrackColor: accent.withValues(alpha: _trackOpacity),
            // The buffered position rides in the secondary track, which is
            // what it is for.
            secondaryActiveTrackColor: accent.withValues(
              alpha: _bufferedOpacity,
            ),
            thumbColor: accent,
            overlayColor: accent.withValues(alpha: _trackOpacity),
            thumbShape: widget.allowScrub
                ? null
                : SliderComponentShape.noThumb,
            overlayShape: widget.allowScrub
                ? null
                : SliderComponentShape.noOverlay,
          ),
          child: StreamBuilder<Duration>(
            stream: _player.bufferedPositionStream,
            builder: (context, buffered) {
              return Slider(
                value: value.clamp(0, maxMs <= 0 ? 1 : maxMs),
                max: maxMs <= 0 ? 1 : maxMs,
                secondaryTrackValue: (buffered.data ?? Duration.zero)
                    .inMilliseconds
                    .toDouble()
                    .clamp(0, maxMs <= 0 ? 1 : maxMs),
                onChanged: widget.allowScrub && maxMs > 0
                    ? (v) => setState(() => _scrubbing = v)
                    : null,
                onChangeEnd: widget.allowScrub && maxMs > 0
                    ? (v) {
                        _player.seek(Duration(milliseconds: v.round()));
                        setState(() => _scrubbing = null);
                      }
                    : null,
              );
            },
          ),
        );
      },
    );
  }

  Widget _times(ThemeData theme) {
    final style = theme.textTheme.labelSmall?.copyWith(
      color: theme.colorScheme.onSurfaceVariant,
    );

    return StreamBuilder<Duration>(
      stream: _player.positionStream,
      builder: (context, snapshot) {
        final position = _scrubbing != null
            ? _position
            : (snapshot.data ?? Duration.zero);
        final trailing = widget.showRemaining
            ? '-${AppAudioPlayer.formatDuration(_duration - position)}'
            : AppAudioPlayer.formatDuration(_duration);

        return Padding(
          padding: const EdgeInsets.symmetric(
            horizontal: AppConstants.space4,
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(AppAudioPlayer.formatDuration(position), style: style),
              Text(trailing, style: style),
            ],
          ),
        );
      },
    );
  }

  Widget _transport(ThemeData theme, Color accent) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        if (widget.showSkip) ...[
          _skipButton(
            theme,
            accent,
            icon: Icons.replay,
            seconds: widget.skipBackward.inSeconds,
            onTap: () => _skip(-widget.skipBackward),
          ),
          const SizedBox(width: AppConstants.space16),
        ],
        _playButton(theme, accent, dimension: _playDimension),
        if (widget.showSkip) ...[
          const SizedBox(width: AppConstants.space16),
          _skipButton(
            theme,
            accent,
            icon: Icons.refresh,
            seconds: widget.skipForward.inSeconds,
            onTap: () => _skip(widget.skipForward),
          ),
        ],
      ],
    );
  }

  Widget _playButton(
    ThemeData theme,
    Color accent, {
    required double dimension,
  }) {
    return StreamBuilder<PlayerState>(
      stream: _player.playerStateStream,
      builder: (context, snapshot) {
        final state =
            snapshot.data ?? PlayerState(false, ProcessingState.idle);
        final waiting = state.processingState == ProcessingState.loading ||
            state.processingState == ProcessingState.buffering;

        return Material(
          color: accent,
          shape: const CircleBorder(),
          clipBehavior: Clip.antiAlias,
          child: InkWell(
            // Waiting is not disabled: a buffering clip is still pausable,
            // and greying the only control out mid-stall reads as broken.
            onTap: () => _togglePlay(state),
            child: SizedBox.square(
              dimension: dimension,
              child: waiting
                  ? Padding(
                      padding: const EdgeInsets.all(AppConstants.space16),
                      child: CircularProgressIndicator(
                        strokeWidth: 2,
                        color: AppInputStyle.onAccentOf(
                          context,
                          widget.variant,
                        ),
                      ),
                    )
                  : Icon(
                      state.playing ? Icons.pause : Icons.play_arrow,
                      color: AppInputStyle.onAccentOf(context, widget.variant),
                      size: AppConstants.iconMedium,
                    ),
            ),
          ),
        );
      },
    );
  }

  Widget _skipButton(
    ThemeData theme,
    Color accent, {
    required IconData icon,
    required int seconds,
    required VoidCallback onTap,
  }) {
    return Semantics(
      button: true,
      label: '$seconds seconds',
      child: InkResponse(
        onTap: onTap,
        radius: _skipDimension / 2,
        child: SizedBox.square(
          dimension: _skipDimension,
          child: Stack(
            alignment: Alignment.center,
            children: [
              Icon(
                icon,
                size: AppConstants.iconMedium,
                color: theme.colorScheme.onSurface,
              ),
              // The number rides inside the arrow, so one glyph serves any
              // skip amount rather than needing an icon per interval.
              Text(
                '$seconds',
                style: theme.textTheme.labelSmall?.copyWith(
                  fontSize: AppConstants.fontSize11 - 2,
                  fontWeight: FontWeight.w700,
                  color: theme.colorScheme.onSurface,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _speedButton(ThemeData theme, Color accent) {
    final label = _speed == _speed.roundToDouble()
        ? '${_speed.toInt()}x'
        : '${_speed}x';

    return Semantics(
      button: true,
      label: 'Playback speed $label',
      child: InkWell(
        onTap: _cycleSpeed,
        borderRadius: AppConstants.borderRadiusFull,
        child: Padding(
          padding: const EdgeInsets.symmetric(
            horizontal: AppConstants.space12,
            vertical: AppConstants.space8,
          ),
          child: Text(
            label,
            style: theme.textTheme.labelMedium?.copyWith(
              color: accent,
              fontWeight: FontWeight.w700,
            ),
          ),
        ),
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:skeletonizer/skeletonizer.dart';

import './empty_view.dart';
import './error_view.dart';
import '../../core/errors/app_exception.dart';

/// Renders one asynchronous source as loading, failed, empty or loaded.
///
/// ```dart
/// AppAsyncView<HomeState>(
///   value: ref.watch(homeNotifierProvider),
///   onRetry: () => ref.invalidate(homeNotifierProvider),
///   isEmpty: (state) => state.items.isEmpty,
///   skeleton: (context) => _body(context, HomeState.placeholder),
///   builder: _body,
/// )
/// ```
///
/// [AppAsyncView.stream] and [AppAsyncView.future] take a raw source instead,
/// for data that never became a provider. It builds inline, not as a route, so
/// a [Scaffold] keeps its app bar while the content loads. Once there is
/// something to show, a later reload leaves it on screen rather than swapping
/// it for a spinner.
class AppAsyncView<T> extends StatelessWidget {
  /// Renders the [AsyncValue] a provider handed back.
  const AppAsyncView({
    super.key,
    required AsyncValue<T> value,
    required this.builder,
    this.skeleton,
    this.isEmpty,
    this.emptyTitle,
    this.emptyMessage,
    this.emptyIcon,
    this.emptyActionLabel,
    this.onEmptyAction,
    this.errorTitle,
    this.errorMessage,
    this.onRetry,
  })  : _value = value,
        _stream = null,
        _future = null;

  /// Subscribes to [stream] for as long as this widget lives. Reopening a dead
  /// stream means rebuilding with a new one, so [onRetry] is the caller's job.
  const AppAsyncView.stream({
    super.key,
    required Stream<T> stream,
    required this.builder,
    this.skeleton,
    this.isEmpty,
    this.emptyTitle,
    this.emptyMessage,
    this.emptyIcon,
    this.emptyActionLabel,
    this.onEmptyAction,
    this.errorTitle,
    this.errorMessage,
    this.onRetry,
  })  : _stream = stream,
        _value = null,
        _future = null;

  /// Awaits [future] and renders the result. A future runs once, so a retry
  /// means handing over a new one from [onRetry].
  const AppAsyncView.future({
    super.key,
    required Future<T> future,
    required this.builder,
    this.skeleton,
    this.isEmpty,
    this.emptyTitle,
    this.emptyMessage,
    this.emptyIcon,
    this.emptyActionLabel,
    this.onEmptyAction,
    this.errorTitle,
    this.errorMessage,
    this.onRetry,
  })  : _future = future,
        _value = null,
        _stream = null;

  /// Exactly one of these is set, by the constructor that was used.
  final AsyncValue<T>? _value;
  final Stream<T>? _stream;
  final Future<T>? _future;

  /// Builds the loaded state.
  final Widget Function(BuildContext context, T data) builder;

  /// The shape to shimmer while the first load runs, e.g.
  /// `(context) => _body(context, HomeState.placeholder)`. Null shows a
  /// centered spinner instead.
  ///
  /// It must be built from *fake* data, not an empty state — Skeletonizer
  /// traces the tree it is handed, so a `ListView.builder` over nothing traces
  /// to a blank screen. States from `moarch create feature` carry a
  /// `placeholder` for this.
  final WidgetBuilder? skeleton;

  /// Whether loaded data counts as nothing to show. Null means it never does.
  final bool Function(T data)? isEmpty;

  /// Copy for the empty state. Null keeps [EmptyView]'s own wording.
  final String? emptyTitle;
  final String? emptyMessage;
  final IconData? emptyIcon;
  final String? emptyActionLabel;
  final VoidCallback? onEmptyAction;

  /// Copy for the failed state. [errorMessage] overrides the exception's own.
  final String? errorTitle;
  final String? errorMessage;

  /// Passing this is what puts the retry button in [ErrorView]. Usually
  /// `() => ref.invalidate(theProvider)`.
  final VoidCallback? onRetry;

  /// Anything that is not an [AppException] shows no detail on purpose —
  /// `error.toString()` tells the user nothing and leaks internals.
  String? _messageFor(Object error) =>
      errorMessage ??
      switch (error) {
        AppException(:final message) => message,
        _ => null,
      };

  @override
  Widget build(BuildContext context) {
    final value = _value;
    if (value != null) return _render(context, value);

    return _AsyncSource<T>(
      stream: _stream,
      future: _future,
      builder: _render,
    );
  }

  Widget _render(BuildContext context, AsyncValue<T> value) {
    // `hasValue` rather than `when`: it separates "still waiting for the first
    // result" from "already showing one and fetching again".
    if (!value.hasValue) {
      final error = value.error;
      if (error != null && !value.isLoading) {
        return ErrorView(
          title: errorTitle ?? 'Something went wrong',
          message: _messageFor(error),
          onRetry: onRetry,
        );
      }
      final shape = skeleton;
      if (shape == null) {
        return const Center(child: CircularProgressIndicator.adaptive());
      }
      return Skeletonizer(child: shape(context));
    }

    // Non-null by `hasValue`, and the cast keeps a nullable T honest: a
    // provider of `String?` can hold null *as its value*, and that is data.
    final data = value.value as T;

    if (isEmpty?.call(data) ?? false) {
      return EmptyView(
        title: emptyTitle ?? 'Nothing here yet',
        message: emptyMessage ?? 'No items are available right now.',
        icon: emptyIcon ?? Icons.inbox_outlined,
        actionLabel: emptyActionLabel,
        onAction: onEmptyAction,
      );
    }

    return builder(context, data);
  }
}

/// Turns a [Stream] or a [Future] into the [AsyncValue] [AppAsyncView] draws,
/// carrying the last data forward so an error never wipes the screen.
class _AsyncSource<T> extends StatefulWidget {
  const _AsyncSource({
    required this.builder,
    this.stream,
    this.future,
  });

  final Stream<T>? stream;
  final Future<T>? future;
  final Widget Function(BuildContext context, AsyncValue<T> value) builder;

  @override
  State<_AsyncSource<T>> createState() => _AsyncSourceState<T>();
}

class _AsyncSourceState<T> extends State<_AsyncSource<T>> {
  // Not `const`: a constant cannot be built out of a type parameter.
  AsyncValue<T> _value = AsyncValue<T>.loading();
  StreamSubscription<T>? _subscription;

  /// The future currently being awaited — a superseded one still completes,
  /// and its late result is not ours to show.
  Future<T>? _pending;

  @override
  void initState() {
    super.initState();
    _subscribe();
  }

  @override
  void didUpdateWidget(covariant _AsyncSource<T> oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.stream != oldWidget.stream || widget.future != oldWidget.future) {
      _unsubscribe();
      _subscribe();
    }
  }

  @override
  void dispose() {
    _unsubscribe();
    super.dispose();
  }

  void _unsubscribe() {
    _subscription?.cancel();
    _subscription = null;
    _pending = null;
  }

  void _subscribe() {
    // A new source is a load, not a blank screen.
    _value = AsyncValue<T>.loading().copyWithPrevious(_value);

    final stream = widget.stream;
    if (stream != null) {
      _subscription = stream.listen(
        (data) => _emit(AsyncValue<T>.data(data)),
        onError: (Object error, StackTrace stackTrace) =>
            _emit(AsyncValue<T>.error(error, stackTrace)),
      );
      return;
    }

    final future = widget.future;
    if (future == null) return;
    _pending = future;
    unawaited(
      future.then(
        (data) => _emit(AsyncValue<T>.data(data), from: future),
        onError: (Object error, StackTrace stackTrace) =>
            _emit(AsyncValue<T>.error(error, stackTrace), from: future),
      ),
    );
  }

  /// Records [next] over what came before. [from] is checked for futures,
  /// whose results arrive whether or not anyone is still waiting for them.
  void _emit(AsyncValue<T> next, {Future<T>? from}) {
    if (!mounted) return;
    if (from != null && !identical(from, _pending)) return;
    setState(() => _value = next.copyWithPrevious(_value));
  }

  @override
  Widget build(BuildContext context) => widget.builder(context, _value);
}

import 'dart:async';
import '../../core/errors/app_exception.dart';
import 'package:dio/dio.dart';
import 'package:connectivity_plus/connectivity_plus.dart';


Future<T> safeApiCall<T>({
  required Future<T> Function() apiCall,
  FutureOr<T>? Function()? onNoInternet, // optional cache fallback
}) async {
  final connectivityResult = await Connectivity().checkConnectivity();

  if (connectivityResult.contains(ConnectivityResult.none)) {
    if (onNoInternet != null) {
      final fallback = await onNoInternet();
      if (fallback != null) return fallback;
    }
    throw AppException.noInternet();
  }

  try {
    return await apiCall();
  } on DioException catch (e) {
    throw AppException.fromDioError(e);
  } catch (e, s) {
    throw AppException.fromError(e, s);
  }
}

