/// One attachment held by an [AppFilePickerField].
///
/// Deliberately not a `file_picker` or `image_picker` type — nothing here
/// imports a picker package, so the widget adds no dependency.
class AppPickedFile {
  const AppPickedFile({required this.name, this.path, this.sizeBytes});

  final String name;

  /// Where the bytes are, when they are on disk. A file chosen on the web has
  /// no path, and the field simply shows no preview for it.
  final String? path;

  final int? sizeBytes;

  /// Lower-case extension without the dot, or empty when the name has none.
  String get extension {
    final dot = name.lastIndexOf('.');
    return dot <= 0 ? '' : name.substring(dot + 1).toLowerCase();
  }

  /// Whether this can be drawn as a thumbnail.
  bool get isImage =>
      const {'jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'heic'}
          .contains(extension);

  /// Size as a person reads it — "480 KB", "1.2 MB".
  String? get readableSize {
    final bytes = sizeBytes;
    if (bytes == null) return null;
    if (bytes < 1024) return '$bytes B';
    if (bytes < 1024 * 1024) return '${(bytes / 1024).round()} KB';
    return '${(bytes / (1024 * 1024)).toStringAsFixed(1)} MB';
  }

  /// The icon that stands in for a file with no thumbnail.
  IconData get icon => switch (extension) {
    'pdf' => Icons.picture_as_pdf_outlined,
    'doc' || 'docx' || 'txt' || 'rtf' => Icons.description_outlined,
    'xls' || 'xlsx' || 'csv' => Icons.table_chart_outlined,
    'zip' || 'rar' || '7z' => Icons.folder_zip_outlined,
    'mp3' || 'wav' || 'm4a' => Icons.audiotrack_outlined,
    'mp4' || 'mov' || 'avi' => Icons.movie_outlined,
    _ => Icons.insert_drive_file_outlined,
  };
}

/// A field whose value is a list of attachments: an area that opens the app's
/// own picker, and a row per file with a thumbnail and a remove button.
///
/// The picking belongs to the caller — this is the field, not the plugin.
///
/// ```dart
/// AppFilePickerField(
///   label: 'Documents',
///   files: _files,
///   maxFiles: 3,
///   required: true,
///   onPick: () async {
///     final picked = await ref.read(mediaServiceProvider).pickFiles();
///     return [for (final f in picked) AppPickedFile(name: f.name, path: f.path)];
///   },
///   onChanged: (files) => setState(() => _files = files),
/// )
/// ```
class AppFilePickerField extends StatelessWidget {
  const AppFilePickerField({
    super.key,
    required this.label,
    required this.files,
    required this.onPick,
    required this.onChanged,
    this.hint = 'Add a file',
    this.maxFiles,
    this.enabled = true,
    this.required = false,
    this.validator,
    this.autovalidateMode,
    this.labelMode,
    this.variant,
    this.type,
    this.shape,
    this.size,
  });

  final String label;

  /// The attachments held right now. The caller owns them, as with every other
  /// field in the family.
  final List<AppPickedFile> files;

  /// Opens whatever picker the app uses and resolves to what was chosen.
  /// Returning null or an empty list leaves the field alone, so a cancelled
  /// picker costs nothing.
  final Future<List<AppPickedFile>?> Function() onPick;

  /// Called with the complete new list, added or removed.
  final ValueChanged<List<AppPickedFile>> onChanged;

  /// Copy on the add area.
  final String hint;

  /// Ceiling on how many may be held. At the limit the add area disappears
  /// rather than offering a pick the field would have to throw away.
  final int? maxFiles;

  final bool enabled;

  /// Marks the label, and — unless [validator] replaces the rule — rejects an
  /// empty field when the form validates.
  final bool required;

  /// Replaces the built-in rule entirely. Receives the current files.
  final String? Function(List<AppPickedFile> files)? validator;

  final AutovalidateMode? autovalidateMode;

  /// Null follows [AppInputConfig.defaults].
  final AppInputLabelMode? labelMode;
  final AppInputVariant? variant;
  final AppInputType? type;
  final AppInputShape? shape;
  final AppInputSize? size;

  /// The rule applied when no [validator] is given: a required field holds at
  /// least one file, and no more than [max] are held.
  static String? validate(
    List<AppPickedFile> files, {
    bool required = false,
    int? max,
  }) {
    if (required && files.isEmpty) return 'This field is required';
    if (max != null && files.length > max) {
      return 'Attach no more than $max file${max == 1 ? '' : 's'}';
    }
    return null;
  }

  bool get _atLimit => maxFiles != null && files.length >= maxFiles!;

  String? _validate() {
    final rule = validator;
    return rule != null
        ? rule(files)
        : validate(files, required: required, max: maxFiles);
  }

  Future<void> _add(FormFieldState<List<AppPickedFile>> state) async {
    HapticFeedback.selectionClick();
    final picked = await onPick();
    if (picked == null || picked.isEmpty) return;

    // Trims at the ceiling rather than refusing the whole pick: someone who
    // selected five images for three slots meant to attach three.
    final next = [...files, ...picked];
    final limited = maxFiles == null ? next : next.take(maxFiles!).toList();
    state.didChange(limited);
    onChanged(limited);
  }

  void _remove(int index, FormFieldState<List<AppPickedFile>> state) {
    HapticFeedback.selectionClick();
    final next = [...files]..removeAt(index);
    state.didChange(next);
    onChanged(next);
  }

  @override
  Widget build(BuildContext context) {
    return InputFieldLayout(
      label: label,
      required: required,
      labelMode: labelMode,
      variant: variant,
      size: size,
      field: FormField<List<AppPickedFile>>(
        initialValue: files,
        enabled: enabled,
        autovalidateMode:
            autovalidateMode ?? AppInputStyle.config.autovalidateMode,
        validator: (_) => _validate(),
        builder: (state) {
          final error = state.errorText;
          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              for (var i = 0; i < files.length; i++)
                _FileRow(
                  file: files[i],
                  variant: variant,
                  onRemove: enabled ? () => _remove(i, state) : null,
                ),
              if (enabled && !_atLimit) _addArea(context, state, error != null),
              if (error != null)
                Padding(
                  padding: const EdgeInsets.only(
                    top: AppConstants.space4,
                    left: AppConstants.space12,
                  ),
                  child: Text(
                    error,
                    style: context.textTheme.bodySmall?.copyWith(
                      color: context.colorScheme.error,
                    ),
                  ),
                ),
            ],
          );
        },
      ),
    );
  }

  /// The tappable area that opens the picker. Dashed-looking rather than a
  /// filled field: it is an action, and it should not read as a value.
  Widget _addArea(
    BuildContext context,
    FormFieldState<List<AppPickedFile>> state,
    bool hasError,
  ) {
    final accent = AppInputStyle.accentOf(context, variant);
    final borderColor = hasError
        ? context.colorScheme.error
        : accent.withValues(alpha: AppInputStyle.config.idleBorderOpacity);

    return Semantics(
      button: true,
      label: hint,
      child: InkWell(
        onTap: () => _add(state),
        borderRadius: AppConstants.borderRadius12,
        child: Container(
          width: double.infinity,
          padding: AppConstants.padding16,
          decoration: BoxDecoration(
            borderRadius: AppConstants.borderRadius12,
            border: Border.all(
              color: borderColor,
              width: AppInputStyle.config.idleBorderWidth,
            ),
            color: accent.withValues(alpha: AppInputStyle.config.fillOpacity),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            spacing: AppConstants.space8,
            children: [
              Icon(
                Icons.attach_file,
                size: AppInputStyle.configOf(size).iconSize,
                color: accent,
              ),
              Text(
                hint,
                style: AppInputStyle.textStyle(
                  context,
                  size: size,
                )?.copyWith(color: accent, fontWeight: FontWeight.bold),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// One attachment: thumbnail or type icon, name, size, and a remove button.
class _FileRow extends StatelessWidget {
  const _FileRow({required this.file, required this.onRemove, this.variant});

  final AppPickedFile file;
  final VoidCallback? onRemove;
  final AppInputVariant? variant;

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);
    final size = file.readableSize;

    return Padding(
      padding: const EdgeInsets.only(bottom: AppConstants.space8),
      child: Row(
        spacing: AppConstants.space12,
        children: [
          ClipRRect(
            borderRadius: AppConstants.borderRadius8,
            child: SizedBox.square(
              dimension: AppConstants.touchTarget,
              child: _thumbnail(context, accent),
            ),
          ),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  file.name,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: context.textTheme.bodyMedium,
                ),
                if (size != null)
                  Text(
                    size,
                    style: context.textTheme.bodySmall?.copyWith(
                      color: context.colorScheme.onSurfaceVariant,
                    ),
                  ),
              ],
            ),
          ),
          if (onRemove != null)
            IconButton(
              onPressed: onRemove,
              tooltip: 'Remove',
              icon: const Icon(Icons.close),
            ),
        ],
      ),
    );
  }

  Widget _thumbnail(BuildContext context, Color accent) {
    final path = file.path;
    if (file.isImage && path != null) {
      return Image.file(
        File(path),
        fit: BoxFit.cover,
        // A file that has been moved or deleted since it was picked is not a
        // reason to break the row.
        errorBuilder: (context, error, stackTrace) => _icon(context, accent),
      );
    }
    return _icon(context, accent);
  }

  Widget _icon(BuildContext context, Color accent) => ColoredBox(
    color: accent.withValues(alpha: AppInputStyle.config.fillOpacity * 2),
    child: Icon(file.icon, color: accent, size: AppConstants.iconMedium),
  );
}

import 'dart:io';

import 'package:flutter_local_notifications/flutter_local_notifications.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:timezone/data/latest_all.dart' as tz;
import 'package:timezone/timezone.dart' as tz;

import '../../core/constants/app_constants.dart';
import '../../core/utils/app_logger.dart';

// Android: AndroidManifest.xml needs RECEIVE_BOOT_COMPLETED, SCHEDULE_EXACT_ALARM,
// USE_EXACT_ALARM and POST_NOTIFICATIONS.
// iOS: `moarch init` sets UNUserNotificationCenter.current().delegate in
// AppDelegate.swift. Never override userNotificationCenter(_:didReceive:)
// without calling super — that blocks the plugins from receiving taps.

final _log = appLogger.scoped('Notifications');

// Must stay top-level.
@pragma('vm:entry-point')
void _backgroundHandler(NotificationResponse response) {
  _log.i(
    'Background tap | id: ${response.id} | payload: ${response.payload}',
  );
}

enum NotificationPriority { defaultPriority, high }

/// Read this to reach the service: `ref.read(notificationServiceProvider)`.
final notificationServiceProvider = Provider<NotificationService>((ref) {
  return NotificationService(ref);
});

class NotificationService {
  NotificationService(this._ref);

  /// Read other providers from here, e.g. to navigate on tap.
  // ignore: unused_field
  final Ref _ref;

  bool _initialized = false;

  final FlutterLocalNotificationsPlugin _plugin =
      FlutterLocalNotificationsPlugin();

  static const String _defaultChannelId = 'default_channel';
  static const String _defaultChannelName = 'Default Notifications';
  static const String _defaultChannelDesc = 'General app notifications';

  static const String _scheduledChannelId = 'scheduled_channel';
  static const String _scheduledChannelName = 'Scheduled Notifications';
  static const String _scheduledChannelDesc = 'Reminders and scheduled alerts';

  static const String _highPriorityChannelId = 'high_priority_channel';
  static const String _highPriorityChannelName = 'High Priority';
  static const String _highPriorityChannelDesc = 'Urgent notifications';

  static const int defaultId = 0;
  static const int scheduledId = 1;
  static const int periodicId = 2;

  Future<void> init() async {
    if (_initialized) return;

    tz.initializeTimeZones();

    const androidSettings = AndroidInitializationSettings(
      '@mipmap/ic_launcher',
    );

    const iosSettings = DarwinInitializationSettings(
      requestAlertPermission: false, // Asked for in requestPermissions().
      requestBadgePermission: false,
      requestSoundPermission: false,
    );

    const initSettings = InitializationSettings(
      android: androidSettings,
      iOS: iosSettings,
    );

    await _plugin.initialize(
      settings: initSettings,
      onDidReceiveNotificationResponse: (response) {
        _log.i(
          'Tapped | id: ${response.id} | payload: ${response.payload}',
        );
      },
      onDidReceiveBackgroundNotificationResponse: _backgroundHandler,
    );

    await _createNotificationChannels();

    _initialized = true;
    _log.i('Initialized');

    await requestPermissions();
  }

  Future<void> _createNotificationChannels() async {
    if (!Platform.isAndroid) return;

    final androidPlugin =
        _plugin.resolvePlatformSpecificImplementation<
          AndroidFlutterLocalNotificationsPlugin
        >();

    await androidPlugin?.createNotificationChannel(
      const AndroidNotificationChannel(
        _defaultChannelId,
        _defaultChannelName,
        description: _defaultChannelDesc,
        importance: Importance.defaultImportance,
        playSound: true,
      ),
    );

    await androidPlugin?.createNotificationChannel(
      const AndroidNotificationChannel(
        _scheduledChannelId,
        _scheduledChannelName,
        description: _scheduledChannelDesc,
        importance: Importance.high,
        playSound: true,
      ),
    );

    await androidPlugin?.createNotificationChannel(
      const AndroidNotificationChannel(
        _highPriorityChannelId,
        _highPriorityChannelName,
        description: _highPriorityChannelDesc,
        importance: Importance.max,
        playSound: true,
        enableLights: true,
        enableVibration: true,
      ),
    );
  }

  /// Ask for notification permission — call it after onboarding, not on boot.
  Future<bool> requestPermissions() async {
    if (Platform.isIOS) {
      final ios = _plugin.resolvePlatformSpecificImplementation<
          IOSFlutterLocalNotificationsPlugin>();
      return await ios?.requestPermissions(
            alert: true,
            badge: true,
            sound: true,
          ) ??
          false;
    }

    if (Platform.isAndroid) {
      final android = _plugin.resolvePlatformSpecificImplementation<
          AndroidFlutterLocalNotificationsPlugin>();
      return await android?.requestNotificationsPermission() ?? false;
    }

    return false;
  }

  /// Show a notification right now.
  Future<void> show({
    int id = defaultId,
    required String title,
    required String body,
    String? payload,
    NotificationPriority priority = NotificationPriority.defaultPriority,
  }) async {
    _ensureInit();
    await _plugin.show(
      id: id,
      title: title,
      body: body,
      notificationDetails: _buildDetails(priority),
      payload: payload,
    );
    _log.i('Shown (id: $id)');
  }

  /// Schedule at an exact [scheduledDate].
  ///
  /// [timeZoneName] is an IANA name like 'Europe/Lisbon'; defaults to local.
  Future<void> scheduleAt({
    int id = scheduledId,
    required String title,
    required String body,
    required DateTime scheduledDate,
    String? payload,
    String? timeZoneName,
  }) async {
    _ensureInit();

    final location =
        timeZoneName != null ? tz.getLocation(timeZoneName) : tz.local;
    final tzDate = tz.TZDateTime.from(scheduledDate, location);

    await _plugin.zonedSchedule(
      id: id,
      title: title,
      body: body,
      scheduledDate: tzDate,
      notificationDetails: _buildScheduledDetails(),
      androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
      payload: payload,
    );

    _log.i('Scheduled at $tzDate (id: $id)');
  }

  /// Schedule a notification [delay] from now.
  Future<void> scheduleAfter({
    int id = scheduledId,
    required String title,
    required String body,
    Duration delay = const Duration(seconds: 5),
    String? payload,
  }) async {
    await scheduleAt(
      id: id,
      title: title,
      body: body,
      scheduledDate: DateTime.now().add(delay),
      payload: payload,
    );
  }

  /// Schedule a daily notification at [hour]:[minute].
  Future<void> scheduleDailyAt({
    int id = scheduledId,
    required String title,
    required String body,
    required int hour,
    required int minute,
    String? payload,
  }) async {
    _ensureInit();
    await _plugin.zonedSchedule(
      id: id,
      title: title,
      body: body,
      scheduledDate: _nextInstanceOfTime(hour, minute),
      notificationDetails: _buildScheduledDetails(),
      androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
      matchDateTimeComponents: DateTimeComponents.time,
      payload: payload,
    );
    _log.i('Daily scheduled at $hour:$minute (id: $id)');
  }

  /// Schedule a weekly notification on [day]
  /// (DateTime.monday..DateTime.sunday) at [hour]:[minute].
  Future<void> scheduleWeeklyAt({
    int id = scheduledId,
    required String title,
    required String body,
    required int day,
    required int hour,
    required int minute,
    String? payload,
  }) async {
    _ensureInit();
    await _plugin.zonedSchedule(
      id: id,
      title: title,
      body: body,
      scheduledDate: _nextInstanceOfDay(day, hour, minute),
      notificationDetails: _buildScheduledDetails(),
      androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
      matchDateTimeComponents: DateTimeComponents.dayOfWeekAndTime,
      payload: payload,
    );
    _log.i(
      'Weekly scheduled (day $day at $hour:$minute, id: $id)',
    );
  }

  /// Show a repeating notification at a fixed [interval].
  Future<void> showPeriodic({
    int id = periodicId,
    required String title,
    required String body,
    RepeatInterval interval = RepeatInterval.hourly,
    String? payload,
  }) async {
    _ensureInit();

    await _plugin.periodicallyShow(
      id: id,
      title: title,
      body: body,
      repeatInterval: interval,
      notificationDetails: _buildDetails(NotificationPriority.defaultPriority),
      androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle,
      payload: payload,
    );

    _log.i('Periodic ($interval) started (id: $id)');
  }

  /// Cancel a specific notification by [id].
  Future<void> cancel(int id) async {
    await _plugin.cancel(id: id);
    _log.i('Cancelled (id: $id)');
  }

  /// Cancel all pending and shown notifications.
  Future<void> cancelAll() async {
    await _plugin.cancelAll();
    _log.i('Cancelled all');
  }

  /// Notifications that are scheduled but not yet shown.
  Future<List<PendingNotificationRequest>> getPending() =>
      _plugin.pendingNotificationRequests();

  NotificationDetails _buildDetails(NotificationPriority priority) {
    final isHigh = priority == NotificationPriority.high;

    return NotificationDetails(
      android: AndroidNotificationDetails(
        isHigh ? _highPriorityChannelId : _defaultChannelId,
        isHigh ? _highPriorityChannelName : _defaultChannelName,
        channelDescription: isHigh ? _highPriorityChannelDesc : _defaultChannelDesc,
        importance: isHigh ? Importance.max : Importance.defaultImportance,
        priority: isHigh ? Priority.high : Priority.defaultPriority,
        ticker: 'ticker',
        color: AppConstants.primary,
      ),
      iOS: DarwinNotificationDetails(
        presentAlert: true,
        presentBadge: true,
        presentSound: isHigh,
        interruptionLevel: isHigh
            ? InterruptionLevel.timeSensitive
            : InterruptionLevel.active,
      ),
    );
  }

  NotificationDetails _buildScheduledDetails() {
    return const NotificationDetails(
      android: AndroidNotificationDetails(
        _scheduledChannelId,
        _scheduledChannelName,
        channelDescription: _scheduledChannelDesc,
        importance: Importance.high,
        priority: Priority.high,
      ),
      iOS: DarwinNotificationDetails(
        presentAlert: true,
        presentBadge: true,
        presentSound: true,
      ),
    );
  }

  tz.TZDateTime _nextInstanceOfTime(int hour, int minute) {
    final tz.TZDateTime now = tz.TZDateTime.now(tz.local);
    tz.TZDateTime scheduledDate = tz.TZDateTime(
      tz.local,
      now.year,
      now.month,
      now.day,
      hour,
      minute,
    );
    if (scheduledDate.isBefore(now)) {
      scheduledDate = scheduledDate.add(const Duration(days: 1));
    }
    return scheduledDate;
  }

  tz.TZDateTime _nextInstanceOfDay(int day, int hour, int minute) {
    tz.TZDateTime scheduledDate = _nextInstanceOfTime(hour, minute);
    while (scheduledDate.weekday != day) {
      scheduledDate = scheduledDate.add(const Duration(days: 1));
    }
    return scheduledDate;
  }

  void _ensureInit() {
    if (!_initialized) {
      throw StateError(
        'NotificationService not initialized. '
        'Call ref.read(notificationServiceProvider).init() first.',
      );
    }
  }
}

