import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// Color role of [AppIconButton]. Mirrors [AppButtonVariant] and
/// [AppLeadingIconVariant] so every control speaks the same color vocabulary.
enum AppIconButtonVariant { primary, secondary, tertiary, danger }

/// Fill treatment of [AppIconButton] — how the variant color is applied.
///
/// - [filled]: solid variant background, contrasting icon.
/// - [tonal]: soft variant-tinted background, variant-colored icon.
/// - [outlined]: transparent background, variant-colored border + icon.
/// - [ghost]: no container at all — just the variant-colored icon.
enum AppIconButtonType { filled, tonal, outlined, ghost }

/// Corner shape of the tap target.
enum AppIconButtonShape { rounded, circle }

enum AppIconButtonSize { small, medium, large }

typedef _IconButtonSizeConfig = ({double container, double icon});

/// A tappable icon — [AppLeadingIcon]'s interactive sibling. Same color
/// vocabulary, but with a ripple, haptics, a loading state and a real touch
/// target. Use [AppLeadingIcon] when the icon is decoration, this when it does
/// something.
class AppIconButton extends StatelessWidget {
  const AppIconButton({
    super.key,
    required this.icon,
    this.onPressed,
    this.variant = AppIconButtonVariant.primary,
    this.type = AppIconButtonType.ghost,
    this.shape = AppIconButtonShape.circle,
    this.size = AppIconButtonSize.medium,
    this.tooltip,
    this.isLoading = false,
    this.color,
  });

  final IconData icon;

  /// Tap handler. Pass null to render the button in its disabled state.
  final VoidCallback? onPressed;
  final AppIconButtonVariant variant;
  final AppIconButtonType type;
  final AppIconButtonShape shape;
  final AppIconButtonSize size;

  /// Long-press label. Worth setting on every icon button — an icon on its own
  /// rarely names itself, and screen readers have nothing else to read.
  final String? tooltip;

  /// Replaces the icon with a spinner and ignores taps, keeping the same size
  /// so the surrounding layout doesn't jump.
  final bool isLoading;

  /// Overrides [variant]'s accent color. For the control that has to match a
  /// color the variant vocabulary doesn't name — a status tint, say. Reach for
  /// a [variant] first; this is the escape hatch.
  final Color? color;

  static const double _tonalFillOpacity = 0.12;
  static const double _outlinedBorderWidth = 1.5;
  static const double _disabledOpacity = 0.38;

  /// The tap target's outer dimension for [size]. Public so a layout that has
  /// to reserve room for the button — an AppBar's leading slot, say — can size
  /// that slot instead of guessing at it.
  static double dimensionOf(AppIconButtonSize size) => switch (size) {
        AppIconButtonSize.small => 32.0,
        AppIconButtonSize.medium => AppConstants.touchTarget,
        AppIconButtonSize.large => AppConstants.touchTarget + 16,
      };

  _IconButtonSizeConfig _sizeConfig() => (
        container: dimensionOf(size),
        icon: switch (size) {
          AppIconButtonSize.small => AppConstants.iconSmall,
          AppIconButtonSize.medium => AppConstants.iconMedium,
          AppIconButtonSize.large => AppConstants.iconLarge,
        },
      );

  /// The accent color, plus the color that reads on top of it.
  (Color, Color) _colorsOf(ThemeData theme) {
    final override = color;
    if (override != null) {
      // No colorScheme pair exists for an arbitrary color, so pick whichever
      // of black/white keeps the filled treatment legible.
      return (
        override,
        ThemeData.estimateBrightnessForColor(override) == Brightness.dark
            ? Colors.white
            : Colors.black,
      );
    }
    return switch (variant) {
      AppIconButtonVariant.primary => (
          theme.colorScheme.primary,
          theme.colorScheme.onPrimary,
        ),
      AppIconButtonVariant.secondary => (
          theme.colorScheme.secondary,
          theme.colorScheme.onSecondary,
        ),
      AppIconButtonVariant.tertiary => (
          theme.colorScheme.tertiary,
          theme.colorScheme.onTertiary,
        ),
      AppIconButtonVariant.danger => (
          theme.colorScheme.error,
          theme.colorScheme.onError,
        ),
    };
  }

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final sizeConfig = _sizeConfig();
    final (accent, onAccent) = _colorsOf(theme);
    final enabled = onPressed != null && !isLoading;

    // Variant chooses the color; type only decides how that color is applied.
    final (backgroundColor, foregroundColor) = switch (type) {
      AppIconButtonType.filled => (accent, onAccent),
      AppIconButtonType.tonal => (
          Color.alphaBlend(
            accent.withValues(alpha: _tonalFillOpacity),
            theme.colorScheme.surface,
          ),
          accent,
        ),
      AppIconButtonType.outlined || AppIconButtonType.ghost => (
          Colors.transparent,
          accent,
        ),
    };

    // A disabled button stays its variant, just faded — never a generic grey.
    final resolvedForeground = enabled
        ? foregroundColor
        : foregroundColor.withValues(alpha: _disabledOpacity);
    final resolvedBackground = enabled
        ? backgroundColor
        : backgroundColor.withValues(alpha: _disabledOpacity);

    final border = type == AppIconButtonType.outlined
        ? BorderSide(color: resolvedForeground, width: _outlinedBorderWidth)
        : BorderSide.none;

    final button = Material(
      color: resolvedBackground,
      clipBehavior: Clip.antiAlias,
      shape: shape == AppIconButtonShape.circle
          ? CircleBorder(side: border)
          : RoundedRectangleBorder(
              borderRadius: AppConstants.borderRadius12,
              side: border,
            ),
      child: InkWell(
        onTap: enabled
            ? () {
                HapticFeedback.selectionClick();
                onPressed!();
              }
            : null,
        child: SizedBox.square(
          dimension: sizeConfig.container,
          child: isLoading
              ? Center(
                  child: SizedBox.square(
                    dimension: sizeConfig.icon,
                    child: CircularProgressIndicator(
                      strokeWidth: 2,
                      color: resolvedForeground,
                    ),
                  ),
                )
              : Icon(icon, size: sizeConfig.icon, color: resolvedForeground),
        ),
      ),
    );

    if (tooltip == null) return button;
    return Tooltip(message: tooltip!, child: button);
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// Color role of [AppTextButton] — what the action is about, not how it is
/// drawn. Mirrors [AppButtonVariant].
///
/// [neutral] follows the theme's `onSurface`, for actions that are offered
/// without being urged: "Skip", "Not now", "Cancel".
enum AppTextButtonVariant { primary, secondary, tertiary, danger, neutral }

/// How the [AppTextButtonVariant] color is applied. Orthogonal to variant and
/// size — any combination works.
///
/// - [plain]: bare colored label, the quietest.
/// - [underlined]: the inline-link look, for an action inside a sentence —
///   pair it with `bare: true` to drop the button box around it.
/// - [tonal]: label on a soft tinted pill, findable at a glance.
enum AppTextButtonType { plain, underlined, tonal }

/// Corner shape of the [AppTextButtonType.tonal] pill. Ignored by the other
/// two types, which paint no container to shape.
enum AppTextButtonShape { rounded, pill }

enum AppTextButtonSize { small, medium, large }

typedef _TextButtonSizeConfig = ({
  double fontSize,
  double iconSize,
  double minHeight,
  EdgeInsets padding,
});

/// A text-first action: the label *is* the button. [AppButton]'s quiet
/// sibling, for the choice that shouldn't compete with the screen's main one.
///
/// ```dart
/// AppTextButton(
///   label: 'Forgot password?',
///   variant: AppTextButtonVariant.primary,
///   type: AppTextButtonType.underlined,
///   bare: true,
///   alignment: Alignment.centerRight,
///   onPressed: () => context.push('/reset'),
/// )
/// ```
class AppTextButton extends StatelessWidget {
  const AppTextButton({
    super.key,
    required this.label,
    this.onPressed,
    this.variant = AppTextButtonVariant.primary,
    this.type = AppTextButtonType.plain,
    this.shape = AppTextButtonShape.rounded,
    this.size = AppTextButtonSize.medium,
    this.prefixIcon,
    this.suffixIcon,
    this.isLoading = false,
    this.color,
    this.fontWeight,
    this.maxLines = 1,
    this.expand = false,
    this.alignment,
    this.dense = false,
    this.bare = false,
    this.tooltip,
  });

  final String label;

  /// Tap handler. Pass null to render the button in its disabled state.
  final VoidCallback? onPressed;
  final AppTextButtonVariant variant;
  final AppTextButtonType type;

  /// Only read by [AppTextButtonType.tonal] — the other types have no
  /// container to shape.
  final AppTextButtonShape shape;
  final AppTextButtonSize size;
  final IconData? prefixIcon;
  final IconData? suffixIcon;

  /// Replaces the label with a spinner and ignores taps. The button keeps the
  /// exact width the label gave it, so a row of actions doesn't reflow.
  final bool isLoading;

  /// Overrides [variant]'s color — the escape hatch for a tint the variant
  /// vocabulary doesn't name.
  final Color? color;

  /// Defaults to semi-bold, which is what keeps a bare label reading as
  /// something tappable rather than as more text.
  final FontWeight? fontWeight;

  /// Lines the label may wrap onto before it ellipsizes. One by default.
  final int maxLines;

  /// Stretches the button across its parent. Off by default: a text action
  /// normally takes only the room its label needs.
  final bool expand;

  /// Where the label sits. Setting it also gives the button the parent's width
  /// to align inside of, so `Alignment.centerRight` puts the label on the right
  /// of the row or column it sits in rather than only inside its own box.
  /// Defaults to centered.
  final Alignment? alignment;

  /// Drops the 48dp touch target and the padding, for an action that has to
  /// sit tight against something else. Keep it for already-tappable rows.
  final bool dense;

  /// Drops the button itself — no padding, no minimum size, no ripple, no
  /// container — leaving the label and its tap handler. What an underlined
  /// link needs to sit inline with the text around it, where a button's box
  /// would show. Makes [dense], [shape] and the [AppTextButtonType.tonal] fill
  /// moot: there is nothing left to pad, shape or paint.
  final bool bare;

  /// Long-press label. Worth setting when the label is abbreviated by
  /// [maxLines] on a narrow screen.
  final String? tooltip;

  static const double _tonalFillOpacity = 0.12;
  static const double _disabledOpacity = 0.38;
  static const FontWeight _defaultWeight = FontWeight.w600;

  _TextButtonSizeConfig _sizeConfig() => switch (size) {
        AppTextButtonSize.small => (
            fontSize: AppConstants.fontSize13,
            iconSize: 16.0,
            minHeight: 32.0,
            padding: const EdgeInsets.symmetric(
              horizontal: AppConstants.space8,
              vertical: AppConstants.space4,
            ),
          ),
        AppTextButtonSize.medium => (
            fontSize: AppConstants.fontSize15,
            iconSize: 18.0,
            minHeight: 40.0,
            padding: const EdgeInsets.symmetric(
              horizontal: AppConstants.space12,
              vertical: AppConstants.space8,
            ),
          ),
        AppTextButtonSize.large => (
            fontSize: AppConstants.fontSize17,
            iconSize: 20.0,
            minHeight: AppConstants.touchTarget,
            padding: const EdgeInsets.symmetric(
              horizontal: AppConstants.space16,
              vertical: AppConstants.space12,
            ),
          ),
      };

  /// The variant's color, plus the color that reads on top of it. Single
  /// source for every color the button paints.
  (Color, Color) _colorsOf(ThemeData theme) {
    final override = color;
    if (override != null) {
      // No colorScheme pair exists for an arbitrary color, so pick whichever
      // of black/white keeps a tonal fill legible.
      return (
        override,
        ThemeData.estimateBrightnessForColor(override) == Brightness.dark
            ? Colors.white
            : Colors.black,
      );
    }
    return switch (variant) {
      AppTextButtonVariant.primary => (
          theme.colorScheme.primary,
          theme.colorScheme.onPrimary,
        ),
      AppTextButtonVariant.secondary => (
          theme.colorScheme.secondary,
          theme.colorScheme.onSecondary,
        ),
      AppTextButtonVariant.tertiary => (
          theme.colorScheme.tertiary,
          theme.colorScheme.onTertiary,
        ),
      AppTextButtonVariant.danger => (
          theme.colorScheme.error,
          theme.colorScheme.onError,
        ),
      AppTextButtonVariant.neutral => (
          theme.colorScheme.onSurface,
          theme.colorScheme.surface,
        ),
    };
  }

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final sizeConfig = _sizeConfig();
    final (accent, _) = _colorsOf(theme);
    final enabled = onPressed != null && !isLoading;

    // Variant chooses the color; type only decides how that color is applied.
    // Only the tonal type paints anything behind the label.
    final background = switch (type) {
      AppTextButtonType.tonal => Color.alphaBlend(
          accent.withValues(alpha: _tonalFillOpacity),
          theme.colorScheme.surface,
        ),
      AppTextButtonType.plain || AppTextButtonType.underlined =>
        Colors.transparent,
    };

    // A disabled button stays its variant, just faded — never a generic grey.
    final foreground =
        enabled ? accent : accent.withValues(alpha: _disabledOpacity);
    final resolvedBackground = enabled
        ? background
        : background.withValues(alpha: _disabledOpacity);

    final textStyle = theme.textTheme.labelLarge?.copyWith(
          color: foreground,
          fontSize: sizeConfig.fontSize,
          fontWeight: fontWeight ?? _defaultWeight,
          decoration: type == AppTextButtonType.underlined
              ? TextDecoration.underline
              : TextDecoration.none,
        ) ??
        TextStyle(
          color: foreground,
          fontSize: sizeConfig.fontSize,
          fontWeight: fontWeight ?? _defaultWeight,
        );

    // The alignment has to reach the row and the label too: a row that always
    // centers, holding a label that always centers, pins the text to the middle
    // of a stretched button whatever the button's own alignment says.
    final resolvedAlignment = alignment ?? Alignment.center;
    final (rowAlignment, textAlign) = switch (resolvedAlignment.x) {
      < 0 => (MainAxisAlignment.start, TextAlign.left),
      > 0 => (MainAxisAlignment.end, TextAlign.right),
      _ => (MainAxisAlignment.center, TextAlign.center),
    };

    final content = Row(
      mainAxisSize: expand ? MainAxisSize.max : MainAxisSize.min,
      mainAxisAlignment: rowAlignment,
      children: [
        if (prefixIcon != null) ...[
          Icon(prefixIcon, size: sizeConfig.iconSize, color: foreground),
          const SizedBox(width: AppConstants.space4),
        ],
        // Flexible + ellipsis so a label wider than the room it is given
        // truncates instead of overflowing the row it sits in.
        Flexible(
          child: Text(
            label,
            maxLines: maxLines,
            overflow: TextOverflow.ellipsis,
            textAlign: textAlign,
            style: textStyle,
          ),
        ),
        if (suffixIcon != null) ...[
          const SizedBox(width: AppConstants.space4),
          Icon(suffixIcon, size: sizeConfig.iconSize, color: foreground),
        ],
      ],
    );

    final handleTap = enabled
        ? () {
            HapticFeedback.selectionClick();
            onPressed!();
          }
        : null;

    final child = isLoading
        // Stacked under a transparent copy of the label so the button keeps
        // the exact width it had, and the row around it doesn't jump.
        ? Stack(
            alignment: resolvedAlignment,
            children: [
              Opacity(opacity: 0, child: content),
              SizedBox.square(
                dimension: sizeConfig.iconSize,
                child: CircularProgressIndicator(
                  strokeWidth: 2,
                  color: foreground,
                ),
              ),
            ],
          )
        : content;

    // Nothing around the label: no padding to fake away, no minimum size, no
    // ripple, no shape — the label is the whole widget, and the tap is on it.
    if (bare) {
      final bareButton = MouseRegion(
        cursor: enabled ? SystemMouseCursors.click : MouseCursor.defer,
        child: GestureDetector(
          // Only the label takes the tap. An opaque box would take the whole
          // width a stretched parent hands down, so a tap far to the side of a
          // short link would still fire it.
          behavior: HitTestBehavior.deferToChild,
          onTap: handleTap,
          child: child,
        ),
      );
      return _wrap(bareButton);
    }

    final button = TextButton(
      onPressed: handleTap,
      style: TextButton.styleFrom(
        backgroundColor: resolvedBackground,
        disabledBackgroundColor: resolvedBackground,
        foregroundColor: foreground,
        disabledForegroundColor: foreground,
        padding: dense ? EdgeInsets.zero : sizeConfig.padding,
        alignment: resolvedAlignment,
        // A dense button gives up its 48dp target for the layout's sake; every
        // other one keeps a target a finger can actually land on.
        minimumSize: dense ? Size.zero : Size(0, sizeConfig.minHeight),
        tapTargetSize:
            dense ? MaterialTapTargetSize.shrinkWrap : MaterialTapTargetSize.padded,
        shape: RoundedRectangleBorder(
          borderRadius: switch (shape) {
            AppTextButtonShape.rounded => AppConstants.borderRadius8,
            AppTextButtonShape.pill => AppConstants.borderRadiusFull,
          },
        ),
      ),
      child: child,
    );

    return _wrap(button);
  }

  /// Gives [button] the width [expand] and [alignment] ask for, then the
  /// tooltip. Shared by the bare label and the real button.
  Widget _wrap(Widget button) {
    final sized =
        expand ? SizedBox(width: double.infinity, child: button) : button;
    // A button only as wide as its label has nothing to align inside of, so an
    // alignment claims the width the parent offers to align against. In an
    // unbounded parent — a Row, a scrolling Column — Align shrink-wraps, so
    // this costs nothing where there is no room to move into.
    final aligned = alignment != null && !expand
        ? Align(alignment: alignment!, child: sized)
        : sized;
    if (tooltip == null) return aligned;
    return Tooltip(message: tooltip!, child: aligned);
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// Fill treatment of the sheet's close button.
///
/// Mirrors `AppIconButtonType`'s naming so it reads like the rest of the kit.
/// It is redeclared here rather than imported because this widget ships with
/// `moarch init` and AppIconButton does not — an init widget can only lean on
/// other init widgets.
enum AppSheetCloseType { filled, tonal, outlined, ghost }

/// The standard inside of a bottom sheet: a rounded surface panel with a drag
/// handle (grabber) at the top, an optional [title], an optional close button,
/// and your [child].
/// Pass this as the `child` to `AppBottomModals.showAppBottomModal`.
class AppBottomSheetScaffold extends StatelessWidget {
  const AppBottomSheetScaffold({
    super.key,
    required this.child,
    this.title,
    this.showHandle = true,
    this.padding = AppConstants.paddingPage,
    this.titleAlign = TextAlign.center,
    this.handleWidth = 40,
    this.handleHeight = 4,
    this.handleColor,
    this.showClose = false,
    this.onClose,
    this.closeIcon = Icons.close,
    this.closeType = AppSheetCloseType.tonal,
    this.closeColor,
  });

  final Widget child;
  final String? title;
  final bool showHandle;
  final EdgeInsetsGeometry padding;

  /// Centered reads as a modal, [TextAlign.start] as a panel. Pick one per app
  /// and keep to it.
  final TextAlign titleAlign;

  final double handleWidth;
  final double handleHeight;

  /// Defaults to a muted `onSurfaceVariant`. Worth overriding only when the
  /// sheet sits on a colored surface.
  final Color? handleColor;

  /// Shows a close button in the sheet's top corner. The drag handle already
  /// says "dismissable" — add this when the sheet is tall enough that the
  /// handle scrolls out of reach, or when dismissal needs to be obvious.
  final bool showClose;

  /// Overrides the default `Navigator.maybePop` — e.g. to confirm unsaved work.
  final VoidCallback? onClose;

  final IconData closeIcon;

  /// How the close button wears [closeColor]. Tonal gives the soft grey circle
  /// most sheets want; [AppSheetCloseType.ghost] is a bare glyph.
  final AppSheetCloseType closeType;

  /// Defaults to `onSurfaceVariant` — a close button is chrome, not an action,
  /// so it stays neutral unless you say otherwise.
  final Color? closeColor;

  /// Matches AppIconButton's `small` tap target, so a sheet close and an icon
  /// button elsewhere in the app are the same size.
  static const double _closeDimension = 32;
  static const double _closeTonalOpacity = 0.12;
  static const double _closeBorderWidth = 1.5;
  static const double _handleOpacity = 0.4;

  Widget _buildClose(BuildContext context, ThemeData theme) {
    final accent = closeColor ?? theme.colorScheme.onSurfaceVariant;
    final (background, foreground) = switch (closeType) {
      AppSheetCloseType.filled => (accent, theme.colorScheme.surface),
      AppSheetCloseType.tonal => (
          Color.alphaBlend(
            accent.withValues(alpha: _closeTonalOpacity),
            theme.colorScheme.surface,
          ),
          accent,
        ),
      AppSheetCloseType.outlined || AppSheetCloseType.ghost => (
          Colors.transparent,
          accent,
        ),
    };

    return Tooltip(
      message: MaterialLocalizations.of(context).closeButtonTooltip,
      child: Material(
        color: background,
        clipBehavior: Clip.antiAlias,
        shape: CircleBorder(
          side: closeType == AppSheetCloseType.outlined
              ? BorderSide(color: accent, width: _closeBorderWidth)
              : BorderSide.none,
        ),
        child: InkWell(
          onTap: () {
            HapticFeedback.selectionClick();
            if (onClose != null) {
              onClose!();
            } else {
              Navigator.maybePop(context);
            }
          },
          child: SizedBox.square(
            dimension: _closeDimension,
            child: Icon(
              closeIcon,
              size: AppConstants.iconSmall,
              color: foreground,
            ),
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    return Container(
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: const BorderRadius.vertical(
          top: Radius.circular(AppConstants.radius24),
        ),
      ),
      child: SafeArea(
        top: false,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (showHandle)
              Center(
                child: Container(
                  margin: const EdgeInsets.only(top: AppConstants.space12),
                  width: handleWidth,
                  height: handleHeight,
                  decoration: BoxDecoration(
                    color: handleColor ??
                        theme.colorScheme.onSurfaceVariant
                            .withValues(alpha: _handleOpacity),
                    borderRadius: AppConstants.borderRadiusFull,
                  ),
                ),
              ),
            Padding(
              padding: padding,
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  if (title != null || showClose) ...[
                    // A Stack rather than a Row: it keeps a centered title
                    // centered on the sheet instead of on the space left over
                    // beside the close button.
                    Stack(
                      alignment: AlignmentDirectional.centerEnd,
                      children: [
                        if (title != null)
                          Padding(
                            // Reserve the close button's width on both sides so
                            // a centered title doesn't drift left to avoid it.
                            padding: EdgeInsets.symmetric(
                              horizontal: showClose ? _closeDimension : 0,
                            ),
                            child: SizedBox(
                              width: double.infinity,
                              child: Text(
                                title!,
                                style: theme.textTheme.titleLarge,
                                textAlign: titleAlign,
                              ),
                            ),
                          ),
                        if (showClose) _buildClose(context, theme),
                      ],
                    ),
                    const SizedBox(height: AppConstants.space16),
                  ],
                  child,
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';
import '../buttons/app_icon_button.dart';
import '../indicators/app_tag.dart';

/// An inline status message — the calm, persistent counterpart to AppToast.
/// Use a banner for something that stays true while the screen is open
/// ("You're offline", "Verify your email"), and a toast for something that
/// just happened.
///
/// Colors come from [AppTagStatus], shared with [AppTag], so a banner and a
/// pill about the same thing read as the same thing.
class AppBanner extends StatelessWidget {
  const AppBanner({
    super.key,
    required this.message,
    this.title,
    this.status = AppTagStatus.info,
    this.icon,
    this.actionLabel,
    this.onAction,
    this.onDismiss,
    this.dismissIcon = Icons.close,
    this.dismissType = AppIconButtonType.ghost,
    this.dismissShape = AppIconButtonShape.circle,
  });

  final String message;

  /// Optional bold first line. Skip it for one-sentence banners.
  final String? title;
  final AppTagStatus status;

  /// Overrides the status's default icon.
  final IconData? icon;

  /// Inline text action — "Retry", "Verify now". Shown only when [onAction]
  /// is also set.
  final String? actionLabel;
  final VoidCallback? onAction;

  /// Shows a close button when set. Leave it null for a banner the user
  /// shouldn't be able to wave away.
  final VoidCallback? onDismiss;

  final IconData dismissIcon;

  /// How the dismiss button wears the [status] color. Ghost keeps the banner
  /// quiet; [AppIconButtonType.tonal] gives the close a soft container of its
  /// own, which helps when the banner is long enough to hunt for it.
  final AppIconButtonType dismissType;
  final AppIconButtonShape dismissShape;

  static const double _fillOpacity = 0.10;
  static const double _borderOpacity = 0.35;

  Color _colorOf(ThemeData theme) => switch (status) {
        AppTagStatus.neutral => theme.colorScheme.onSurfaceVariant,
        AppTagStatus.success => AppConstants.success,
        AppTagStatus.warning => AppConstants.warning,
        AppTagStatus.error => theme.colorScheme.error,
        AppTagStatus.info => AppConstants.info,
      };

  IconData _iconOf() => switch (status) {
        AppTagStatus.neutral => Icons.info_outline,
        AppTagStatus.success => Icons.check_circle_outline,
        AppTagStatus.warning => Icons.warning_amber_outlined,
        AppTagStatus.error => Icons.error_outline,
        AppTagStatus.info => Icons.info_outline,
      };

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final color = _colorOf(theme);

    return Container(
      padding: AppConstants.padding12,
      decoration: BoxDecoration(
        color: color.withValues(alpha: _fillOpacity),
        borderRadius: AppConstants.borderRadius12,
        border: Border.all(color: color.withValues(alpha: _borderOpacity)),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(icon ?? _iconOf(), color: color, size: AppConstants.iconMedium),
          const SizedBox(width: AppConstants.space12),
          Expanded(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                if (title != null) ...[
                  Text(
                    title!,
                    style: theme.textTheme.titleSmall?.copyWith(color: color),
                  ),
                  const SizedBox(height: 2),
                ],
                Text(
                  message,
                  style: theme.textTheme.bodyMedium?.copyWith(
                    color: theme.colorScheme.onSurface,
                  ),
                ),
                if (actionLabel != null && onAction != null) ...[
                  const SizedBox(height: AppConstants.space4),
                  // A bare text action keeps the banner quiet: it is
                  // information first, a call to action second.
                  TextButton(
                    onPressed: () {
                      HapticFeedback.selectionClick();
                      onAction!();
                    },
                    style: TextButton.styleFrom(
                      foregroundColor: color,
                      padding: EdgeInsets.zero,
                      minimumSize: Size.zero,
                      tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                    ),
                    child: Text(actionLabel!),
                  ),
                ],
              ],
            ),
          ),
          if (onDismiss != null) ...[
            const SizedBox(width: AppConstants.space4),
            AppIconButton(
              icon: dismissIcon,
              onPressed: onDismiss,
              // The banner's color comes from AppTagStatus, which the variant
              // vocabulary doesn't name — hence the explicit override.
              color: color,
              type: dismissType,
              shape: dismissShape,
              size: AppIconButtonSize.small,
              tooltip: 'Dismiss',
            ),
          ],
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';
import './app_input_style.dart';

/// A quantity stepper — "− 2 +". For picking a small count, where a slider
/// would be imprecise and a text field is overkill.
///
/// The buttons disable themselves at [min] and [max], so the value can never
/// leave the range you allow.
class AppStepper extends StatelessWidget {
  const AppStepper({
    super.key,
    required this.value,
    required this.onChanged,
    this.min = 0,
    this.max = 99,
    this.step = 1,
    this.variant,
    this.size,
  });

  final int value;

  /// Pass null to render the whole stepper disabled.
  final ValueChanged<int>? onChanged;
  final int min;
  final int max;

  /// How much one tap moves the value.
  final int step;
  final AppInputVariant? variant;
  final AppInputSize? size;

  static const double _fillOpacity = 0.06;
  static const double _borderOpacity = 0.25;
  static const double _disabledOpacity = 0.35;

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final accent = AppInputStyle.accentOf(context, variant);
    final sizeConfig = AppInputStyle.configOf(size);
    final enabled = onChanged != null;

    void emit(int next) {
      HapticFeedback.selectionClick();
      onChanged!(next.clamp(min, max));
    }

    return Container(
      decoration: BoxDecoration(
        color: accent.withValues(alpha: _fillOpacity),
        borderRadius: AppConstants.borderRadiusFull,
        border: Border.all(color: accent.withValues(alpha: _borderOpacity)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          _StepButton(
            icon: Icons.remove,
            tooltip: 'Decrease',
            color: accent,
            iconSize: sizeConfig.iconSize,
            disabledOpacity: _disabledOpacity,
            onTap: enabled && value > min ? () => emit(value - step) : null,
          ),
          ConstrainedBox(
            constraints: const BoxConstraints(minWidth: AppConstants.space32),
            child: Text(
              '$value',
              textAlign: TextAlign.center,
              style: theme.textTheme.titleMedium?.copyWith(
                fontSize: sizeConfig.fontSize,
                color: enabled
                    ? theme.colorScheme.onSurface
                    : theme.colorScheme.onSurface
                        .withValues(alpha: _disabledOpacity),
              ),
            ),
          ),
          _StepButton(
            icon: Icons.add,
            tooltip: 'Increase',
            color: accent,
            iconSize: sizeConfig.iconSize,
            disabledOpacity: _disabledOpacity,
            onTap: enabled && value < max ? () => emit(value + step) : null,
          ),
        ],
      ),
    );
  }
}

class _StepButton extends StatelessWidget {
  const _StepButton({
    required this.icon,
    required this.tooltip,
    required this.color,
    required this.iconSize,
    required this.disabledOpacity,
    required this.onTap,
  });

  final IconData icon;

  /// Names the button. A bare glyph tells a screen reader nothing, and "−" and
  /// "+" are exactly the two a stepper cannot afford to have confused.
  final String tooltip;

  final Color color;
  final double iconSize;
  final double disabledOpacity;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    return Tooltip(
      message: tooltip,
      child: Semantics(
        button: true,
        enabled: onTap != null,
        label: tooltip,
        child: InkWell(
          customBorder: const CircleBorder(),
          onTap: onTap,
          child: ConstrainedBox(
            // Material's minimum tap target. The glyph alone left it at 40.
            constraints: const BoxConstraints(
              minWidth: AppConstants.touchTarget,
              minHeight: AppConstants.touchTarget,
            ),
            child: Icon(
              icon,
              size: iconSize,
              color: onTap == null
                  ? color.withValues(alpha: disabledOpacity)
                  : color,
            ),
          ),
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';

/// How big an item is along the section's own axis. [fit] lets the child size
/// itself; the named sizes come from [AppDragSizes].
enum AppDragSize { fit, small, medium, large }

/// What the three named [AppDragSize]s measure, in logical pixels.
///
/// Pass one to [AppDragSection.sizes] to retune a whole section at once
/// instead of an extent per item.
class AppDragSizes {
  const AppDragSizes({
    this.small = 88,
    this.medium = 140,
    this.large = 220,
  });

  final double small;
  final double medium;
  final double large;

  /// The extent for [size], or null when the child sizes itself.
  double? resolve(AppDragSize size) => switch (size) {
        AppDragSize.fit => null,
        AppDragSize.small => small,
        AppDragSize.medium => medium,
        AppDragSize.large => large,
      };
}

/// What starts a drag.
enum AppDragTrigger {
  /// Press and hold anywhere on the item. The right default on a phone: an
  /// immediate drag on the item's whole surface would fight the scroll.
  longPress,

  /// A grip on the item's trailing edge, which drags the moment it is
  /// touched. Choose it when the item is itself tappable and a long press
  /// already means something else.
  handle,
}

/// One child of an [AppDragSection].
class AppDragItem {
  const AppDragItem({
    required this.id,
    required this.child,
    this.draggable = true,
    this.size = AppDragSize.fit,
    this.extent,
  });

  /// Stable across rebuilds and unique within the section — it becomes the
  /// child's key, which is what lets the list animate the *item* rather than
  /// the position. An index would move the animation to whatever now sits
  /// there.
  final String id;

  final Widget child;

  /// A pinned item: it cannot be picked up, and nothing can be dragged past
  /// it. A header, a total, an "add" tile at the end.
  final bool draggable;

  final AppDragSize size;

  /// An exact extent, overriding [size]. For the one item that does not fit
  /// the section's three sizes.
  final double? extent;
}

/// A section whose children can be dragged into a new order.
///
/// ```dart
/// AppDragSection(
///   items: [
///     for (final card in _cards)
///       AppDragItem(id: card.id, child: DashboardCard(card)),
///   ],
///   onReorder: (from, to) => setState(
///     () => _cards = AppDragSection.reorder(_cards, from, to),
///   ),
/// )
/// ```
///
/// It reports the move and nothing else — the list stays yours, and [reorder]
/// does the remove-and-insert for you.
///
/// Items declare their own size and whether they can be moved:
///
/// ```dart
/// AppDragSection(
///   orientation: Axis.horizontal,
///   items: [
///     AppDragItem(id: 'a', size: AppDragSize.large, child: ChartCard()),
///     AppDragItem(id: 'b', size: AppDragSize.small, child: TotalCard()),
///     AppDragItem(id: 'new', draggable: false, child: AddTile()),
///   ],
///   onReorder: _move,
/// )
/// ```
///
/// A pinned item is not merely un-draggable: **nothing can be dropped past
/// it**. It keeps its index, so the "add" tile above stays at the end however
/// the rest are shuffled.
///
/// A **vertical** section shrink-wraps and does not scroll, so it drops into a
/// page that already scrolls; give it [physics] to make it the scrolling thing
/// itself. A **horizontal** one scrolls sideways on its own — nothing else is
/// going to — and needs a bounded height from its parent, so put it in a
/// `SizedBox` or give its items an extent.
class AppDragSection extends StatelessWidget {
  const AppDragSection({
    super.key,
    required this.items,
    required this.onReorder,
    this.orientation = Axis.vertical,
    this.trigger = AppDragTrigger.longPress,
    this.sizes = const AppDragSizes(),
    this.spacing = AppConstants.space8,
    this.padding = EdgeInsets.zero,
    this.shrinkWrap,
    this.physics,
    this.scrollController,
    this.onReorderStart,
    this.onReorderEnd,
    this.handleIcon = Icons.drag_indicator,
    this.variant,
  });

  final List<AppDragItem> items;

  /// Called with the item's old and new index, already corrected for the
  /// pinned items in the way. Apply it with [reorder].
  final void Function(int oldIndex, int newIndex) onReorder;

  /// Vertical stacks the items; horizontal lays them in a row that scrolls
  /// sideways.
  final Axis orientation;

  final AppDragTrigger trigger;
  final AppDragSizes sizes;

  /// The gap between items. It travels inside each item, so it moves with the
  /// one being dragged rather than leaving a hole behind.
  final double spacing;

  /// `EdgeInsets` rather than `EdgeInsetsGeometry`, because that is what
  /// `ReorderableListView` accepts.
  final EdgeInsets padding;

  /// Null follows the orientation: a vertical section shrink-wraps so it can
  /// sit in a page, a horizontal one does not so it can fill the width it is
  /// given.
  final bool? shrinkWrap;

  /// Null follows the orientation too — a vertical section does not scroll
  /// (the page it is in does), a horizontal one scrolls itself, because
  /// nothing else is going to scroll it sideways.
  final ScrollPhysics? physics;

  final ScrollController? scrollController;

  final VoidCallback? onReorderStart;
  final VoidCallback? onReorderEnd;

  /// Only drawn for [AppDragTrigger.handle].
  final IconData handleIcon;

  /// Tints the drag handle. Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  static const double _liftScale = 0.04;
  static const double _liftElevation = 8;

  /// Moves the item at [oldIndex] to [newIndex], returning a new list.
  ///
  /// The remove-and-insert every caller of [onReorder] would otherwise write
  /// out, and the place the off-by-one lives if it is written out wrong.
  static List<T> reorder<T>(List<T> items, int oldIndex, int newIndex) {
    final copy = List<T>.of(items);
    if (oldIndex < 0 || oldIndex >= copy.length) return copy;
    final item = copy.removeAt(oldIndex);
    copy.insert(newIndex.clamp(0, copy.length), item);
    return copy;
  }

  /// How far the item at [oldIndex] is allowed to travel.
  ///
  /// A pinned item keeps its index, so it is a wall: an item may move freely
  /// within the run of movable slots it sits in, and no further. Without this
  /// a drop past a pinned item would silently push it along.
  int _clampToPinned(int oldIndex, int newIndex) {
    var lower = 0;
    for (var i = oldIndex - 1; i >= 0; i--) {
      if (!items[i].draggable) {
        lower = i + 1;
        break;
      }
    }

    var upper = items.length - 1;
    for (var i = oldIndex + 1; i < items.length; i++) {
      if (!items[i].draggable) {
        upper = i - 1;
        break;
      }
    }

    if (newIndex < lower) return lower;
    if (newIndex > upper) return upper;
    return newIndex;
  }

  void _handleReorder(int oldIndex, int newIndex) {
    // ReorderableListView reports the destination against the list *before*
    // the dragged item is taken out of it, so a downward move arrives one too
    // high. Every caller would otherwise have to know that.
    final corrected = newIndex > oldIndex ? newIndex - 1 : newIndex;
    final target = _clampToPinned(oldIndex, corrected);
    if (target == oldIndex) return;
    HapticFeedback.selectionClick();
    onReorder(oldIndex, target);
  }

  @override
  Widget build(BuildContext context) {
    assert(
      items.map((item) => item.id).toSet().length == items.length,
      'AppDragSection needs a unique id per item — duplicates make the list '
      'animate the wrong child.',
    );

    return ReorderableListView.builder(
      itemCount: items.length,
      scrollDirection: orientation,
      shrinkWrap: shrinkWrap ?? orientation == Axis.vertical,
      physics: physics ??
          (orientation == Axis.vertical
              ? const NeverScrollableScrollPhysics()
              : null),
      scrollController: scrollController,
      padding: padding,
      // The listeners are attached per item instead, so a pinned one has none
      // and cannot be picked up at all.
      buildDefaultDragHandles: false,
      onReorder: _handleReorder,
      onReorderStart: (_) {
        HapticFeedback.mediumImpact();
        onReorderStart?.call();
      },
      onReorderEnd: (_) => onReorderEnd?.call(),
      proxyDecorator: _lifted,
      itemBuilder: (context, index) => _item(context, index),
    );
  }

  Widget _item(BuildContext context, int index) {
    final item = items[index];
    final extent = item.extent ?? sizes.resolve(item.size);
    final isLast = index == items.length - 1;

    Widget content = item.child;

    if (trigger == AppDragTrigger.handle && item.draggable) {
      content = Row(
        children: [
          Expanded(child: content),
          ReorderableDragStartListener(
            index: index,
            child: Padding(
              padding: const EdgeInsets.all(AppConstants.space8),
              child: Icon(
                handleIcon,
                color: AppInputStyle.accentOf(context, variant),
              ),
            ),
          ),
        ],
      );
    }

    if (extent != null) {
      content = orientation == Axis.vertical
          ? SizedBox(height: extent, child: content)
          : SizedBox(width: extent, child: content);
    }

    // Inside the keyed child, so the gap travels with the item rather than
    // staying behind as a hole in the list.
    if (!isLast && spacing > 0) {
      content = Padding(
        padding: orientation == Axis.vertical
            ? EdgeInsets.only(bottom: spacing)
            : EdgeInsets.only(right: spacing),
        child: content,
      );
    }

    final key = ValueKey<String>(item.id);

    if (!item.draggable) return KeyedSubtree(key: key, child: content);

    return switch (trigger) {
      // The whole surface drags, after a hold — an immediate listener here
      // would swallow the scroll.
      AppDragTrigger.longPress => ReorderableDelayedDragStartListener(
          key: key,
          index: index,
          child: content,
        ),
      // The grip is already wrapped above; this keeps the rest of the item
      // tappable.
      AppDragTrigger.handle => KeyedSubtree(key: key, child: content),
    };
  }

  /// The lifted look while an item is in flight: a touch bigger, with a
  /// shadow under it.
  Widget _lifted(Widget child, int index, Animation<double> animation) {
    return AnimatedBuilder(
      animation: animation,
      builder: (context, _) {
        final t = Curves.easeInOut.transform(animation.value);
        return Transform.scale(
          scale: 1 + _liftScale * t,
          child: Material(
            color: Colors.transparent,
            elevation: _liftElevation * t,
            borderRadius: AppConstants.borderRadius12,
            child: child,
          ),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';

/// How tightly rows are packed.
enum AppTableDensity { compact, standard, comfortable }

/// One column: its heading, how wide it is, and how its cells align.
class AppTableColumn {
  const AppTableColumn({
    required this.label,
    this.width,
    this.flex = 1,
    this.minWidth = 72,
    this.align = TextAlign.start,
    this.numeric = false,
    this.tooltip,
  });

  /// A column holding numbers: right-aligned and tabular, because a column of
  /// figures is read down rather than across.
  const AppTableColumn.numeric({
    required this.label,
    this.width,
    this.flex = 1,
    this.minWidth = 72,
    this.tooltip,
  })  : align = TextAlign.end,
        numeric = true;

  final String label;

  /// A fixed width. Takes priority over [flex] — use it for a column whose
  /// content never varies (a quantity, a status chip).
  final double? width;

  /// This column's share of what is left once the fixed columns are placed.
  final int flex;

  /// The width a flexible column will not go below. Past the point where
  /// every column is at its minimum, the table scrolls sideways instead of
  /// squeezing further.
  final double minWidth;

  final TextAlign align;

  /// Renders cells with `FontFeature.tabularFigures`, so digits line up
  /// column-wise instead of jittering by glyph width.
  final bool numeric;

  /// Shown on a long-press of the heading — room for the full name of a
  /// column abbreviated to fit.
  final String? tooltip;
}

/// One row of cells.
///
/// Cells are `String`s by default, which covers most of a table. Pass
/// [widgets] instead when a cell is a chip, an avatar or a button — the two
/// are exclusive, and [widgets] wins if both are given.
class AppTableRow {
  const AppTableRow({
    this.cells = const [],
    this.widgets,
    this.onTap,
    this.selected = false,
    this.color,
  });

  final List<String> cells;

  /// Arbitrary cell content. Must be the same length as the column list, as
  /// [cells] must.
  final List<Widget>? widgets;

  final VoidCallback? onTap;

  /// Tints the row with the accent — a current selection, a highlighted
  /// result.
  final bool selected;

  /// Tints the row with something of your own. Overrides striping.
  final Color? color;
}

/// Rows and columns, sized for a screen narrower than the data.
///
/// ```dart
/// AppTable(
///   columns: const [
///     AppTableColumn(label: 'Item', flex: 2),
///     AppTableColumn.numeric(label: 'Qty', width: 56),
///     AppTableColumn.numeric(label: 'Total'),
///   ],
///   rows: const [
///     AppTableRow(cells: ['Coffee', '2', '€7.00']),
///     AppTableRow(cells: ['Pastry', '1', '€2.40']),
///   ],
///   footer: AppTableRow(cells: ['Total', '3', '€9.40']),
/// )
/// ```
///
/// **It does not scroll vertically.** A table that owns a vertical scroll
/// cannot sit in a page that also scrolls without one of them being wrong, so
/// this one lays out at its full height and lets the page it is in do the
/// scrolling — drop it into `AppSingleScrollView` or a `ListView`. It *does*
/// scroll sideways, on its own, once the columns no longer fit: every
/// flexible column drops to its [AppTableColumn.minWidth] and the whole table
/// pans.
class AppTable extends StatelessWidget {
  const AppTable({
    super.key,
    required this.columns,
    required this.rows,
    this.footer,
    this.showHeader = true,
    this.density = AppTableDensity.standard,
    this.striped = false,
    this.showRowDividers = true,
    this.showColumnDividers = false,
    this.showBorder = true,
    this.emptyLabel = 'Nothing to show',
    this.emptyBuilder,
    this.horizontalPadding = AppConstants.space12,
    this.variant,
  });

  final List<AppTableColumn> columns;
  final List<AppTableRow> rows;

  /// A row pinned under the body, drawn in the heading's weight — a total, a
  /// count. Not striped and not tappable.
  final AppTableRow? footer;

  final bool showHeader;
  final AppTableDensity density;

  /// Tints every other row. Prefer it over [showRowDividers] on a wide table,
  /// where a stripe tracks the eye across better than a line does.
  final bool striped;

  final bool showRowDividers;

  /// Vertical rules between columns. Off by default: alignment usually
  /// separates columns better than lines, and lines make a small table look
  /// like a spreadsheet.
  final bool showColumnDividers;

  /// The outline and rounded corners around the whole table.
  final bool showBorder;

  final String emptyLabel;

  /// Replaces the whole empty state. [emptyLabel] is ignored when given.
  final WidgetBuilder? emptyBuilder;

  final double horizontalPadding;

  /// Colors the selected-row tint and the header text. Null follows
  /// [AppInputConfig.defaults].
  final AppInputVariant? variant;

  static const double _stripeOpacity = 0.04;
  static const double _selectedOpacity = 0.10;

  /// What sits between two columns — a plain gap, or a rule with a gap
  /// either side of it. Counted in the width maths: a row whose gaps are not
  /// budgeted for overflows by exactly this much per column.
  double get _columnGap => showColumnDividers
      ? AppConstants.space8 * 2 + 1
      : AppConstants.space8;

  double get _rowPadding => switch (density) {
        AppTableDensity.compact => AppConstants.space8,
        AppTableDensity.standard => AppConstants.space12,
        AppTableDensity.comfortable => AppConstants.space16,
      };

  /// The width each column gets, given [available].
  ///
  /// Fixed columns take theirs first; the rest share what is left by [flex],
  /// but never below their own minimum. When the minimums alone overflow, the
  /// caller scrolls — so this returns widths that may total more than
  /// [available], deliberately.
  List<double> _resolveWidths(double available) {
    final widths = List<double>.filled(columns.length, 0);
    var fixedTotal = 0.0;
    var flexTotal = 0;

    for (var i = 0; i < columns.length; i++) {
      final width = columns[i].width;
      if (width != null) {
        widths[i] = width;
        fixedTotal += width;
      } else {
        flexTotal += columns[i].flex < 1 ? 1 : columns[i].flex;
      }
    }

    final remaining = available - fixedTotal;
    for (var i = 0; i < columns.length; i++) {
      if (columns[i].width != null) continue;
      final flex = columns[i].flex < 1 ? 1 : columns[i].flex;
      final share = flexTotal == 0 ? 0.0 : remaining * flex / flexTotal;
      widths[i] = share < columns[i].minWidth ? columns[i].minWidth : share;
    }

    return widths;
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final colorScheme = theme.colorScheme;
    final accent = AppInputStyle.accentOf(context, variant);

    assert(
      columns.isNotEmpty,
      'AppTable needs at least one column to lay anything out.',
    );

    final table = LayoutBuilder(
      builder: (context, constraints) {
        // Unbounded width means an unconstrained parent (a Row, a horizontal
        // list). Fall back to the minimums rather than dividing infinity.
        final gaps = _columnGap * (columns.length - 1);
        final available = constraints.hasBoundedWidth
            ? constraints.maxWidth - horizontalPadding * 2 - gaps
            : 0.0;
        final widths = _resolveWidths(available);
        final total = widths.fold<double>(0, (sum, w) => sum + w);
        final overflows = total > available;

        final content = SizedBox(
          width: overflows ? total + gaps + horizontalPadding * 2 : null,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              if (showHeader) ...[
                _header(theme, accent, widths),
                Divider(height: 1, color: colorScheme.outlineVariant),
              ],
              if (rows.isEmpty)
                _empty(context, theme)
              else
                for (var i = 0; i < rows.length; i++) ...[
                  if (i > 0 && showRowDividers)
                    Divider(height: 1, color: colorScheme.outlineVariant),
                  _row(theme, accent, widths, rows[i], index: i),
                ],
              if (footer != null) ...[
                Divider(height: 1, color: colorScheme.outlineVariant),
                _row(
                  theme,
                  accent,
                  widths,
                  footer!,
                  index: -1,
                  bold: true,
                ),
              ],
            ],
          ),
        );

        if (!overflows) return content;
        return SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: content,
        );
      },
    );

    if (!showBorder) return table;
    return DecoratedBox(
      decoration: BoxDecoration(
        border: Border.all(color: colorScheme.outlineVariant),
        borderRadius: AppConstants.borderRadius12,
      ),
      child: ClipRRect(
        borderRadius: AppConstants.borderRadius12,
        child: table,
      ),
    );
  }

  Widget _empty(BuildContext context, ThemeData theme) {
    final builder = emptyBuilder;
    if (builder != null) return builder(context);
    return Padding(
      padding: EdgeInsets.symmetric(
        horizontal: horizontalPadding,
        vertical: AppConstants.space24,
      ),
      child: Text(
        emptyLabel,
        textAlign: TextAlign.center,
        style: theme.textTheme.bodyMedium?.copyWith(
          color: theme.colorScheme.onSurfaceVariant,
        ),
      ),
    );
  }

  Widget _header(ThemeData theme, Color accent, List<double> widths) {
    final style = theme.textTheme.labelMedium?.copyWith(
      color: theme.colorScheme.onSurfaceVariant,
      fontWeight: FontWeight.w600,
    );

    return Container(
      color: theme.colorScheme.surfaceContainerHighest.withValues(alpha: 0.5),
      padding: EdgeInsets.symmetric(
        horizontal: horizontalPadding,
        vertical: _rowPadding,
      ),
      child: Row(
        children: [
          for (var i = 0; i < columns.length; i++) ...[
            if (i > 0 && showColumnDividers)
              _columnDivider(theme)
            else if (i > 0)
              const SizedBox(width: AppConstants.space8),
            SizedBox(
              width: widths[i],
              child: _headingCell(columns[i], style),
            ),
          ],
        ],
      ),
    );
  }

  Widget _headingCell(AppTableColumn column, TextStyle? style) {
    final text = Text(
      column.label,
      textAlign: column.align,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: style,
    );
    final tooltip = column.tooltip;
    if (tooltip == null) return text;
    return Tooltip(message: tooltip, child: text);
  }

  Widget _row(
    ThemeData theme,
    Color accent,
    List<double> widths,
    AppTableRow row, {
    required int index,
    bool bold = false,
  }) {
    final colorScheme = theme.colorScheme;
    final baseStyle = theme.textTheme.bodyMedium?.copyWith(
      fontWeight: bold ? FontWeight.w600 : null,
    );

    final background = row.color ??
        (row.selected
            ? accent.withValues(alpha: _selectedOpacity)
            : (striped && index.isOdd
                ? colorScheme.onSurface.withValues(alpha: _stripeOpacity)
                : null));

    final cells = Padding(
      padding: EdgeInsets.symmetric(
        horizontal: horizontalPadding,
        vertical: _rowPadding,
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.center,
        children: [
          for (var i = 0; i < columns.length; i++) ...[
            if (i > 0 && showColumnDividers)
              _columnDivider(theme)
            else if (i > 0)
              const SizedBox(width: AppConstants.space8),
            SizedBox(
              width: widths[i],
              child: _cell(row, i, columns[i], baseStyle),
            ),
          ],
        ],
      ),
    );

    if (row.onTap == null) {
      return background == null ? cells : ColoredBox(color: background, child: cells);
    }

    return Material(
      // Its own Material so the ripple paints over the row tint rather than
      // under it.
      color: background ?? Colors.transparent,
      child: InkWell(
        onTap: () {
          HapticFeedback.selectionClick();
          row.onTap!();
        },
        child: cells,
      ),
    );
  }

  /// A cell's content: the widget if one was given, otherwise the string —
  /// and an empty box when the row is shorter than the column list, which is
  /// a ragged row rather than a crash.
  Widget _cell(
    AppTableRow row,
    int index,
    AppTableColumn column,
    TextStyle? style,
  ) {
    final widgets = row.widgets;
    if (widgets != null) {
      if (index >= widgets.length) return const SizedBox.shrink();
      return Align(
        alignment: switch (column.align) {
          TextAlign.end => Alignment.centerRight,
          TextAlign.center => Alignment.center,
          _ => Alignment.centerLeft,
        },
        child: widgets[index],
      );
    }

    if (index >= row.cells.length) return const SizedBox.shrink();
    return Text(
      row.cells[index],
      textAlign: column.align,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: column.numeric
          ? style?.copyWith(
              fontFeatures: const [FontFeature.tabularFigures()],
            )
          : style,
    );
  }

  Widget _columnDivider(ThemeData theme) {
    return Container(
      width: 1,
      height: AppConstants.space16,
      margin: const EdgeInsets.symmetric(horizontal: AppConstants.space8),
      color: theme.colorScheme.outlineVariant,
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// A single destination for [AppBottomNav] — and for the rail and the drawer,
/// which read the same list so an app describes its navigation once.
class AppNavDestination {
  const AppNavDestination({
    required this.icon,
    required this.selectedIcon,
    required this.label,
  });

  final IconData icon;
  final IconData selectedIcon;
  final String label;
}

/// How [AppBottomNav] marks the selected destination.
///
/// - [material]: Material 3's own bar — a label under every icon and a pill
///   indicator that slides behind the selected one.
/// - [classic]: the pre-M3 bar — icon over label, the selected pair tinted
///   with the accent and nothing drawn behind it.
/// - [pill]: icons only until selected; the selected one opens into an accent
///   pill with its label beside the icon.
/// - [dot]: icons only, with a dot under the selected one. The quietest of the
///   four, for a bar whose icons speak for themselves.
enum AppBottomNavStyle { material, classic, pill, dot }

/// The app's bottom navigation. Feed it the current [index], the
/// [destinations], and an [onDestinationSelected] callback. For go_router,
/// drive [index] from a `StatefulShellRoute` and switch branch in the callback:
///
/// ```dart
/// AppBottomNav(
///   index: shell.currentIndex,
///   destinations: destinations,
///   onDestinationSelected: shell.goBranch,
///   style: AppBottomNavStyle.pill,
///   floating: true,
/// )
/// ```
///
/// [style] is how the selected destination is marked; [floating] is the
/// separate question of whether the bar is a band across the bottom edge or a
/// rounded card riding above it. The two combine freely — a floating [pill] is
/// the look most modern apps wear, but every style floats.
///
/// A floating bar wants `Scaffold(extendBody: true)` under it, so the content
/// runs through the gap instead of stopping at it. [AppAdaptiveNav] sets that
/// for you.
class AppBottomNav extends StatelessWidget {
  const AppBottomNav({
    super.key,
    required this.index,
    required this.destinations,
    required this.onDestinationSelected,
    this.style = AppBottomNavStyle.material,
    this.floating = false,
    this.variant,
  });

  final int index;
  final List<AppNavDestination> destinations;
  final ValueChanged<int> onDestinationSelected;

  final AppBottomNavStyle style;

  /// Detaches the bar from the bottom edge: a rounded card with a margin around
  /// it and a shadow under it. Works with every [style].
  final bool floating;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// The height of the three styles this widget draws itself, before any
  /// safe-area inset: a row of touch targets with a little air around it.
  /// Material's own bar measures itself and is left alone.
  static const double _height = 64;

  void _select(int i) {
    HapticFeedback.selectionClick();
    onDestinationSelected(i);
  }

  @override
  Widget build(BuildContext context) {
    assert(
      destinations.length >= 2,
      'AppBottomNav: needs at least two destinations — a bar with one of them '
      'is not navigation.',
    );
    assert(
      index >= 0 && index < destinations.length,
      'AppBottomNav: index $index is outside the ${destinations.length} '
      'destinations it was given.',
    );

    final bar = style == AppBottomNavStyle.material
        ? _material(context)
        : _drawn(context);

    return floating ? _floated(context, bar) : bar;
  }

  /// Material's own [NavigationBar] — still the right answer when you want the
  /// platform look, and the only style whose indicator animates between
  /// destinations for free.
  Widget _material(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);

    return NavigationBar(
      selectedIndex: index,
      // Floating, the card behind it owns the surface and the shadow — a bar
      // painting its own would draw a second edge inside the rounded one.
      backgroundColor:
          floating ? Colors.transparent : context.colorScheme.surface,
      elevation: floating ? 0 : null,
      indicatorColor: accent.withValues(
        alpha: AppInputStyle.config.fillOpacity * 2,
      ),
      onDestinationSelected: _select,
      destinations: [
        for (final destination in destinations)
          NavigationDestination(
            icon: Icon(destination.icon),
            selectedIcon: Icon(destination.selectedIcon, color: accent),
            label: destination.label,
          ),
      ],
    );
  }

  /// The three styles Material does not ship: one row of items over the bar's
  /// own surface.
  Widget _drawn(BuildContext context) {
    final row = SizedBox(
      height: _height,
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          for (var i = 0; i < destinations.length; i++)
            // Only the pill grows with its label, so only the pill is sized by
            // its content — the other two divide the width evenly.
            if (style != AppBottomNavStyle.pill)
              Expanded(child: _item(i))
            // The open pill is the one item that can want more room than it is
            // given: Flexible lets its label ellipsize on a narrow screen
            // instead of overflowing the row.
            else if (i == index)
              Flexible(child: _item(i))
            else
              _item(i),
        ],
      ),
    );

    // Floating, the shell around it is the Material, and it has already spent
    // the safe area on the margin under the card.
    if (floating) return row;

    return Material(
      color: context.colorScheme.surface,
      child: DecoratedBox(
        // What separates the bar from the content above it, since this one
        // carries no elevation. Drawn outside the SafeArea so it spans the
        // full width on a notched phone held sideways.
        decoration: BoxDecoration(
          border: Border(
            top: BorderSide(color: context.colorScheme.outlineVariant),
          ),
        ),
        child: SafeArea(top: false, child: row),
      ),
    );
  }

  Widget _item(int i) => _AppNavItem(
        destination: destinations[i],
        selected: i == index,
        style: style,
        variant: variant,
        onTap: () => _select(i),
      );

  /// The card a floating bar rides in: the margin off the edges, the rounded
  /// edge, and the shadow that lifts it off the content passing underneath.
  Widget _floated(BuildContext context, Widget bar) {
    final inset = MediaQuery.paddingOf(context).bottom;

    return Padding(
      padding: EdgeInsets.only(
        left: AppConstants.space16,
        right: AppConstants.space16,
        top: AppConstants.space8,
        // Just clear of the gesture indicator where there is one, a margin's
        // worth off the edge where there is not.
        bottom: inset > 0 ? inset : AppConstants.space16,
      ),
      child: DecoratedBox(
        // The same shadow an elevated AppCard casts, so the two read as
        // siblings rather than as two ideas of what "raised" looks like.
        decoration: BoxDecoration(
          borderRadius: AppConstants.borderRadiusFull,
          boxShadow: [
            BoxShadow(
              color: Colors.black.withValues(alpha: 0.08),
              blurRadius: 16,
              offset: const Offset(0, 4),
            ),
          ],
        ),
        child: Material(
          // A step off `surface`, which is what keeps the card visible in a
          // dark theme, where the shadow under it is not.
          color: context.colorScheme.surfaceContainer,
          clipBehavior: Clip.antiAlias,
          borderRadius: AppConstants.borderRadiusFull,
          // The bar inside must not inset itself as well — NavigationBar wraps
          // itself in a SafeArea, which here would pad the inside of the card.
          child: MediaQuery.removePadding(
            context: context,
            removeBottom: true,
            // A rounded end curves in over the last destination's label. The
            // inset keeps the outermost label clear of that curve, which a
            // long one on a narrow phone would otherwise be clipped by.
            child: Padding(
              padding: const EdgeInsets.symmetric(
                horizontal: AppConstants.space8,
              ),
              child: bar,
            ),
          ),
        ),
      ),
    );
  }
}

/// One destination in the styles [AppBottomNav] draws itself.
class _AppNavItem extends StatelessWidget {
  const _AppNavItem({
    required this.destination,
    required this.selected,
    required this.style,
    required this.variant,
    required this.onTap,
  });

  final AppNavDestination destination;
  final bool selected;
  final AppBottomNavStyle style;
  final AppInputVariant? variant;
  final VoidCallback onTap;

  /// The mark under a selected [AppBottomNavStyle.dot] icon. Small enough to
  /// read as a mark rather than as a second icon.
  static const double _dotSize = 6;

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);
    final idle = context.colorScheme.onSurfaceVariant;
    final pill = style == AppBottomNavStyle.pill;

    // The pill is the one style that fills a surface behind its icon, so it is
    // the one style whose selected icon is drawn *on* the accent.
    final selectedColor =
        pill ? AppInputStyle.onAccentOf(context, variant) : accent;

    // Reduce-motion reaches the same layouts, just instantly.
    final duration = MediaQuery.disableAnimationsOf(context)
        ? Duration.zero
        : AppConstants.duration200;

    final icon = Icon(
      selected ? destination.selectedIcon : destination.icon,
      size: AppConstants.iconMedium,
      color: selected ? selectedColor : idle,
    );

    final label = Text(
      destination.label,
      maxLines: 1,
      overflow: TextOverflow.ellipsis,
      style: context.textTheme.labelMedium?.copyWith(
        color: selected ? selectedColor : idle,
        fontWeight: selected ? FontWeight.bold : null,
      ),
    );

    final Widget content = switch (style) {
      // The material style is a NavigationBar, not a row of these, so it never
      // arrives here — answering with the nearest layout beats an empty box if
      // that ever stops being true.
      AppBottomNavStyle.classic || AppBottomNavStyle.material => Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            icon,
            const SizedBox(height: AppConstants.space4),
            label,
          ],
        ),
      AppBottomNavStyle.dot => Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            icon,
            const SizedBox(height: AppConstants.space8),
            // The dot's room is held whether or not it is drawn, so the icons
            // do not hop as the selection moves.
            SizedBox(
              width: _dotSize,
              height: _dotSize,
              child: AnimatedOpacity(
                duration: duration,
                opacity: selected ? 1 : 0,
                child: DecoratedBox(
                  decoration: BoxDecoration(
                    color: accent,
                    shape: BoxShape.circle,
                  ),
                ),
              ),
            ),
          ],
        ),
      AppBottomNavStyle.pill => AnimatedContainer(
          duration: duration,
          curve: Curves.easeOut,
          padding: EdgeInsets.symmetric(
            horizontal: selected ? AppConstants.space16 : AppConstants.space12,
            vertical: AppConstants.space8,
          ),
          decoration: BoxDecoration(
            color: selected ? accent : Colors.transparent,
            borderRadius: AppConstants.borderRadiusFull,
          ),
          // The label is only in the tree while selected; AnimatedSize is what
          // turns its arrival into the pill opening rather than a jump.
          child: AnimatedSize(
            duration: duration,
            curve: Curves.easeOut,
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                icon,
                if (selected) ...[
                  const SizedBox(width: AppConstants.space8),
                  Flexible(child: label),
                ],
              ],
            ),
          ),
        ),
    };

    final target = ConstrainedBox(
      constraints: const BoxConstraints(
        minWidth: AppConstants.touchTarget,
        minHeight: AppConstants.touchTarget,
      ),
      // Shrink-wraps where the item is sized by its content — a pill that
      // stretched to the free space beside it would not be a pill. Ignored
      // where the row hands down a tight width.
      child: Center(
        widthFactor: 1,
        heightFactor: 1,
        // The label below carries the same string as the Semantics above, and
        // reading a destination out twice is what excluding it here avoids.
        child: ExcludeSemantics(child: content),
      ),
    );

    return MergeSemantics(
      child: Semantics(
        selected: selected,
        // Two of the three styles never draw the label, and a row of unnamed
        // icons is unusable with a screen reader.
        label: destination.label,
        child: _tooltipped(
          child: InkWell(
            onTap: onTap,
            borderRadius: AppConstants.borderRadiusFull,
            child: target,
          ),
        ),
      ),
    );
  }

  /// Names the icon on a long press — but only where the label is not already
  /// written beside it, so a tooltip never repeats what is on screen.
  Widget _tooltipped({required Widget child}) {
    final labelled = style == AppBottomNavStyle.classic ||
        (style == AppBottomNavStyle.pill && selected);
    if (labelled) return child;
    return Tooltip(message: destination.label, child: child);
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// One tab in an [AppTabBar].
class AppTab {
  const AppTab({required this.label, this.icon});

  final String label;
  final IconData? icon;
}

/// How the current tab is marked.
///
/// - [underline]: a line under the selected label (Material's own).
/// - [pill]: the selected tab is filled with the accent, like [AppSegmented].
enum AppTabsStyle { underline, pill }

/// A [TabBar] wearing the kit's vocabulary. Being a [PreferredSizeWidget] is
/// the point — it drops straight into [AppAppBar]'s `bottom` slot.
///
/// ```dart
/// DefaultTabController(
///   length: 2,
///   child: Scaffold(
///     appBar: AppAppBar(
///       title: 'Orders',
///       bottom: const AppTabBar(
///         tabs: [AppTab(label: 'Open'), AppTab(label: 'Closed')],
///       ),
///     ),
///     body: const TabBarView(children: [...]),
///   ),
/// )
/// ```
///
/// With no [controller] it reads the [DefaultTabController] above it. [AppTabs]
/// is the version that owns a controller and puts the views underneath.
class AppTabBar extends StatelessWidget implements PreferredSizeWidget {
  const AppTabBar({
    super.key,
    required this.tabs,
    this.controller,
    this.onTap,
    this.style = AppTabsStyle.underline,
    this.isScrollable = false,
    this.variant,
  });

  final List<AppTab> tabs;

  /// Null falls back to the [DefaultTabController] above this widget.
  final TabController? controller;

  /// Fires on a tap, not on a swipe between views — listen to the controller
  /// if you need both.
  final ValueChanged<int>? onTap;

  final AppTabsStyle style;

  /// Lets the row scroll instead of dividing the width evenly. What more than
  /// about four tabs needs, and what any tab with a long label needs.
  final bool isScrollable;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// The [Tab] widgets, built once so the bar and [preferredSize] can never
  /// disagree about what is in it.
  List<Widget> get _tabWidgets => [
    for (final tab in tabs)
      Tab(text: tab.label, icon: tab.icon == null ? null : Icon(tab.icon)),
  ];

  /// Measured by asking a bare [TabBar] holding the same tabs, so a row with
  /// icons gets the taller bar Material specifies — and keeps getting the right
  /// answer if those metrics ever change.
  @override
  Size get preferredSize => TabBar(tabs: _tabWidgets).preferredSize;

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);
    final onAccent = AppInputStyle.onAccentOf(context, variant);
    final pill = style == AppTabsStyle.pill;

    return TabBar(
      controller: controller,
      isScrollable: isScrollable,
      tabs: _tabWidgets,
      onTap: onTap == null
          ? null
          : (index) {
              HapticFeedback.selectionClick();
              onTap!(index);
            },
      // A filled indicator has to cover the whole tab for the label to read on
      // top of it; an underline is drawn under the label only.
      indicatorSize: pill ? TabBarIndicatorSize.tab : TabBarIndicatorSize.label,
      indicator: pill
          ? BoxDecoration(
              color: accent,
              borderRadius: AppConstants.borderRadiusFull,
            )
          : null,
      indicatorColor: pill ? null : accent,
      // Ignored once `indicator` is set, but TabBar asserts it is positive
      // either way — so the pill branch cannot answer 0.
      indicatorWeight: AppInputStyle.config.focusedBorderWidth * 2,
      labelColor: pill ? onAccent : accent,
      unselectedLabelColor: context.colorScheme.onSurfaceVariant,
      labelStyle: context.textTheme.titleSmall?.copyWith(
        fontWeight: FontWeight.bold,
      ),
      unselectedLabelStyle: context.textTheme.titleSmall,
      // The pill carries its own edge; Material's divider under the row only
      // makes sense beneath an underline.
      dividerColor: pill ? Colors.transparent : null,
      splashBorderRadius: AppConstants.borderRadiusFull,
    );
  }
}

/// An [AppTabBar] with its views under it, owning the [TabController] — the
/// [StatefulWidget], ticker and `dispose` you would otherwise write.
///
/// ```dart
/// AppTabs(
///   tabs: const [AppTab(label: 'Open'), AppTab(label: 'Closed')],
///   children: [OpenOrders(), ClosedOrders()],
/// )
/// ```
///
/// It fills the height it is given, so put it under an [Expanded] or hand it a
/// body's worth of space. For a bar in the app bar, use [AppTabBar].
class AppTabs extends StatefulWidget {
  const AppTabs({
    super.key,
    required this.tabs,
    required this.children,
    this.initialIndex = 0,
    this.onChanged,
    this.style = AppTabsStyle.underline,
    this.isScrollable = false,
    this.variant,
    this.padding,
  });

  final List<AppTab> tabs;

  /// One view per tab — a different count is a bug, not a layout to guess at.
  final List<Widget> children;

  final int initialIndex;

  /// Fires for a tap *and* for a swipe, once the move has settled.
  final ValueChanged<int>? onChanged;

  final AppTabsStyle style;
  final bool isScrollable;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// Inset around the bar. Null is none — the bar spans the full width, as it
  /// does in an app bar.
  final EdgeInsetsGeometry? padding;

  @override
  State<AppTabs> createState() => _AppTabsState();
}

class _AppTabsState extends State<AppTabs> with TickerProviderStateMixin {
  late TabController _controller;

  /// What [AppTabs.onChanged] last reported, so a settled swipe fires once
  /// rather than on every frame of the animation.
  late int _reportedIndex;

  @override
  void initState() {
    super.initState();
    assert(widget.tabs.isNotEmpty, 'AppTabs: needs at least one tab.');
    _reportedIndex = widget.initialIndex;
    _controller = _createController();
  }

  @override
  void didUpdateWidget(AppTabs oldWidget) {
    super.didUpdateWidget(oldWidget);
    // A TabController's length is fixed, so a tab list that grew or shrank
    // needs a new one — otherwise the bar asserts on the next build.
    if (widget.tabs.length != oldWidget.tabs.length) {
      final previous = _controller;
      _controller = _createController(
        index: previous.index.clamp(0, widget.tabs.length - 1),
      );
      previous
        ..removeListener(_onControllerChanged)
        ..dispose();
    }
  }

  TabController _createController({int? index}) {
    return TabController(
      length: widget.tabs.length,
      initialIndex: index ?? widget.initialIndex.clamp(0, widget.tabs.length - 1),
      vsync: this,
    )..addListener(_onControllerChanged);
  }

  /// Reports the tab the user landed on. `indexIsChanging` is still true while
  /// a tap animates, and the index is already the destination — so waiting for
  /// it to clear reports the move once, whether it came from a tap or a swipe.
  void _onControllerChanged() {
    if (_controller.indexIsChanging) return;
    if (_controller.index == _reportedIndex) return;
    _reportedIndex = _controller.index;
    widget.onChanged?.call(_controller.index);
  }

  @override
  void dispose() {
    _controller
      ..removeListener(_onControllerChanged)
      ..dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    assert(
      widget.tabs.length == widget.children.length,
      'AppTabs: ${widget.tabs.length} tabs but ${widget.children.length} '
      'children — every tab needs exactly one view.',
    );

    final bar = AppTabBar(
      tabs: widget.tabs,
      controller: _controller,
      style: widget.style,
      isScrollable: widget.isScrollable,
      variant: widget.variant,
    );

    return Column(
      children: [
        widget.padding == null
            ? bar
            : Padding(padding: widget.padding!, child: bar),
        Expanded(
          child: TabBarView(controller: _controller, children: widget.children),
        ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// Where one [AppTimelineEntry] stands in the sequence — which is what its node
/// is drawn from.
///
/// - [done]: behind us. A filled node.
/// - [current]: where the thing is now. A ringed node, drawing the eye.
/// - [pending]: still to come. A hollow, dimmed node.
/// - [failed]: went wrong here. Error-colored, whatever the variant.
enum AppTimelineStatus { done, current, pending, failed }

/// One event on an [AppTimeline].
class AppTimelineEntry {
  const AppTimelineEntry({
    required this.title,
    this.subtitle,
    this.timestamp,
    this.status = AppTimelineStatus.done,
    this.icon,
    this.trailing,
    this.onTap,
  });

  final String title;
  final String? subtitle;

  /// Shown under the subtitle, dimmed — "2 hours ago", "14:32", a date. Already
  /// formatted: the timeline does not decide how an app writes its times.
  final String? timestamp;

  final AppTimelineStatus status;

  /// Drawn inside the node instead of a dot — a check, a truck, a warning.
  final IconData? icon;

  final Widget? trailing;
  final VoidCallback? onTap;
}

/// A vertical sequence of events, each on a node joined to the next by a line —
/// an order's progress, an audit trail, a delivery status.
///
/// ```dart
/// AppTimeline(
///   entries: [
///     AppTimelineEntry(title: 'Ordered', timestamp: 'Mon 09:12'),
///     AppTimelineEntry(title: 'Shipped', timestamp: 'Tue 11:40'),
///     AppTimelineEntry(
///       title: 'Out for delivery',
///       status: AppTimelineStatus.current,
///     ),
///     AppTimelineEntry(title: 'Delivered', status: AppTimelineStatus.pending),
///   ],
/// )
/// ```
///
/// It sizes to its content, so it needs no height. For a list long enough to
/// need lazy rows, [entryBuilder] gives you one row for a `ListView.builder`.
class AppTimeline extends StatelessWidget {
  const AppTimeline({
    super.key,
    required this.entries,
    this.variant,
    this.nodeSize = 16,
    this.padding,
  });

  final List<AppTimelineEntry> entries;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// Diameter of a node. The connector's width and the gap to the text follow
  /// it, so one number scales the rail.
  final double nodeSize;

  final EdgeInsetsGeometry? padding;

  /// One row, for a caller building its own lazy list:
  ///
  /// ```dart
  /// ListView.builder(
  ///   itemCount: entries.length,
  ///   itemBuilder: (context, i) => AppTimeline.entryBuilder(
  ///     entries[i],
  ///     isLast: i == entries.length - 1,
  ///   ),
  /// )
  /// ```
  static Widget entryBuilder(
    AppTimelineEntry entry, {
    required bool isLast,
    AppInputVariant? variant,
    double nodeSize = 16,
  }) => _TimelineRow(
    entry: entry,
    isLast: isLast,
    variant: variant,
    nodeSize: nodeSize,
  );

  @override
  Widget build(BuildContext context) {
    final column = Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        for (var i = 0; i < entries.length; i++)
          _TimelineRow(
            entry: entries[i],
            // The last node has nothing to join, and a line running off the
            // bottom of a finished sequence reads as a missing step.
            isLast: i == entries.length - 1,
            variant: variant,
            nodeSize: nodeSize,
          ),
      ],
    );

    return padding == null ? column : Padding(padding: padding!, child: column);
  }
}

class _TimelineRow extends StatelessWidget {
  const _TimelineRow({
    required this.entry,
    required this.isLast,
    required this.nodeSize,
    this.variant,
  });

  final AppTimelineEntry entry;
  final bool isLast;
  final double nodeSize;
  final AppInputVariant? variant;

  /// The node's color: the variant for everything that has happened or is
  /// happening, the theme's error for a step that failed, and a faded variant
  /// for one that has not been reached.
  Color _colorOf(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);
    return switch (entry.status) {
      AppTimelineStatus.failed => context.colorScheme.error,
      AppTimelineStatus.pending => accent.withValues(
        alpha: AppInputStyle.config.idleBorderOpacity,
      ),
      _ => accent,
    };
  }

  @override
  Widget build(BuildContext context) {
    final color = _colorOf(context);
    final content = _content(context);

    return IntrinsicHeight(
      child: Row(
        // Stretch is what lets the connector fill the row: without it the rail
        // column is only as tall as its dot, and the line never reaches the
        // next node.
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          SizedBox(
            width: nodeSize * 2,
            child: Column(
              children: [
                _node(color),
                if (!isLast)
                  Expanded(
                    child: Container(
                      width: nodeSize / 8,
                      margin: const EdgeInsets.symmetric(
                        vertical: AppConstants.space4,
                      ),
                      color: color.withValues(alpha: 0.4),
                    ),
                  ),
              ],
            ),
          ),
          Expanded(
            child: Padding(
              padding: EdgeInsets.only(
                left: AppConstants.space4,
                bottom: isLast ? 0 : AppConstants.space16,
              ),
              child: entry.onTap == null
                  ? content
                  : InkWell(
                      onTap: () {
                        HapticFeedback.selectionClick();
                        entry.onTap!();
                      },
                      borderRadius: AppConstants.borderRadius8,
                      child: content,
                    ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _node(Color color) {
    final hollow = entry.status == AppTimelineStatus.pending;
    final ringed = entry.status == AppTimelineStatus.current;
    final icon = entry.icon;

    return Container(
      // Centers the dot on the first line of the title rather than on the row,
      // which is what makes a two-line entry still look joined up.
      margin: const EdgeInsets.only(top: AppConstants.space4),
      width: nodeSize,
      height: nodeSize,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: hollow ? Colors.transparent : color,
        border: Border.all(
          color: color,
          width: ringed ? nodeSize / 4 : nodeSize / 8,
        ),
      ),
      child: icon == null
          ? null
          : FittedBox(
              fit: BoxFit.scaleDown,
              child: Icon(icon, color: hollow ? color : Colors.white),
            ),
    );
  }

  Widget _content(BuildContext context) {
    final subtitle = entry.subtitle;
    final timestamp = entry.timestamp;
    final trailing = entry.trailing;
    final dimmed = entry.status == AppTimelineStatus.pending;

    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                entry.title,
                style: context.textTheme.bodyLarge?.copyWith(
                  fontWeight: entry.status == AppTimelineStatus.current
                      ? FontWeight.bold
                      : FontWeight.w500,
                  color: dimmed ? context.colorScheme.onSurfaceVariant : null,
                ),
              ),
              if (subtitle != null)
                Text(
                  subtitle,
                  style: context.textTheme.bodyMedium?.copyWith(
                    color: context.colorScheme.onSurfaceVariant,
                  ),
                ),
              if (timestamp != null)
                Padding(
                  padding: const EdgeInsets.only(top: AppConstants.space4),
                  child: Text(
                    timestamp,
                    style: context.textTheme.bodySmall?.copyWith(
                      color: context.colorScheme.onSurfaceVariant,
                    ),
                  ),
                ),
            ],
          ),
        ),
        // An empty box rather than a null-aware element: this file has to
        // compile in a project whose pubspec still asks for an older Dart.
        trailing ?? const SizedBox.shrink(),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_bottom_nav.dart';
import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// The side menu, reading the same [AppNavDestination] list as [AppBottomNav]
/// so a phone and a tablet describe their navigation once.
///
/// ```dart
/// Scaffold(
///   drawer: AppDrawer(
///     destinations: destinations,
///     selectedIndex: index,
///     onDestinationSelected: _go,
///     header: const AppDrawerHeader(title: 'Acme', subtitle: 'Signed in'),
///   ),
///   ...
/// )
/// ```
///
/// It closes itself after a pick — a modal drawer should never survive its own
/// selection.
class AppDrawer extends StatelessWidget {
  const AppDrawer({
    super.key,
    required this.destinations,
    required this.selectedIndex,
    required this.onDestinationSelected,
    this.header,
    this.footer,
    this.variant,
  });

  final List<AppNavDestination> destinations;
  final int selectedIndex;
  final ValueChanged<int> onDestinationSelected;

  /// Shown above the destinations — an [AppDrawerHeader], a logo, an account
  /// row. It is not a destination and does not shift the selected index.
  final Widget? header;

  /// Shown under the destinations — a sign-out row, a version string.
  final Widget? footer;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// Closes the drawer if this one is open as a drawer at all — on a wide
  /// layout the same widget may be pinned beside the content, where there is
  /// nothing to close.
  void _dismiss(BuildContext context) {
    final scaffold = Scaffold.maybeOf(context);
    if (scaffold == null) return;
    if (scaffold.isDrawerOpen) {
      scaffold.closeDrawer();
    } else if (scaffold.isEndDrawerOpen) {
      scaffold.closeEndDrawer();
    }
  }

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);

    return NavigationDrawer(
      selectedIndex: selectedIndex,
      backgroundColor: context.colorScheme.surface,
      indicatorColor: accent.withValues(alpha: AppInputStyle.config.fillOpacity * 2),
      indicatorShape: RoundedRectangleBorder(
        borderRadius: AppConstants.borderRadiusFull,
      ),
      onDestinationSelected: (index) {
        HapticFeedback.selectionClick();
        _dismiss(context);
        onDestinationSelected(index);
      },
      children: [
        // NavigationDrawer counts only its NavigationDrawerDestination
        // children, so a header or divider never shifts the selected index.
        // An empty box rather than a null-aware element, to stay compatible
        // with older Dart SDKs.
        header ?? const SizedBox.shrink(),
        for (final destination in destinations)
          NavigationDrawerDestination(
            icon: Icon(destination.icon),
            selectedIcon: Icon(destination.selectedIcon, color: accent),
            label: Text(destination.label),
          ),
        if (footer != null) ...[
          const Padding(
            padding: AppConstants.paddingV8,
            child: Divider(height: 1),
          ),
          footer!,
        ],
      ],
    );
  }
}

/// A title-and-subtitle block for the top of an [AppDrawer]. Pass anything else
/// you like as [AppDrawer.header] — this is only the common case.
class AppDrawerHeader extends StatelessWidget {
  const AppDrawerHeader({
    super.key,
    required this.title,
    this.subtitle,
    this.leading,
  });

  final String title;
  final String? subtitle;
  final Widget? leading;

  @override
  Widget build(BuildContext context) {
    return Padding(
      // Clears the status bar without a SafeArea: the drawer starts at the top
      // of the screen, and NavigationDrawer does not inset its children.
      padding: EdgeInsets.only(
        top: MediaQuery.paddingOf(context).top + AppConstants.space16,
        left: AppConstants.space24,
        right: AppConstants.space16,
        bottom: AppConstants.space16,
      ),
      child: Row(
        children: [
          // The gap travels with the leading widget, so a header without one
          // does not start with 12px of nothing.
          if (leading != null) ...[
            leading!,
            const SizedBox(width: AppConstants.space12),
          ],
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  title,
                  style: context.textTheme.titleMedium?.copyWith(
                    fontWeight: FontWeight.bold,
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
                if (subtitle != null)
                  Text(
                    subtitle!,
                    style: context.textTheme.bodySmall?.copyWith(
                      color: context.colorScheme.onSurfaceVariant,
                    ),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_bottom_nav.dart';
import '../inputs/app_input_style.dart';
import '../../../core/utils/extensions.dart';

/// The vertical navigation a wide screen shows instead of a bottom bar, reading
/// the same [AppNavDestination] list as [AppBottomNav].
///
/// Material asks for a rail past 600dp; [AppAdaptiveNav] makes that switch.
class AppNavRail extends StatelessWidget {
  const AppNavRail({
    super.key,
    required this.destinations,
    required this.index,
    required this.onDestinationSelected,
    this.extended = false,
    this.leading,
    this.trailing,
    this.variant,
  });

  final List<AppNavDestination> destinations;
  final int index;
  final ValueChanged<int> onDestinationSelected;

  /// Shows the labels beside the icons rather than under them — for a window
  /// wide enough that a narrow rail would be wasting the space.
  final bool extended;

  /// Above the destinations: a logo, or the [FloatingActionButton] a rail is
  /// expected to host.
  final Widget? leading;

  /// Below the destinations, pushed to the bottom of the rail.
  final Widget? trailing;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  @override
  Widget build(BuildContext context) {
    final accent = AppInputStyle.accentOf(context, variant);

    return NavigationRail(
      selectedIndex: index,
      extended: extended,
      backgroundColor: context.colorScheme.surface,
      indicatorColor: accent.withValues(
        alpha: AppInputStyle.config.fillOpacity * 2,
      ),
      // An extended rail already writes every label beside its icon; asking for
      // labels as well is what NavigationRail asserts against.
      labelType: extended ? null : NavigationRailLabelType.all,
      leading: leading,
      trailing: trailing == null
          ? null
          : Expanded(
              child: Align(
                alignment: Alignment.bottomCenter,
                child: trailing,
              ),
            ),
      onDestinationSelected: (i) {
        HapticFeedback.selectionClick();
        onDestinationSelected(i);
      },
      destinations: [
        for (final destination in destinations)
          NavigationRailDestination(
            icon: Icon(destination.icon),
            selectedIcon: Icon(destination.selectedIcon, color: accent),
            label: Text(destination.label),
          ),
      ],
    );
  }
}

/// A [Scaffold] that navigates the way the window is shaped: an [AppNavRail]
/// beside the content on a tablet, an [AppBottomNav] under it on a phone.
///
/// This is the shell a `StatefulShellRoute` builds.
///
/// ```dart
/// AppAdaptiveNav(
///   destinations: destinations,
///   index: shell.currentIndex,
///   onDestinationSelected: shell.goBranch,
///   body: shell,
/// )
/// ```
///
/// The phone half of it is an [AppBottomNav], so [bottomNavStyle] and
/// [floatingBottomNav] pick which of its looks that half wears.
class AppAdaptiveNav extends StatelessWidget {
  const AppAdaptiveNav({
    super.key,
    required this.destinations,
    required this.index,
    required this.onDestinationSelected,
    required this.body,
    this.appBar,
    this.floatingActionButton,
    this.drawer,
    this.extendedRail = false,
    this.bottomNavStyle = AppBottomNavStyle.material,
    this.floatingBottomNav = false,
    this.variant,
  });

  final List<AppNavDestination> destinations;
  final int index;
  final ValueChanged<int> onDestinationSelected;

  /// The screen itself — on a phone the whole body, on a tablet everything
  /// right of the rail.
  final Widget body;

  final PreferredSizeWidget? appBar;
  final Widget? floatingActionButton;
  final Widget? drawer;

  /// Whether the rail shows its labels beside the icons. Only read on the wide
  /// layout.
  final bool extendedRail;

  /// How the bar marks the selected destination. Only read on the phone
  /// layout — the rail draws its own indicator either way.
  final AppBottomNavStyle bottomNavStyle;

  /// Whether the bar floats above the content instead of sitting on the bottom
  /// edge. Only read on the phone layout, where it also turns on
  /// [Scaffold.extendBody] so the body runs under the card.
  final bool floatingBottomNav;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  @override
  Widget build(BuildContext context) {
    // The 600dp short-side breakpoint, so the layout survives a rotation
    // instead of following whichever edge happens to be longer.
    final wide = context.isTablet;

    return Scaffold(
      appBar: appBar,
      drawer: drawer,
      floatingActionButton: floatingActionButton,
      // A floating bar leaves a gap under and beside itself. Without this the
      // body stops at the top of that gap and the card looks pasted on.
      extendBody: !wide && floatingBottomNav,
      body: wide
          ? Row(
              children: [
                AppNavRail(
                  destinations: destinations,
                  index: index,
                  onDestinationSelected: onDestinationSelected,
                  extended: extendedRail,
                  variant: variant,
                ),
                const VerticalDivider(width: 1),
                Expanded(child: body),
              ],
            )
          : body,
      bottomNavigationBar: wide
          ? null
          : AppBottomNav(
              index: index,
              destinations: destinations,
              onDestinationSelected: onDestinationSelected,
              style: bottomNavStyle,
              floating: floatingBottomNav,
              variant: variant,
            ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_button.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// The screen's one primary action, wearing [AppButtonVariant] so it matches
/// the buttons inside the screen it floats over.
///
/// ```dart
/// Scaffold(
///   floatingActionButton: AppFab(
///     icon: Icons.add,
///     label: 'New order',        // omit for a circular icon-only FAB
///     onPressed: _create,
///   ),
///   ...
/// )
/// ```
///
/// [isLoading] swaps the icon for a spinner and stops the taps without changing
/// the button's size, so a FAB that starts a request does not resize the screen
/// under it. A null [onPressed] renders it disabled — the same rule the rest of
/// the kit follows.
class AppFab extends StatelessWidget {
  const AppFab({
    super.key,
    required this.icon,
    this.onPressed,
    this.label,
    this.variant = AppButtonVariant.primary,
    this.type = AppButtonType.filled,
    this.isLoading = false,
    this.mini = false,
    this.tooltip,
    this.heroTag,
  });

  final IconData icon;

  /// Pass null to render the FAB disabled.
  final VoidCallback? onPressed;

  /// Turns the circle into an extended pill. Skip it for the icon-only form.
  final String? label;

  final AppButtonVariant variant;

  /// [AppButtonType.filled] is the FAB Material describes;
  /// [AppButtonType.outlined] and [AppButtonType.ghost] give the quieter
  /// version a screen with its own strong content sometimes wants.
  final AppButtonType type;

  final bool isLoading;

  /// The smaller circle, for a dense screen. Ignored by the extended form,
  /// which has a label to fit.
  final bool mini;

  /// Falls back to [label] on the extended form. Worth setting on the
  /// icon-only form, which otherwise says nothing at all to a screen reader.
  final String? tooltip;

  /// Only needed when two FABs can be on screen at once, or across a route
  /// transition: Flutter animates same-tag heroes into each other and throws if
  /// it finds two.
  final Object? heroTag;

  (Color, Color) _colorsOf(BuildContext context) {
    final colorScheme = context.colorScheme;
    final (accent, onAccent) = switch (variant) {
      AppButtonVariant.primary => (colorScheme.primary, colorScheme.onPrimary),
      AppButtonVariant.secondary => (
        colorScheme.secondary,
        colorScheme.onSecondary,
      ),
      AppButtonVariant.tertiary => (
        colorScheme.tertiary,
        colorScheme.onTertiary,
      ),
      AppButtonVariant.danger => (colorScheme.error, colorScheme.onError),
    };

    // Variant picks the color; type only decides how it is applied — the same
    // split AppButton makes.
    return switch (type) {
      AppButtonType.filled => (accent, onAccent),
      AppButtonType.outlined || AppButtonType.ghost => (
        colorScheme.surfaceContainerLowest,
        accent,
      ),
    };
  }

  @override
  Widget build(BuildContext context) {
    final enabled = !isLoading && onPressed != null;
    final (background, foreground) = _colorsOf(context);
    final resolvedBackground = enabled
        ? background
        : background.withValues(alpha: 0.35);

    final child = isLoading
        ? SizedBox.square(
            dimension: AppConstants.iconMedium,
            child: CircularProgressIndicator(
              strokeWidth: 2,
              color: foreground,
            ),
          )
        : Icon(icon, color: foreground);

    void handlePress() {
      HapticFeedback.selectionClick();
      onPressed!();
    }

    final shape = RoundedRectangleBorder(
      borderRadius: AppConstants.borderRadius16,
      side: type == AppButtonType.outlined
          ? BorderSide(color: foreground, width: 1.5)
          : BorderSide.none,
    );

    final resolvedLabel = label;
    if (resolvedLabel == null) {
      return FloatingActionButton(
        onPressed: enabled ? handlePress : null,
        backgroundColor: resolvedBackground,
        foregroundColor: foreground,
        elevation: type == AppButtonType.ghost ? 0 : null,
        mini: mini,
        shape: shape,
        tooltip: tooltip,
        heroTag: heroTag,
        child: child,
      );
    }

    return FloatingActionButton.extended(
      onPressed: enabled ? handlePress : null,
      backgroundColor: resolvedBackground,
      foregroundColor: foreground,
      elevation: type == AppButtonType.ghost ? 0 : null,
      shape: shape,
      tooltip: tooltip ?? resolvedLabel,
      heroTag: heroTag,
      icon: child,
      label: Text(
        resolvedLabel,
        style: context.textTheme.titleSmall?.copyWith(
          color: foreground,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_country.dart';
import './app_input.dart';
import './app_input_format.dart';
import './app_country_picker.dart';
import './app_input_style.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/security/validation_service.dart';
import '../../../core/utils/extensions.dart';

export './app_country.dart';

/// A phone field that masks what is typed for the country it is set to, with
/// the country picker built into its prefix.
///
///   AppPhoneInput(
///     initialCountry: 'PT',
///     onChanged: (number) => _phone = number.e164,
///   )
///
/// The field holds the *national* number and punctuates it as the user types.
/// The calling code is never in the text, so it cannot be typed twice — read
/// the joined-up value from [AppPhoneNumber.e164]. Switching country re-masks
/// what is already there rather than clearing it.
class AppPhoneInput extends StatefulWidget {
  /// Creates a phone field.
  const AppPhoneInput({
    super.key,
    this.label = 'Phone',
    this.controller,
    this.initialValue,
    this.initialCountry,
    this.countries,
    this.onChanged,
    this.onSubmitted,
    this.hint,
    this.required = false,
    this.enabled = true,
    this.readOnly = false,
    this.autoFocus = false,
    this.focusNode,
    this.textInputAction,
    this.validator,
    this.autovalidateMode,
    this.showDialCode = true,
    this.pickerTitle = 'Select a country',
    this.searchHint = 'Search country or code',
    this.labelMode,
    this.variant,
    this.type,
    this.shape,
    this.size,
  });

  /// Field label, shown wherever [AppInputConfig] puts labels.
  final String label;

  /// Controls the *national* part. Its text is the masked number, so read a
  /// clean value from [AppPhoneNumber] via [onChanged] rather than parsing it.
  final TextEditingController? controller;

  /// Seeds the field. An E.164 value picks the country too — `+351912345678`
  /// opens on Portugal — while a bare national number keeps [initialCountry].
  final String? initialValue;

  /// ISO 3166-1 alpha-2 of the country to open on. Defaults to
  /// [AppCountries.initial]. Ignored when [initialValue] carries a `+`.
  final String? initialCountry;

  /// The countries the picker offers. Defaults to [AppCountries.all]; pass a
  /// subset to restrict a form to where you actually operate.
  final List<AppCountry>? countries;

  /// Called on every keystroke and on every country change.
  final ValueChanged<AppPhoneNumber>? onChanged;

  /// Called when the keyboard's action key is pressed.
  final ValueChanged<AppPhoneNumber>? onSubmitted;

  /// Placeholder. Defaults to the country's own mask, so an empty field
  /// already shows the shape it wants.
  final String? hint;

  /// Marks the label and rejects an empty value.
  final bool required;

  final bool enabled;

  /// Shows the value without letting it be edited. The country picker is
  /// disabled too — a read-only number cannot change country.
  final bool readOnly;

  final bool autoFocus;
  final FocusNode? focusNode;
  final TextInputAction? textInputAction;

  /// Replaces the built-in rule, which checks the number is complete for its
  /// country. Receives the masked national text.
  final FormFieldValidator<String>? validator;

  final AutovalidateMode? autovalidateMode;

  /// Whether the prefix shows `+351` next to the flag. Turn off for a narrow
  /// field where the flag alone carries it.
  final bool showDialCode;

  /// Title over the country picker sheet.
  final String pickerTitle;

  /// Placeholder in the picker's search field.
  final String searchHint;

  /// Null follows [AppInputConfig.defaults].
  final AppInputLabelMode? labelMode;
  final AppInputVariant? variant;
  final AppInputType? type;
  final AppInputShape? shape;
  final AppInputSize? size;

  /// The built-in rule, exposed so a custom [validator] can build on it. Runs
  /// [ValidationService], then holds the number to its country's digit counts.
  static String? validate(
    String? value, {
    required AppCountry country,
    bool required = false,
  }) {
    final digits = _digitsOnly(value ?? '');
    if (digits.isEmpty) return required ? 'This field is required' : null;

    final result = ValidationService.validate(
      country.e164(digits),
      inputType: InputType.phone,
    );
    if (!result.isValid) return result.error;

    return country.accepts(digits)
        ? null
        : 'Enter a ${_lengths(country)} number for ${country.name}';
  }

  static String _lengths(AppCountry country) {
    final lengths = country.lengths;
    if (lengths.length == 1) return '${lengths.first}-digit';
    return '${lengths.sublist(0, lengths.length - 1).join(', ')} or '
        '${lengths.last} digit';
  }

  @override
  State<AppPhoneInput> createState() => _AppPhoneInputState();
}

class _AppPhoneInputState extends State<AppPhoneInput> {
  late AppCountry _country;
  late final TextEditingController _controller;
  late final bool _ownsController;

  @override
  void initState() {
    super.initState();

    final seeded = AppCountries.split(
      widget.initialValue ?? '',
      fallback: widget.initialCountry == null
          ? AppCountries.initial
          : AppCountries.byIso(widget.initialCountry!) ?? AppCountries.initial,
    );
    _country = seeded.country;

    _ownsController = widget.controller == null;
    _controller = widget.controller ?? TextEditingController();
    if (_controller.text.isEmpty && seeded.national.isNotEmpty) {
      _controller.text = _country.format(seeded.national);
    }
  }

  @override
  void dispose() {
    if (_ownsController) _controller.dispose();
    super.dispose();
  }

  /// What the field currently holds, as a whole number.
  AppPhoneNumber get _value =>
      AppPhoneNumber(country: _country, national: _digitsOnly(_controller.text));

  void _openPicker() async {
    // The sheet is configured once, in AppCountryPicker — the flag, the
    // calling code and the ranked search are the same here as in a standalone
    // country field, and stay that way because there is only one of them.
    final picked = await AppCountryPicker.show(
      context,
      title: widget.pickerTitle,
      searchHint: widget.searchHint,
      countries: widget.countries,
      selectedIso: _country.iso,
      variant: widget.variant,
    );
    if (picked == null || !mounted) return;
    _selectCountry(picked);
  }

  /// Re-masks the digits already in the field for the new country — Flutter
  /// only runs `inputFormatters` on an edit, so nothing else would.
  void _selectCountry(AppCountry country) {
    setState(() => _country = country);

    final digits = _digitsOnly(_controller.text);
    final reshaped = country.format(digits);
    if (reshaped != _controller.text) {
      _controller.value = TextEditingValue(
        text: reshaped,
        selection: TextSelection.collapsed(offset: reshaped.length),
      );
    }
    widget.onChanged?.call(_value);
  }

  Widget get _countrySelector {
    final accent = AppInputStyle.accentOf(context, widget.variant);
    final enabled = widget.enabled && !widget.readOnly;

    return Semantics(
      button: true,
      label: 'Country: ${_country.name}, ${_country.dialCode}',
      child: InkWell(
        onTap: enabled
            ? () {
                HapticFeedback.selectionClick();
                _openPicker();
              }
            : null,
        borderRadius: AppConstants.borderRadius12,
        child: Padding(
          padding: const EdgeInsets.symmetric(
            horizontal: AppConstants.space12,
          ),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              // The flag is an emoji, so it must not be tinted by the icon
              // theme the decoration wraps a prefix in.
              Text(
                _country.flag,
                style: const TextStyle(fontSize: _flagSize),
              ),
              if (widget.showDialCode) ...[
                const SizedBox(width: AppConstants.space4),
                Text(
                  _country.dialCode,
                  style: AppInputStyle.textStyle(
                    context,
                    size: widget.size,
                  )?.copyWith(
                    color: enabled
                        ? accent
                        : context.theme.colorScheme.onSurface.withValues(
                            alpha: AppInputStyle.config.disabledOpacity,
                          ),
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ],
              Icon(
                Icons.keyboard_arrow_down,
                size: AppInputStyle.configOf(widget.size).iconSize,
                color: enabled ? accent : null,
              ),
            ],
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return AppInput(
      label: widget.label,
      format: AppInputFormat.phone,
      controller: _controller,
      hint: widget.hint ?? _country.masks.first,
      required: widget.required,
      enabled: widget.enabled,
      readOnly: widget.readOnly,
      autoFocus: widget.autoFocus,
      focusNode: widget.focusNode,
      textInputAction: widget.textInputAction,
      // Rebuilt on every country change, which is what re-points the mask.
      inputFormatters: [PhoneNumberInputFormatter(_country)],
      prefixIcon: _countrySelector,
      validator:
          widget.validator ??
          (value) => AppPhoneInput.validate(
            value,
            country: _country,
            required: widget.required,
          ),
      autovalidateMode: widget.autovalidateMode,
      onChanged: (_) => widget.onChanged?.call(_value),
      onSubmitted: (_) => widget.onSubmitted?.call(_value),
      labelMode: widget.labelMode,
      variant: widget.variant,
      type: widget.type,
      shape: widget.shape,
      size: widget.size,
    );
  }
}

/// Types a national number in the shape [country] writes them in.
///
/// Re-picks the mask on every keystroke, so a multi-shape plan widens as the
/// number grows. Digits past the longest mask are dropped, so the plan is
/// also the length cap.
class PhoneNumberInputFormatter extends TextInputFormatter {
  /// Formats for [country].
  const PhoneNumberInputFormatter(this.country);

  /// The country whose masks are applied.
  final AppCountry country;

  @override
  TextEditingValue formatEditUpdate(
    TextEditingValue oldValue,
    TextEditingValue newValue,
  ) {
    final trailing = _digitsAfterCaret(newValue);
    final text = country.format(newValue.text);
    return TextEditingValue(
      text: text,
      selection: TextSelection.collapsed(
        offset: _offsetLeaving(text, trailing),
      ),
    );
  }
}

/// Flags are emoji, so they are sized as text rather than as an icon.
const double _flagSize = 20;

final RegExp _nonDigits = RegExp(r'\D');
final RegExp _digit = RegExp(r'\d');

String _digitsOnly(String value) => value.replaceAll(_nonDigits, '');

/// How many digits sit after the caret — the part of the value an edit leaves
/// untouched, and so the anchor the re-masked string can be measured against.
int _digitsAfterCaret(TextEditingValue value) {
  final caret = value.selection.end;
  if (caret < 0 || caret > value.text.length) return 0;
  return _digitsOnly(value.text.substring(caret)).length;
}

/// The offset in [text] that leaves exactly [digits] digits after it.
int _offsetLeaving(String text, int digits) {
  if (digits <= 0) return text.length;
  var seen = 0;
  for (var i = text.length - 1; i >= 0; i--) {
    if (_digit.hasMatch(text[i])) {
      seen++;
      if (seen == digits) return i;
    }
  }
  return 0;
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_country.dart';
import './app_input_style.dart';
import './input_title.dart';
import './search_picker_sheet.dart';
import '../../../core/constants/app_constants.dart';

/// What a country reads as in a closed field.
enum AppCountryDisplay {
  /// `🇵🇹 Portugal` — the default, and what a shipping or address field wants.
  flagAndName,

  /// `Portugal`.
  name,

  /// `🇵🇹 +351` — for a narrow field where the name will not fit.
  flagAndDialCode,

  /// `🇵🇹` alone.
  flag,
}

/// Picks one of the 238 countries in [AppCountries].
///
/// Two ways in. As a field, validating like the rest of the family:
///
/// ```dart
/// AppCountryPicker(
///   label: 'Country',
///   selectedIso: _iso,
///   required: true,
///   onChanged: (country) => setState(() => _iso = country.iso),
/// )
/// ```
///
/// Or as a sheet on its own, for a country picked from somewhere that is not
/// a form — a filter, a settings row, the prefix of a phone field:
///
/// ```dart
/// final country = await AppCountryPicker.show(context, selectedIso: _iso);
/// ```
///
/// [show] is the single place the country sheet is configured — the flag
/// leading each row, the calling code trailing it, and the ranked search that
/// makes `PT` find Portugal rather than the first country whose name happens
/// to contain those letters. `AppPhoneInput` opens this same sheet for its
/// prefix, so the two can never drift apart.
class AppCountryPicker extends StatelessWidget {
  const AppCountryPicker({
    super.key,
    required this.onChanged,
    this.label = 'Country',
    this.selectedIso,
    this.hint = 'Select a country',
    this.display = AppCountryDisplay.flagAndName,
    this.countries,
    this.enabled = true,
    this.required = false,
    this.validator,
    this.autovalidateMode,
    this.showDialCodeInSheet = true,
    this.pickerTitle,
    this.searchHint = 'Search country',
    this.onCleared,
    this.prefixIcon,
    this.suffixIcon,
    this.labelMode,
    this.variant,
    this.type,
    this.shape,
    this.size,
  });

  /// Called with the whole country, not just its code — the caller usually
  /// wants the dial code or the flag as well, and looking it back up by ISO
  /// to get them is work this already did.
  final ValueChanged<AppCountry> onChanged;

  final String label;

  /// The current selection, by ISO 3166-1 alpha-2. Unknown or null shows
  /// [hint].
  final String? selectedIso;

  final String hint;
  final AppCountryDisplay display;

  /// Narrows the list — the countries you ship to, the ones you have numbers
  /// for. Null offers all of [AppCountries.all].
  final List<AppCountry>? countries;

  final bool enabled;

  /// Marks the label and, unless [validator] replaces the rule, rejects an
  /// empty selection when the form validates.
  final bool required;

  /// Replaces the built-in rule. Receives the selected ISO code, or null.
  final String? Function(String? iso)? validator;

  final AutovalidateMode? autovalidateMode;

  /// Shows `+351` at the end of each row in the sheet. Off for a plain
  /// country list where the calling code is noise.
  final bool showDialCodeInSheet;

  /// Heading over the sheet. Defaults to [label].
  final String? pickerTitle;

  final String searchHint;

  /// Offers a clear button once something is selected. Without it the field
  /// cannot be emptied again.
  final VoidCallback? onCleared;

  final Widget? prefixIcon;

  /// Replaces the chevron — and with it the clear button.
  final Widget? suffixIcon;

  /// Null follows [AppInputConfig.defaults].
  final AppInputLabelMode? labelMode;
  final AppInputVariant? variant;
  final AppInputType? type;
  final AppInputShape? shape;
  final AppInputSize? size;

  static const double _flagSize = 20;

  /// Opens the country sheet and resolves to the pick, or null if it was
  /// dismissed.
  ///
  /// The one configuration of the sheet, shared with `AppPhoneInput`.
  static Future<AppCountry?> show(
    BuildContext context, {
    String? selectedIso,
    List<AppCountry>? countries,
    String title = 'Select a country',
    String searchHint = 'Search country',
    bool showDialCode = true,
    AppInputVariant? variant,
  }) {
    return SearchPickerSheet.show<AppCountry>(
      context,
      title: title,
      searchHint: searchHint,
      items: countries ?? AppCountries.all,
      idOf: (country) => country.iso,
      labelOf: (country) => country.name,
      trailingLabelOf: showDialCode ? (country) => country.dialCode : null,
      leadingOf: (country) => Text(
        country.flag,
        style: const TextStyle(fontSize: _flagSize),
      ),
      // Ranked, so two letters find the country whose code they are rather
      // than the first country whose name happens to contain them.
      filter: (countries, query) => AppCountries.search(query, within: countries),
      selectedId: selectedIso,
      variant: variant,
    );
  }

  /// The rule applied when no [validator] is given.
  ///
  /// Exposed so a custom [validator] can layer onto it rather than replace
  /// it:
  ///
  ///   validator: (iso) =>
  ///       AppCountryPicker.validate(iso, required: true) ??
  ///       (_blocked.contains(iso) ? 'We do not ship there yet' : null),
  static String? validate(String? iso, {bool required = false}) {
    if (required && (iso == null || iso.isEmpty)) {
      return 'This field is required';
    }
    return null;
  }

  AppCountry? get _selected {
    final iso = selectedIso;
    return iso == null ? null : AppCountries.byIso(iso);
  }

  String _labelFor(AppCountry country) => switch (display) {
        AppCountryDisplay.flagAndName => '${country.flag}  ${country.name}',
        AppCountryDisplay.name => country.name,
        AppCountryDisplay.flagAndDialCode =>
          '${country.flag}  ${country.dialCode}',
        AppCountryDisplay.flag => country.flag,
      };

  Future<void> _open(
    BuildContext context,
    FormFieldState<String> state,
  ) async {
    HapticFeedback.selectionClick();
    final picked = await show(
      context,
      selectedIso: selectedIso,
      countries: countries,
      title: pickerTitle ?? label,
      searchHint: searchHint,
      showDialCode: showDialCodeInSheet,
      variant: variant,
    );
    if (picked == null) return;
    state.didChange(picked.iso);
    onChanged(picked);
  }

  @override
  Widget build(BuildContext context) {
    final country = _selected;

    return InputFieldLayout(
      label: label,
      required: required,
      labelMode: labelMode,
      variant: variant,
      size: size,
      field: FormField<String>(
        initialValue: selectedIso,
        enabled: enabled,
        autovalidateMode:
            autovalidateMode ?? AppInputStyle.config.autovalidateMode,
        // Judged on [selectedIso] rather than on the value this FormField
        // happens to hold: the caller owns the selection, so its answer is
        // the true one even before a rebuild has reached here.
        validator: (_) {
          final rule = validator;
          return rule != null
              ? rule(selectedIso)
              : validate(selectedIso, required: required);
        },
        builder: (state) => MergeSemantics(
          // An InkWell announces nothing on its own; without this a screen
          // reader reads out the country and never says it can be opened.
          child: Semantics(
            button: true,
            enabled: enabled,
            child: InkWell(
              onTap: enabled ? () => _open(context, state) : null,
              borderRadius: AppConstants.borderRadius12,
              child: InputDecorator(
                decoration: AppInputStyle.decoration(
                  context,
                  variant: variant,
                  type: type,
                  shape: shape,
                  size: size,
                  label: label,
                  labelMode: labelMode,
                  required: required,
                  hint: hint,
                  prefixIcon: prefixIcon,
                  suffixIcon: suffixIcon ?? _trailing(state, country),
                  enabled: enabled,
                ).copyWith(errorText: state.errorText),
                // Drives the hint and the floating label the way an empty
                // text field would.
                isEmpty: country == null,
                child: country == null
                    ? null
                    : Text(
                        _labelFor(country),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: AppInputStyle.textStyle(context, size: size),
                      ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  /// The chevron, or a clear button when there is something to clear and
  /// somewhere to report it. A disabled field shows neither action.
  Widget _trailing(FormFieldState<String> state, AppCountry? country) {
    final clear = onCleared;
    if (clear == null || country == null || !enabled) {
      return const Icon(Icons.keyboard_arrow_down);
    }
    return IconButton(
      icon: const Icon(Icons.close),
      onPressed: () {
        HapticFeedback.selectionClick();
        state.didChange(null);
        clear();
      },
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_input_format.dart';
import './app_input_style.dart';
import './input_title.dart';
import '../../../core/security/validation_service.dart';

/// A labeled text field — the kit's default way to collect a value.
///
/// [format] is the knob that matters: it picks the keyboard, the formatters
/// that keep junk out while typing, the autofill hints and the validation rule
/// in one go, so a money field only ever holds money.
///
///   AppInput(label: 'Email', format: AppInputFormat.email, required: true)
///   AppInput(label: 'Amount', format: AppInputFormat.money)
///   AppInput(label: 'Card', format: AppInputFormat.creditCard)
///
/// A formatted field still reads back as a plain value:
/// `AppInputFormat.money.unformat(controller.text)`.
///
/// Every decision the format makes can be overridden on the field —
/// [keyboardType], [inputFormatters], [autofillHints], [textCapitalization],
/// [obscureText], [maxLength], [validator].
///
/// How it *looks* — where the label goes, which variant, type, shape and size —
/// comes from [AppInputConfig.defaults] unless this field says otherwise, so
/// the app has one place to change its mind.
class AppInput extends StatefulWidget {
  const AppInput({
    super.key,
    required this.label,
    this.format = AppInputFormat.text,
    this.controller,
    this.initialValue,
    this.hint,
    this.required = false,
    this.enabled = true,
    this.readOnly = false,
    this.autoFocus = false,
    this.focusNode,
    this.maxLines = 1,
    this.minLines,
    this.maxLength,
    this.showCounter,
    this.obscureText,
    this.showPasswordToggle = true,
    this.keyboardType,
    this.textInputAction,
    this.textCapitalization,
    this.inputFormatters,
    this.autofillHints,
    this.prefixIcon,
    this.suffixIcon,
    this.validator,
    this.autovalidateMode,
    this.onChanged,
    this.onSubmitted,
    this.onTap,
    this.textAlign = TextAlign.start,
    this.labelMode,
    this.variant,
    this.type,
    this.shape,
    this.size,
  });

  final String label;

  /// What the field holds. Drives keyboard, formatters, autofill and
  /// validation together — see [AppInputFormat].
  final AppInputFormat format;

  final TextEditingController? controller;

  /// Seeds the field. With a [controller] it is only used while the controller
  /// is still empty, so an already-populated controller is never clobbered.
  final String? initialValue;

  final String? hint;

  /// Marks the label with an asterisk and rejects an empty value.
  final bool required;

  /// A disabled field is greyed out and cannot be focused.
  final bool enabled;

  /// A read-only field is styled normally but cannot be edited. Without an
  /// [onTap] it ignores pointers entirely; with one it stays tappable, which is
  /// how the picker-backed inputs are built.
  final bool readOnly;

  final bool autoFocus;
  final FocusNode? focusNode;

  /// Lines the field shows. An [AppInputFormat.multiline] field opens at five
  /// unless you say otherwise; `null` grows without limit.
  final int? maxLines;
  final int? minLines;

  /// Character cap. Defaults to the format's own where it has one (a card
  /// number, an expiry).
  final int? maxLength;

  /// Whether [maxLength] shows its counter. Null follows the config.
  final bool? showCounter;

  /// Hides the value. Defaults to the format's own answer — only
  /// [AppInputFormat.password] hides by default.
  final bool? obscureText;

  /// Shows the eye that reveals an obscured value, unless [suffixIcon] takes
  /// the slot. Turn it off for a value that should never be revealed.
  final bool showPasswordToggle;

  /// Overrides [AppInputFormat.keyboardType].
  final TextInputType? keyboardType;

  final TextInputAction? textInputAction;

  /// Overrides [AppInputFormat.textCapitalization].
  final TextCapitalization? textCapitalization;

  /// Replaces [AppInputFormat.formatters]. To keep them and add your own,
  /// spread them: `[...AppInputFormat.money.formatters, myFormatter]`.
  final List<TextInputFormatter>? inputFormatters;

  /// Overrides [AppInputFormat.autofillHints].
  final List<String>? autofillHints;

  final Widget? prefixIcon;
  final Widget? suffixIcon;

  /// Replaces the built-in rule entirely. Call [AppInput.validate] from inside
  /// it to add a rule on top instead of dropping validation.
  final String? Function(String? value)? validator;

  /// When the field validates itself. Null follows the config, which starts at
  /// Flutter's own default — on submit only.
  final AutovalidateMode? autovalidateMode;

  final ValueChanged<String>? onChanged;
  final ValueChanged<String>? onSubmitted;
  final VoidCallback? onTap;

  /// Alignment of the typed value and the hint. The label follows it too.
  final TextAlign textAlign;

  /// Where this field's label goes. Null follows the config — see
  /// [AppInputLabelMode].
  final AppInputLabelMode? labelMode;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;
  final AppInputType? type;
  final AppInputShape? shape;
  final AppInputSize? size;

  /// The rule an [AppInput] applies when no [validator] is given: required
  /// first, then the format's own [ValidationService] check on the unformatted
  /// value. Empty optional fields pass.
  ///
  /// Exposed so a custom [validator] can layer on top of it:
  ///
  ///   validator: (v) =>
  ///       AppInput.validate(v, format: AppInputFormat.email, required: true) ??
  ///       (v!.endsWith('@work.com') ? null : 'Use your work address'),
  static String? validate(
    String? value, {
    AppInputFormat format = AppInputFormat.text,
    bool required = false,
  }) {
    final text = value ?? '';
    if (required && text.trim().isEmpty) return 'This field is required';
    if (text.isEmpty) return null;

    final result = ValidationService.validate(
      format.unformat(text),
      inputType: format.validationType,
    );
    return result.isValid ? null : result.error;
  }

  @override
  State<AppInput> createState() => _AppInputState();
}

class _AppInputState extends State<AppInput> {
  late bool _obscured;

  /// The format actually in force: an explicit [AppInput.format] wins, then the
  /// one a bare `keyboardType:` implies — so fields written before formats
  /// existed keep validating the way they did.
  AppInputFormat get _format => widget.format != AppInputFormat.text
      ? widget.format
      : AppInputFormat.forKeyboardType(widget.keyboardType) ??
            AppInputFormat.text;

  /// Whether this field hides its value at all — the eye shows for the whole
  /// life of such a field, not only while the value is hidden.
  bool get _obscurable => widget.obscureText ?? _format.isObscured;

  /// Where this field's label goes: its own answer, else the app's.
  AppInputLabelMode get _labelMode =>
      widget.labelMode ?? AppInputStyle.config.labelMode;

  @override
  void initState() {
    super.initState();
    _obscured = _obscurable;

    final controller = widget.controller;
    if (controller != null &&
        controller.text.isEmpty &&
        widget.initialValue != null) {
      controller.text = widget.initialValue!;
    }
  }

  @override
  void didUpdateWidget(AppInput oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.obscureText != oldWidget.obscureText ||
        widget.format != oldWidget.format) {
      _obscured = _obscurable;
    }
  }

  /// An obscured field is single-line by force; a multiline one opens at five
  /// lines unless the caller pinned a value.
  int? get _maxLines {
    if (_obscured) return 1;
    if (_format.isMultiline && widget.maxLines == 1) return 5;
    return widget.maxLines;
  }

  /// The caller's suffix, else the show/hide eye when there is one to show.
  Widget? get _suffixIcon {
    if (widget.suffixIcon != null) return widget.suffixIcon;
    if (!_obscurable || !widget.showPasswordToggle) return null;
    return IconButton(
      onPressed: () {
        HapticFeedback.selectionClick();
        setState(() => _obscured = !_obscured);
      },
      tooltip: _obscured ? 'Show' : 'Hide',
      icon: Icon(
        _obscured ? Icons.visibility_off_outlined : Icons.visibility_outlined,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final format = _format;
    final accent = AppInputStyle.accentOf(context, widget.variant);

    final field = TextFormField(
      controller: widget.controller,
      initialValue: widget.controller == null ? widget.initialValue : null,
      focusNode: widget.focusNode,
      autofocus: widget.autoFocus,
      enabled: widget.enabled,
      readOnly: widget.readOnly,
      obscureText: _obscured,
      maxLines: _maxLines,
      minLines: widget.minLines,
      maxLength: widget.maxLength ?? format.maxLength,
      keyboardType: widget.keyboardType ?? format.keyboardType,
      textInputAction: widget.textInputAction,
      textCapitalization:
          widget.textCapitalization ?? format.textCapitalization,
      textAlign: widget.textAlign,
      inputFormatters: widget.inputFormatters ?? format.formatters,
      autofillHints: widget.autofillHints ?? format.autofillHints,
      autovalidateMode:
          widget.autovalidateMode ?? AppInputStyle.config.autovalidateMode,
      validator:
          widget.validator ??
          (value) => AppInput.validate(
            value,
            format: format,
            required: widget.required,
          ),
      onChanged: widget.onChanged,
      onFieldSubmitted: widget.onSubmitted,
      onTap: widget.onTap,
      cursorColor: accent,
      style: AppInputStyle.textStyle(
        context,
        size: widget.size,
      )?.copyWith(color: accent, fontWeight: FontWeight.bold),
      decoration: AppInputStyle.decoration(
        context,
        variant: widget.variant,
        type: widget.type,
        shape: widget.shape,
        size: widget.size,
        label: widget.label,
        labelMode: _labelMode,
        required: widget.required,
        hint: widget.hint,
        enabled: widget.enabled,
        showCounter: widget.showCounter,
        // A label floating over several lines of text belongs at the first
        // line, not centred against the whole box.
        alignLabelWithHint: _maxLines != 1,
        prefixIcon: widget.prefixIcon,
        suffixIcon: _suffixIcon,
      ),
    );

    return InputFieldLayout(
      label: widget.label,
      required: widget.required,
      labelMode: _labelMode,
      variant: widget.variant,
      size: widget.size,
      textAlign: widget.textAlign,
      // A read-only field with nothing to tap shouldn't take focus or raise a
      // keyboard either.
      field: widget.readOnly && widget.onTap == null
          ? IgnorePointer(child: field)
          : field,
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import './app_input_style.dart';
import './app_search_field.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// A bottom sheet that picks one row out of a long list, with a search field
/// pinned above it.
///
/// A dropdown menu stops being usable somewhere around thirty options, which is
/// why [AppDropdownInput] opens this once it is told `searchable: true`, and why
/// the country selector on `AppPhoneInput` — 238 rows — uses nothing else.
///
/// Generic over the row type, so callers keep their own entities:
///
/// ```dart
/// final picked = await SearchPickerSheet.show<CategoryEntity>(
///   context,
///   title: 'Category',
///   items: categories,
///   idOf: (item) => item.id,
///   labelOf: (item) => item.name,
///   selectedId: _categoryId,
/// );
/// ```
///
/// Resolves to the picked item, or null when the sheet is dismissed.
///
/// [showMulti] opens the same sheet with a checkbox per row and a Done button —
/// what [AppMultiSelectInput] uses. One sheet covers both because everything
/// that makes this sheet worth having (the search, the filter, opening at the
/// current selection) is the same either way.
class SearchPickerSheet<T> extends StatefulWidget {
  /// Creates the sheet. Prefer [show] or [showMulti], which open it with the
  /// modal settings a full-height searchable sheet needs.
  const SearchPickerSheet({
    super.key,
    required this.title,
    required this.items,
    required this.idOf,
    required this.labelOf,
    this.selectedId,
    this.selectedIds = const [],
    this.multiSelect = false,
    this.maxSelected,
    this.doneLabel = 'Done',
    this.searchHint = 'Search',
    this.leadingOf,
    this.trailingLabelOf,
    this.filter,
    this.emptyLabel = 'Nothing matches that search',
    this.variant,
  });

  /// Heading over the search field.
  final String title;

  /// Rows to choose from.
  final List<T> items;

  /// Extracts the id used to mark the current selection.
  final String Function(T item) idOf;

  /// Extracts the row's display text — and, unless [matches] says otherwise,
  /// the text the query is compared against.
  final String Function(T item) labelOf;

  /// The row to mark as current and to open the list scrolled to.
  final String? selectedId;

  /// The rows already ticked, when [multiSelect]. The sheet works on its own
  /// copy and reports the result once, so a dismissed sheet changes nothing.
  final List<String> selectedIds;

  /// Puts a checkbox on every row and a Done button under the list. Tapping a
  /// row toggles it instead of closing the sheet.
  final bool multiSelect;

  /// Ceiling on how many may be ticked. At the limit the unticked rows stop
  /// responding — better than letting the user pick a sixth of five and having
  /// the form refuse it afterwards. Only read when [multiSelect].
  final int? maxSelected;

  /// Copy on the confirm button. Only read when [multiSelect].
  final String doneLabel;

  /// Placeholder in the search field.
  final String searchHint;

  /// Optional leading widget per row — a flag, an avatar, an icon.
  final Widget Function(T item)? leadingOf;

  /// Optional dimmed text at the end of a row, for a secondary value like a
  /// calling code.
  final String Function(T item)? trailingLabelOf;

  /// Replaces the default filter, which is a case-insensitive `contains` over
  /// [labelOf].
  ///
  /// Returns the rows to show *in the order to show them*, so a caller can
  /// rank matches as well as select them — which is how the country picker
  /// keeps Portugal above Egypt for the query `PT`.
  final List<T> Function(List<T> items, String query)? filter;

  /// Shown in place of the list when nothing matches.
  final String emptyLabel;

  /// Null follows [AppInputConfig.defaults].
  final AppInputVariant? variant;

  /// Opens the sheet and resolves to the picked item, or null if dismissed.
  static Future<T?> show<T>(
    BuildContext context, {
    required String title,
    required List<T> items,
    required String Function(T item) idOf,
    required String Function(T item) labelOf,
    String? selectedId,
    String searchHint = 'Search',
    Widget Function(T item)? leadingOf,
    String Function(T item)? trailingLabelOf,
    List<T> Function(List<T> items, String query)? filter,
    String emptyLabel = 'Nothing matches that search',
    AppInputVariant? variant,
  }) {
    return showModalBottomSheet<T>(
      context: context,
      // The sheet has to be free to grow past half the screen and to sit above
      // the keyboard the search field raises.
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => SearchPickerSheet<T>(
        title: title,
        items: items,
        idOf: idOf,
        labelOf: labelOf,
        selectedId: selectedId,
        searchHint: searchHint,
        leadingOf: leadingOf,
        trailingLabelOf: trailingLabelOf,
        filter: filter,
        emptyLabel: emptyLabel,
        variant: variant,
      ),
    );
  }

  /// Opens the sheet in multi-select mode and resolves to everything ticked
  /// when Done was tapped, or null if it was dismissed.
  ///
  /// An empty list and null mean different things: the first is a deliberate
  /// "none of them", the second is "leave it as it was".
  static Future<List<T>?> showMulti<T>(
    BuildContext context, {
    required String title,
    required List<T> items,
    required String Function(T item) idOf,
    required String Function(T item) labelOf,
    List<String> selectedIds = const [],
    int? maxSelected,
    String doneLabel = 'Done',
    String searchHint = 'Search',
    Widget Function(T item)? leadingOf,
    String Function(T item)? trailingLabelOf,
    List<T> Function(List<T> items, String query)? filter,
    String emptyLabel = 'Nothing matches that search',
    AppInputVariant? variant,
  }) {
    return showModalBottomSheet<List<T>>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => SearchPickerSheet<T>(
        title: title,
        items: items,
        idOf: idOf,
        labelOf: labelOf,
        selectedIds: selectedIds,
        multiSelect: true,
        maxSelected: maxSelected,
        doneLabel: doneLabel,
        searchHint: searchHint,
        leadingOf: leadingOf,
        trailingLabelOf: trailingLabelOf,
        filter: filter,
        emptyLabel: emptyLabel,
        variant: variant,
      ),
    );
  }

  @override
  State<SearchPickerSheet<T>> createState() => _SearchPickerSheetState<T>();
}

class _SearchPickerSheetState<T> extends State<SearchPickerSheet<T>> {
  late final ScrollController _scrollController = ScrollController(
    initialScrollOffset: _initialOffset,
  );
  String _query = '';

  /// The sheet's own copy of a multi-select selection: it is reported once, on
  /// Done, so backing out of the sheet leaves the caller's list untouched.
  late final Set<String> _picked = {...widget.selectedIds};

  /// Opens the list already showing the current selection, so a picker over a
  /// long table doesn't start hundreds of rows away from the answer.
  ///
  /// Exact rather than estimated because the rows are a fixed [_rowHeight].
  double get _initialOffset {
    // In multi-select the first tick is the one to open at — it is where the
    // user was working, and later ones are usually near it.
    final selectedId =
        widget.selectedId ??
        (widget.selectedIds.isEmpty ? null : widget.selectedIds.first);
    if (selectedId == null) return 0;
    final index = widget.items.indexWhere(
      (item) => widget.idOf(item) == selectedId,
    );
    return index <= 0 ? 0 : index * _rowHeight;
  }

  /// True once as many rows are ticked as [SearchPickerSheet.maxSelected]
  /// allows.
  bool get _atLimit =>
      widget.maxSelected != null && _picked.length >= widget.maxSelected!;

  /// Everything ticked, in [SearchPickerSheet.items] order rather than in the
  /// order it was tapped — which is the order a caller wants to store.
  List<T> get _pickedItems => [
    for (final item in widget.items)
      if (_picked.contains(widget.idOf(item))) item,
  ];

  void _toggle(String id) {
    HapticFeedback.selectionClick();
    setState(() {
      if (!_picked.remove(id)) _picked.add(id);
    });
  }

  List<T> get _filtered {
    final filter = widget.filter;
    if (filter != null) return filter(widget.items, _query);

    final needle = _query.trim().toLowerCase();
    if (needle.isEmpty) return widget.items;
    return [
      for (final item in widget.items)
        if (widget.labelOf(item).toLowerCase().contains(needle)) item,
    ];
  }

  void _onQueryChanged(String query) {
    setState(() => _query = query);
    // The previous offset means nothing against a freshly filtered list, and
    // may well be past its end.
    if (_scrollController.hasClients) _scrollController.jumpTo(0);
  }

  @override
  void dispose() {
    _scrollController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final mediaQuery = MediaQuery.of(context);
    final accent = AppInputStyle.accentOf(context, widget.variant);
    final rows = _filtered;

    return Padding(
      padding: EdgeInsets.only(bottom: mediaQuery.viewInsets.bottom),
      child: Container(
        constraints: BoxConstraints(
          maxHeight: mediaQuery.size.height * _maxHeightFactor,
        ),
        decoration: BoxDecoration(
          color: theme.colorScheme.surface,
          borderRadius: const BorderRadius.vertical(
            top: Radius.circular(AppConstants.radius24),
          ),
        ),
        child: SafeArea(
          top: false,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Padding(
                padding: AppConstants.padding16,
                child: Column(
                  children: [
                    Text(
                      widget.title,
                      style: theme.textTheme.titleMedium?.copyWith(
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    const SizedBox(height: AppConstants.space12),
                    AppSearchField(
                      hint: widget.searchHint,
                      autofocus: true,
                      variant: widget.variant,
                      onChanged: _onQueryChanged,
                    ),
                  ],
                ),
              ),
              Divider(height: 1, color: theme.colorScheme.outlineVariant),
              Flexible(
                child: rows.isEmpty
                    ? Padding(
                        padding: AppConstants.padding24,
                        child: Text(
                          widget.emptyLabel,
                          style: theme.textTheme.bodyMedium?.copyWith(
                            color: theme.colorScheme.onSurfaceVariant,
                          ),
                        ),
                      )
                    : ListView.builder(
                        controller: _scrollController,
                        // A fixed extent is what makes _initialOffset exact,
                        // and it keeps a 238-row list cheap to scroll.
                        itemExtent: _rowHeight,
                        padding: EdgeInsets.zero,
                        itemCount: rows.length,
                        itemBuilder: (context, index) {
                          final item = rows[index];
                          final id = widget.idOf(item);
                          final selected = widget.multiSelect
                              ? _picked.contains(id)
                              : id == widget.selectedId;
                          final trailing = widget.trailingLabelOf?.call(item);
                          // Past the ceiling only the ticked rows still answer:
                          // offering a pick the caller has to throw away is
                          // worse than showing it can't be made.
                          final enabled =
                              !widget.multiSelect || selected || !_atLimit;

                          return ListTile(
                            enabled: enabled,
                            selected: selected,
                            selectedColor: accent,
                            leading: widget.leadingOf?.call(item),
                            title: Text(
                              widget.labelOf(item),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: selected
                                  ? const TextStyle(fontWeight: FontWeight.bold)
                                  : null,
                            ),
                            trailing: _rowTrailing(
                              theme: theme,
                              accent: accent,
                              trailingLabel: trailing,
                              selected: selected,
                              enabled: enabled,
                              id: id,
                            ),
                            onTap: enabled
                                ? () {
                                    if (widget.multiSelect) {
                                      _toggle(id);
                                      return;
                                    }
                                    HapticFeedback.selectionClick();
                                    Navigator.pop(context, item);
                                  }
                                : null,
                          );
                        },
                      ),
              ),
              if (widget.multiSelect) _confirmBar(theme, accent),
            ],
          ),
        ),
      ),
    );
  }

  /// The end of a row: its secondary label, and in multi-select the checkbox
  /// that says whether it is in.
  Widget? _rowTrailing({
    required ThemeData theme,
    required Color accent,
    required String? trailingLabel,
    required bool selected,
    required bool enabled,
    required String id,
  }) {
    final label = trailingLabel == null
        ? null
        : Text(
            trailingLabel,
            style: theme.textTheme.bodyMedium?.copyWith(
              color: selected ? accent : theme.colorScheme.onSurfaceVariant,
            ),
          );

    if (!widget.multiSelect) return label;

    final checkbox = Checkbox(
      value: selected,
      activeColor: accent,
      // The whole row is the target — the box only has to report the state, and
      // a second tap handler here would double the haptics.
      onChanged: enabled ? (_) => _toggle(id) : null,
    );

    if (label == null) return checkbox;
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [label, checkbox],
    );
  }

  /// The bar under a multi-select list: how many are in, and the button that
  /// commits them.
  Widget _confirmBar(ThemeData theme, Color accent) {
    final max = widget.maxSelected;
    return Container(
      padding: AppConstants.padding16,
      decoration: BoxDecoration(
        border: Border(
          top: BorderSide(color: theme.colorScheme.outlineVariant),
        ),
      ),
      child: Row(
        spacing: AppConstants.space12,
        children: [
          Expanded(
            child: Text(
              max == null
                  ? '${_picked.length} selected'
                  : '${_picked.length} of $max selected',
              style: theme.textTheme.bodyMedium?.copyWith(
                color: theme.colorScheme.onSurfaceVariant,
              ),
            ),
          ),
          FilledButton(
            style: FilledButton.styleFrom(backgroundColor: accent),
            onPressed: () {
              HapticFeedback.selectionClick();
              Navigator.pop(context, _pickedItems);
            },
            child: Text(widget.doneLabel),
          ),
        ],
      ),
    );
  }
}

/// Rows are a fixed height so the list can be opened at an exact offset.
const double _rowHeight = 56;

/// How much of the screen the sheet may take before its list scrolls.
const double _maxHeightFactor = 0.85;

