/// A single selectable chip styled from [AppInputVariant]. Lay several out in a
/// [Wrap] for a multi-select tag/filter row.
class AppChoiceChip extends StatelessWidget {
  const AppChoiceChip({
    super.key,
    required this.label,
    required this.selected,
    required this.onSelected,
    this.icon,
    this.variant,
  });

  final String label;
  final bool selected;

  /// Pass null to render the chip disabled.
  final ValueChanged<bool>? onSelected;

  final IconData? icon;
  final AppInputVariant? variant;

  @override
  Widget build(BuildContext context) {
    final theme = context.theme;
    final accent = AppInputStyle.accentOf(context, variant);
    final onAccent = AppInputStyle.onAccentOf(context, variant);

    return ChoiceChip(
      label: Text(label),
      selected: selected,
      showCheckmark: false,
      avatar: icon == null
          ? null
          : Icon(
              icon,
              size: AppConstants.iconSmall,
              color: selected ? onAccent : accent,
            ),
      labelStyle: theme.textTheme.labelLarge?.copyWith(
        color: selected ? onAccent : theme.colorScheme.onSurface,
      ),
      selectedColor: accent,
      backgroundColor: theme.colorScheme.surfaceContainerLowest,
      side: BorderSide.none,
      shape: RoundedRectangleBorder(borderRadius: AppConstants.borderRadiusFull),
      // Null is what disables a ChoiceChip; there is no `enabled` flag.
      onSelected: onSelected == null
          ? null
          : (v) {
              HapticFeedback.selectionClick();
              onSelected!(v);
            },
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import './app_input_style.dart';
import './input_title.dart';
import '../../../core/constants/app_constants.dart';
import '../../../core/utils/extensions.dart';

/// A vertical single-select list of labeled radio options, colored from
/// [AppInputVariant]. The whole row is tappable, not just the dot. Built on the
/// current [RadioGroup] ancestor API (requires Flutter 3.32+).
///
/// `required: true` refuses to validate while [groupValue] is still null, and
/// says so under the list.
class AppRadioGroup<T> extends StatelessWidget {
  const AppRadioGroup({
    super.key,
    required this.values,
    required this.groupValue,
    required this.labelOf,
    required this.onChanged,
    this.subtitleOf,
    this.required = false,
    this.requiredError = 'Please choose an option',
    this.validator,
    this.autovalidateMode,
    this.variant,
  });

  final List<T> values;

  /// The chosen option, or null while nothing is chosen. Must be one of
  /// [values]; anything else would draw a list with nothing selected, so it is
  /// caught by an assert instead.
  final T? groupValue;

  final String Function(T value) labelOf;
  final String? Function(T value)? subtitleOf;

  /// Pass null to render the whole group disabled.
  final ValueChanged<T>? onChanged;

  /// Refuses to validate until an option is chosen.
  final bool required;

  /// What a [required] group says while nothing is chosen.
  final String requiredError;

  /// Replaces the built-in rule entirely. Returning null means valid.
  final String? Function(T? value)? validator;

  /// When the group validates itself. Null follows the config.
  final AutovalidateMode? autovalidateMode;

  final AppInputVariant? variant;

  /// The rule in force: the caller's, else the required check, else nothing to
  /// enforce at all.
  String? Function(T? value)? get _rule {
    if (validator != null) return validator;
    if (!required) return null;
    return (value) => value == null ? requiredError : null;
  }

  @override
  Widget build(BuildContext context) {
    assert(
      groupValue == null || values.contains(groupValue),
      'AppRadioGroup<$T>: groupValue is not one of values, so the list would '
      'render with nothing selected.',
    );

    final accent = AppInputStyle.accentOf(context, variant);
    final enabled = onChanged != null;

    return SelectionFormField<T?>(
      value: groupValue,
      validator: _rule,
      enabled: enabled,
      autovalidateMode: autovalidateMode,
      builder: (state) {
        void select(T value) {
          HapticFeedback.selectionClick();
          // Tells the FormField it has been interacted with, so a form set to
          // validate on interaction drops the error as soon as one is chosen.
          state.didChange(value);
          onChanged!(value);
        }

        return RadioGroup<T>(
          groupValue: groupValue,
          onChanged: (value) {
            if (value != null && enabled) select(value);
          },
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              for (final value in values)
                InkWell(
                  borderRadius: AppConstants.borderRadius8,
                  onTap: enabled ? () => select(value) : null,
                  child: Padding(
                    padding: const EdgeInsets.symmetric(
                      vertical: AppConstants.space4,
                    ),
                    child: Row(
                      children: [
                        // The row's InkWell drives selection, so the Radio is
                        // display-only; the RadioGroup above supplies its
                        // state.
                        IgnorePointer(
                          child: Radio<T>(
                            value: value,
                            activeColor: accent,
                            materialTapTargetSize:
                                MaterialTapTargetSize.shrinkWrap,
                          ),
                        ),
                        const SizedBox(width: AppConstants.space8),
                        Expanded(
                          child: _RadioLabel(
                            label: labelOf(value),
                            subtitle: subtitleOf?.call(value),
                            enabled: enabled,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
            ],
          ),
        );
      },
    );
  }
}

/// One row's text. Pulled out so [AppRadioGroup.subtitleOf] is asked once per
/// row instead of once to test for null and again to read the value.
class _RadioLabel extends StatelessWidget {
  const _RadioLabel({
    required this.label,
    required this.subtitle,
    required this.enabled,
  });

  final String label;
  final String? subtitle;
  final bool enabled;

  @override
  Widget build(BuildContext context) {
    final textTheme = context.textTheme;
    final colorScheme = context.colorScheme;
    final disabled = colorScheme.onSurface.withValues(
      alpha: AppInputStyle.config.disabledOpacity,
    );

    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          label,
          style: textTheme.bodyLarge?.copyWith(
            color: enabled ? null : disabled,
          ),
        ),
        if (subtitle != null)
          Text(
            subtitle!,
            style: textTheme.bodySmall?.copyWith(
              color: enabled ? colorScheme.onSurfaceVariant : disabled,
            ),
          ),
      ],
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import './app_input_style.dart';
import './input_title.dart';
import './search_picker_sheet.dart';
import '../../../core/constants/app_constants.dart';

// Usage with an entity:
//  AppDropdownInput<CategoryEntity>(
//     label: 'Category',
//     items: categories,
//     selectedId: _selectedCategoryId,
//     idOf: (item) => item.id,
//     labelOf: (item) => item.name,
//     onChanged: (id) => setState(() => _selectedCategoryId = id),
//  )
//
// Past about thirty options a menu becomes a scroll hunt, so a list that long
// opens a [SearchPickerSheet] instead — the same field, the same callback, a
// list you can type into. Where "long" begins is
// [AppInputConfig.searchableThreshold]; passing [searchable] overrules it for
// a single field.
class AppDropdownInput<T> extends StatelessWidget {
  const AppDropdownInput({
    super.key,
    required this.label,
    required this.items,
    required this.idOf,
    required this.labelOf,
    required this.onChanged,
    this.onSelected,
    this.onCleared,
    this.selectedId,
    this.hint = 'Select an option',
    this.enabled = true,
    this.required = false,
    this.validator,
    this.autovalidateMode,
    this.searchable,
    this.searchHint = 'Search',
    this.searchTitle,
    this.leadingOf,
    this.trailingLabelOf,
    this.filter,
    this.emptyLabel,
    this.prefixIcon,
    this.suffixIcon,
    this.labelMode,
    this.variant,
    this.type,
    this.shape,
    this.size,
    this.textAlign = TextAlign.start,
  });

  final String label;
  final List<T> items;

  /// Extract the id from an item — always a String, used as the dropdown value.
  /// Ids pick the selection, so they must be unique across [items]; a duplicate
  /// trips an assert rather than quietly selecting the wrong row.
  final String Function(T item) idOf;

  /// Extract the display label from an item.
  final String Function(T item) labelOf;

  /// Called with the selected id when the user picks an option.
  final ValueChanged<String> onChanged;

  /// Called with the item itself, alongside [onChanged]. Saves the caller
  /// looking up an entity this field had in its hand a moment earlier.
  final ValueChanged<T>? onSelected;

  /// Called when the user clears the field. Providing it is what puts the clear
  /// button in the field — with nowhere to report a clear there is no point
  /// offering one.
  final VoidCallback? onCleared;

  final String? selectedId;
  final String hint;
  final bool enabled;

  /// Marks the label, and — unless [validator] replaces the rule — rejects an
  /// empty selection when the form validates.
  final bool required;

  /// Replaces the built-in rule entirely. Receives the selected id, or null.
  /// Call [AppDropdownInput.validate] from inside it to add a rule on top
  /// instead of dropping the required check.
  final String? Function(String? id)? validator;

  /// When the field validates itself. Null follows the config, which starts at
  /// Flutter's own default — on submit only.
  final AutovalidateMode? autovalidateMode;

  /// Swaps the menu for a [SearchPickerSheet] — a bottom sheet with a search
  /// field over the same options.
  ///
  /// Null decides from the list's own length against
  /// [AppInputConfig.searchableThreshold], which is the answer nearly every
  /// field wants. Say `false` to keep a menu over a long list, `true` to give a
  /// short one a search box anyway.
  final bool? searchable;

  /// Placeholder in the sheet's search field. Only used when searchable.
  final String searchHint;

  /// Heading over the sheet. Defaults to [label]. Only used when searchable.
  final String? searchTitle;

  /// Optional leading widget per row in the sheet — a flag, an avatar, an icon.
  /// Only used when searchable.
  final Widget Function(T item)? leadingOf;

  /// Optional dimmed text at the end of a sheet row, for a secondary value.
  /// Only used when searchable.
  final String Function(T item)? trailingLabelOf;

  /// Replaces the sheet's default filter, which is a case-insensitive
  /// `contains` over [labelOf]. Returns the rows to show *in the order to show
  /// them*, so a caller can rank matches as well as select them. Only used when
  /// searchable.
  final List<T> Function(List<T> items, String query)? filter;

  /// Shown in the sheet in place of the list when there is nothing to show.
  /// Null picks copy that fits the reason — an empty [items] is not a failed
  /// search, and saying so stops the user retyping a query that was never the
  /// problem. Only used when searchable.
  final String? emptyLabel;

  final Widget? prefixIcon;

  /// Replaces the chevron — and, with it, the clear button. The field's own
  /// trailing affordances are a default, not a guarantee.
  final Widget? suffixIcon;

  /// Null follows [AppInputConfig.defaults].
  final AppInputLabelMode? labelMode;
  final AppInputVariant? variant;
  final AppInputType? type;
  final AppInputShape? shape;
  final AppInputSize? size;

  /// Alignment of the selected value and the hint. The label follows it too.
  final TextAlign textAlign;

  /// The rule applied when no [validator] is given: a required field has to
  /// hold a selection.
  ///
  /// Exposed so a custom [validator] can layer on top of it:
  ///
  ///   validator: (id) =>
  ///       AppDropdownInput.validate(id, required: true) ??
  ///       (id == 'archived' ? 'That category is closed' : null),
  static String? validate(String? id, {bool required = false}) =>
      required && (id == null || id.isEmpty) ? 'This field is required' : null;

  /// The item an id points at, or null when no row carries it.
  T? _itemFor(String? id) {
    if (id == null) return null;
    for (final item in items) {
      if (idOf(item) == id) return item;
    }
    return null;
  }

  /// The item [selectedId] points at, or null when nothing is selected — or
  /// when the id has no row yet.
  T? get _selected => _itemFor(selectedId);

  /// Whether this field opens a sheet rather than a menu.
  bool get _searchable =>
      searchable ?? items.length >= AppInputStyle.config.searchableThreshold;

  /// The rule in force — the caller's, else the built-in one.
  String? _validate(String? id) {
    final rule = validator;
    return rule != null ? rule(id) : validate(id, required: required);
  }

  InputDecoration _decoration(
    BuildContext context, {
    Widget? suffix,
    String? errorText,
  }) => AppInputStyle.decoration(
    context,
    variant: variant,
    type: type,
    shape: shape,
    size: size,
    label: label,
    labelMode: labelMode,
    required: required,
    hint: hint,
    prefixIcon: prefixIcon,
    suffixIcon: suffix,
    enabled: enabled,
  ).copyWith(errorText: errorText);

  /// What sits at the end of the field: the caller's own suffix if there is
  /// one, else the clear button when there is something to clear, ahead of the
  /// chevron. A disabled field shows neither — there is no action left to
  /// advertise.
  Widget? _trailing(T? selected) {
    if (suffixIcon != null) return suffixIcon;
    if (!enabled) return null;

    const chevron = Icon(Icons.keyboard_arrow_down);
    if (onCleared == null || selected == null) return chevron;

    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        IconButton(
          onPressed: () {
            HapticFeedback.selectionClick();
            onCleared!();
          },
          tooltip: 'Clear',
          icon: const Icon(Icons.close),
        ),
        chevron,
      ],
    );
  }

  /// Reports a pick to the caller. [haptic] is off on the sheet's path, where
  /// the tapped row has already given feedback of its own.
  void _pick(T item, {bool haptic = true}) {
    if (haptic) HapticFeedback.selectionClick();
    onChanged(idOf(item));
    onSelected?.call(item);
  }

  Future<void> _openSheet(
    BuildContext context,
    FormFieldState<String> state,
  ) async {
    final picked = await SearchPickerSheet.show<T>(
      context,
      title: searchTitle ?? label,
      searchHint: searchHint,
      items: items,
      idOf: idOf,
      labelOf: labelOf,
      selectedId: selectedId,
      leadingOf: leadingOf,
      trailingLabelOf: trailingLabelOf,
      filter: filter,
      emptyLabel:
          emptyLabel ??
          (items.isEmpty
              ? 'Nothing to choose from'
              : 'Nothing matches that search'),
      variant: variant,
    );
    if (picked == null) return;
    // Marks the field as interacted with, so a form set to validate on
    // interaction clears its error the moment a selection lands.
    state.didChange(idOf(picked));
    _pick(picked, haptic: false);
  }

  @override
  Widget build(BuildContext context) {
    assert(
      items.map(idOf).toSet().length == items.length,
      'AppDropdownInput<$T>: idOf returned the same id for more than one item. '
      'Ids are what pick the selection, so they have to be unique.',
    );

    final selected = _selected;
    final accent = AppInputStyle.accentOf(context, variant);
    final alignment = AppInputStyle.alignmentOf(textAlign);

    return InputFieldLayout(
      label: label,
      required: required,
      labelMode: labelMode,
      variant: variant,
      size: size,
      textAlign: textAlign,
      // Both forms turn themselves off from the inside — an IgnorePointer here
      // would block the tap but leave the field painting itself as live.
      field: _searchable
          ? _searchableField(context, selected, accent, alignment)
          : _menuField(context, selected, accent, alignment),
    );
  }

  /// The searchable form: the field only *shows* the selection and opens the
  /// sheet, so there is no menu to lay out and the value still lives with the
  /// caller.
  ///
  /// The [FormField] around it is what lets this form be validated at all. An
  /// [InputDecorator] is only a picture of an input — without this a `Form`
  /// walks straight past a searchable field and a required one submits empty.
  Widget _searchableField(
    BuildContext context,
    T? selected,
    Color accent,
    AlignmentGeometry alignment,
  ) {
    return FormField<String>(
      initialValue: selectedId,
      enabled: enabled,
      autovalidateMode:
          autovalidateMode ?? AppInputStyle.config.autovalidateMode,
      // Judged on [selectedId] rather than on the value this FormField happens
      // to hold: the caller owns the selection, so its answer is the true one
      // even before a rebuild has reached here.
      validator: (_) => _validate(selectedId),
      builder: (state) => MergeSemantics(
        // An InkWell announces nothing on its own; without this a screen reader
        // reads out the value and never says it can be opened.
        child: Semantics(
          button: true,
          enabled: enabled,
          child: InkWell(
            onTap: enabled ? () => _openSheet(context, state) : null,
            borderRadius: AppConstants.borderRadius12,
            child: InputDecorator(
              // The chevron sits inside the border here, where a suffix goes;
              // the menu form hands its own to the dropdown instead.
              decoration: _decoration(
                context,
                suffix: _trailing(selected),
                errorText: state.errorText,
              ),
              // Drives the hint and the floating label the same way an empty
              // text field would.
              isEmpty: selected == null,
              child: selected == null
                  ? null
                  : Align(
                      alignment: alignment,
                      child: Text(
                        labelOf(selected),
                        textAlign: textAlign,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: AppInputStyle.textStyle(
                          context,
                          size: size,
                        )?.copyWith(color: accent, fontWeight: FontWeight.bold),
                      ),
                    ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _menuField(
    BuildContext context,
    T? selected,
    Color accent,
    AlignmentGeometry alignment,
  ) {
    return DropdownButtonFormField<String>(
      // Only an id that actually resolves. A dropdown asserts that exactly one
      // of its items carries its value, so an id whose row has not arrived yet
      // — restored state waiting on a fetch, a list refreshed out from under
      // the selection — would otherwise throw.
      initialValue: selected == null ? null : selectedId,
      style: AppInputStyle.textStyle(
        context,
        size: size,
      )?.copyWith(color: accent, fontWeight: FontWeight.bold),
      decoration: _decoration(context),
      isExpanded: true,
      // A dropdown has no textAlign, so align the item boxes instead.
      alignment: alignment,
      autovalidateMode:
          autovalidateMode ?? AppInputStyle.config.autovalidateMode,
      validator: _validate,
      // A null onChanged is what disables a dropdown: it greys the value out
      // and takes the field out of the focus order, which no wrapper can do.
      onChanged: enabled ? _onMenuChanged : null,
      iconEnabledColor: accent,
      iconSize: AppInputStyle.configOf(size).iconSize,
      // The trailing widget belongs here, not in the decoration: a dropdown
      // draws exactly one, and `icon` is the slot it reads first — anything
      // left in `suffixIcon` is dropped on the floor.
      icon: _trailing(selected) ?? const SizedBox.shrink(),
      items: items
          .map(
            (item) => DropdownMenuItem<String>(
              value: idOf(item),
              alignment: alignment,
              child: Text(labelOf(item), textAlign: textAlign),
            ),
          )
          .toList(),
    );
  }

  void _onMenuChanged(String? id) {
    final item = _itemFor(id);
    if (item != null) _pick(item);
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:local_auth/local_auth.dart';
import 'package:local_auth_android/local_auth_android.dart';
import 'package:local_auth_darwin/types/auth_messages_ios.dart';

import '../utils/app_logger.dart';

final biometricServiceProvider = Provider<BiometricService>((ref) {
  return BiometricService(LocalAuthentication());
});

class BiometricService {
  BiometricService(this._auth);

  final LocalAuthentication _auth;

  // True when the device has a lock screen, biometrics enrolled or not.
  Future<bool> canAuthenticate() => _auth.isDeviceSupported();

  Future<bool> authenticate() {
    return _auth.authenticate(
      localizedReason: 'Please authenticate to continue',
      biometricOnly: false,
      authMessages: const <AuthMessages>[
        AndroidAuthMessages(
          signInTitle: 'Authentication required',
          cancelButton: 'Cancel',
        ),
        IOSAuthMessages(cancelButton: 'Cancel'),
      ],
    );
  }

  /// Runs local authentication, reporting failure as a snackbar rather than
  /// throwing, so callers only need the bool.
  Future<bool> verifyUserLocalAuth(BuildContext context) async {
    // Resolved before any await — the prompt can outlive the calling widget.
    final messenger = ScaffoldMessenger.of(context);

    try {
      final didAuthenticate = await authenticate();
      if (!didAuthenticate) {
        _showFeedback(messenger, 'Authentication failed');
        return false;
      }
      return true;
    } on LocalAuthException catch (e) {
      appLogger.e('LocalAuthException: ${e.code.name} - ${e.description}');
      // Device has neither biometrics nor a PIN/pattern/password set up, so
      // there is no local credential to fall back to.
      final message = e.code == LocalAuthExceptionCode.noCredentialsSet
          ? 'Device has no lock method configured'
          : e.description ?? 'Authentication error';
      _showFeedback(messenger, message);
      return false;
    } on PlatformException catch (e) {
      appLogger.e('PlatformException: ${e.message}');
      _showFeedback(messenger, e.message ?? 'Authentication error');
      return false;
    }
  }

  void _showFeedback(ScaffoldMessengerState messenger, String message) {
    // The screen may have been popped while the prompt was up.
    if (!messenger.mounted) return;
    messenger.showSnackBar(SnackBar(content: Text(message)));
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:table_calendar/table_calendar.dart';

import '../inputs/app_input_style.dart';
import '../../../core/constants/app_constants.dart';

/// How much of the month [AppCalendar] shows at once.
enum AppCalendarFormat { month, twoWeeks, week }

/// The column a week starts in. Monday outside the US, Sunday inside it,
/// Saturday across much of the Middle East.
enum AppCalendarWeekStart { monday, saturday, sunday }

/// An inline month calendar — the sibling of `AppDateInput`, which opens the
/// platform picker instead of showing the grid.
///
/// Use it when the month itself is the content — an agenda, a booking screen.
/// Use `AppDateInput` when a date is one answer in a form.
///
/// ```dart
/// AppCalendar(
///   selected: _day,
///   onSelected: (day) => setState(() => _day = day),
/// )
/// ```
///
/// With events, and loading them as the month turns:
///
/// ```dart
/// AppCalendar(
///   selected: _day,
///   events: {for (final a in appointments) a.startsAt: 1},
///   onSelected: (day) => setState(() => _day = day),
///   onMonthChanged: (first, last) => ref.read(p.notifier).load(first, last),
/// )
/// ```
///
/// Leaving [onSelected] null makes it a read-only display — an availability
/// month with nothing to tap.
class AppCalendar extends StatefulWidget {
  const AppCalendar({
    super.key,
    this.selected,
    this.onSelected,
    this.events = const <DateTime, int>{},
    this.onMonthChanged,
    this.firstDate,
    this.lastDate,
    this.focusedMonth,
    this.format = AppCalendarFormat.month,
    this.canChangeFormat = false,
    this.weekStart = AppCalendarWeekStart.monday,
    this.selectableDay,
    this.variant,
    this.locale,
    this.rowHeight = 46,
  });

  /// The day drawn as selected. Null selects nothing.
  final DateTime? selected;

  /// Called with the tapped day. Null makes the calendar read-only.
  final ValueChanged<DateTime>? onSelected;

  /// Day → how many dots to draw under it, capped at three.
  ///
  /// The keys are re-keyed to the day they fall on, so you can hand this map
  /// whatever `DateTime` your data already carries — two appointments at
  /// 09:00 and 14:00 count as two dots on one day rather than missing the
  /// grid entirely, which is what a raw `DateTime` key does.
  final Map<DateTime, int> events;

  /// Called with the first and last day now on screen, whenever the page
  /// turns or the format changes — the range to fetch [events] for. For
  /// [AppCalendarFormat.month] that is the month's own bounds, not the six
  /// weeks drawn around it.
  final void Function(DateTime first, DateTime last)? onMonthChanged;

  /// Defaults to five years back.
  final DateTime? firstDate;

  /// Defaults to five years on.
  final DateTime? lastDate;

  /// The month to open on. Defaults to [selected], then today.
  final DateTime? focusedMonth;

  /// How much is shown at once. The calendar remembers what the user swipes
  /// to from here, so this is the starting point rather than a fixed setting.
  final AppCalendarFormat format;

  /// Shows the format button and lets a vertical swipe collapse the month to
  /// two weeks or one. Off by default: most screens want one shape.
  final bool canChangeFormat;

  final AppCalendarWeekStart weekStart;

  /// Days this returns false for are greyed and refuse a tap — booked-out
  /// dates, weekends on a business calendar.
  final bool Function(DateTime day)? selectableDay;

  /// Colors the selected day, today's ring and the event dots. Null follows
  /// [AppInputConfig.defaults], like every other field in the kit.
  final AppInputVariant? variant;

  /// A locale tag such as `'pt_PT'`. Null uses the app's.
  ///
  /// Anything other than `en_US` needs
  /// `initializeDateFormatting()` from `package:intl` called once at startup.
  final String? locale;

  final double rowHeight;

  @override
  State<AppCalendar> createState() => _AppCalendarState();
}

class _AppCalendarState extends State<AppCalendar> {
  /// The one instance handed to `eventLoader` per dot. `TableCalendar` only
  /// counts what it gets back, so there is nothing to carry.
  static const Object _dot = Object();

  static const double _todayFill = 0.12;
  static const double _disabledOpacity = 0.38;
  static const int _maxDots = 3;
  static const double _dotSize = 5;

  late DateTime _focused;
  late AppCalendarFormat _format;

  @override
  void initState() {
    super.initState();
    _focused = widget.focusedMonth ?? widget.selected ?? DateTime.now();
    _format = widget.format;
  }

  @override
  void didUpdateWidget(AppCalendar oldWidget) {
    super.didUpdateWidget(oldWidget);
    // A selection made from outside — a "jump to today" button, a restored
    // draft — has to bring the page with it, or it lands on a month that is
    // not on screen.
    final selected = widget.selected;
    if (selected != null && !isSameDay(selected, oldWidget.selected)) {
      _focused = selected;
    }
    final focusedMonth = widget.focusedMonth;
    if (focusedMonth != null && focusedMonth != oldWidget.focusedMonth) {
      _focused = focusedMonth;
    }
    if (widget.format != oldWidget.format) _format = widget.format;
  }

  /// [AppCalendar.events] re-keyed to the day each entry falls on.
  ///
  /// Two `DateTime`s in the same day are not equal, so a map keyed on the
  /// instants the data carries never matches the midnight key the grid looks
  /// up. Counts on the same day are added rather than the last one winning.
  Map<DateTime, int> get _markers {
    final byDay = <DateTime, int>{};
    widget.events.forEach((day, count) {
      if (count <= 0) return;
      final key = DateTime.utc(day.year, day.month, day.day);
      byDay[key] = (byDay[key] ?? 0) + count;
    });
    return byDay;
  }

  int get _weekStartIndex => switch (widget.weekStart) {
        AppCalendarWeekStart.monday => DateTime.monday,
        AppCalendarWeekStart.saturday => DateTime.saturday,
        AppCalendarWeekStart.sunday => DateTime.sunday,
      };

  DateTime _startOfWeek(DateTime day) {
    final offset = (day.weekday - _weekStartIndex + 7) % 7;
    return DateTime(day.year, day.month, day.day - offset);
  }

  /// The first and last day on screen for the current format — what
  /// [AppCalendar.onMonthChanged] reports.
  (DateTime, DateTime) _visibleRange(DateTime focused) {
    switch (_format) {
      case AppCalendarFormat.month:
        // Day zero of the next month is the last day of this one.
        return (
          DateTime(focused.year, focused.month, 1),
          DateTime(focused.year, focused.month + 1, 0),
        );
      case AppCalendarFormat.twoWeeks:
        final start = _startOfWeek(focused);
        return (start, DateTime(start.year, start.month, start.day + 13));
      case AppCalendarFormat.week:
        final start = _startOfWeek(focused);
        return (start, DateTime(start.year, start.month, start.day + 6));
    }
  }

  void _reportRange() {
    final onMonthChanged = widget.onMonthChanged;
    if (onMonthChanged == null) return;
    final (first, last) = _visibleRange(_focused);
    onMonthChanged(first, last);
  }

  CalendarFormat get _tableFormat => switch (_format) {
        AppCalendarFormat.month => CalendarFormat.month,
        AppCalendarFormat.twoWeeks => CalendarFormat.twoWeeks,
        AppCalendarFormat.week => CalendarFormat.week,
      };

  StartingDayOfWeek get _tableWeekStart => switch (widget.weekStart) {
        AppCalendarWeekStart.monday => StartingDayOfWeek.monday,
        AppCalendarWeekStart.saturday => StartingDayOfWeek.saturday,
        AppCalendarWeekStart.sunday => StartingDayOfWeek.sunday,
      };

  static AppCalendarFormat _formatFrom(CalendarFormat format) =>
      switch (format) {
        CalendarFormat.month => AppCalendarFormat.month,
        CalendarFormat.twoWeeks => AppCalendarFormat.twoWeeks,
        CalendarFormat.week => AppCalendarFormat.week,
      };

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final colorScheme = theme.colorScheme;
    final accent = AppInputStyle.accentOf(context, widget.variant);
    final onAccent = AppInputStyle.onAccentOf(context, widget.variant);

    final body = theme.textTheme.bodyMedium ??
        const TextStyle(fontSize: AppConstants.fontSize14);
    final label = theme.textTheme.labelSmall ??
        const TextStyle(fontSize: AppConstants.fontSize12);

    final markers = _markers;
    final today = DateTime.now();
    final enabled = widget.onSelected != null;

    return TableCalendar<Object>(
      firstDay: widget.firstDate ?? DateTime(today.year - 5, 1, 1),
      lastDay: widget.lastDate ?? DateTime(today.year + 5, 12, 31),
      focusedDay: _focused,
      locale: widget.locale,
      rowHeight: widget.rowHeight,
      startingDayOfWeek: _tableWeekStart,
      calendarFormat: _tableFormat,
      // A vertical swipe is what changes the format, so it is only offered
      // when the format can change at all.
      availableGestures: widget.canChangeFormat
          ? AvailableGestures.all
          : AvailableGestures.horizontalSwipe,
      availableCalendarFormats: widget.canChangeFormat
          ? const {
              CalendarFormat.month: 'Month',
              CalendarFormat.twoWeeks: '2 weeks',
              CalendarFormat.week: 'Week',
            }
          : {_tableFormat: ''},
      selectedDayPredicate: (day) => isSameDay(widget.selected, day),
      enabledDayPredicate: widget.selectableDay,
      eventLoader: (day) {
        final count = markers[DateTime.utc(day.year, day.month, day.day)] ?? 0;
        return List<Object>.filled(count, _dot);
      },
      onDaySelected: enabled
          ? (selectedDay, focusedDay) {
              HapticFeedback.selectionClick();
              setState(() => _focused = focusedDay);
              widget.onSelected!(selectedDay);
            }
          : null,
      onPageChanged: (focusedDay) {
        // Not setState: TableCalendar has already moved, and rebuilding here
        // fights its own page animation.
        _focused = focusedDay;
        _reportRange();
      },
      onFormatChanged: (format) {
        setState(() => _format = _formatFrom(format));
        _reportRange();
      },
      headerStyle: HeaderStyle(
        titleCentered: true,
        formatButtonVisible: widget.canChangeFormat,
        formatButtonShowsNext: false,
        headerPadding:
            const EdgeInsets.symmetric(vertical: AppConstants.space8),
        titleTextStyle: theme.textTheme.titleMedium ??
            const TextStyle(
              fontSize: AppConstants.fontSize16,
              fontWeight: FontWeight.w600,
            ),
        leftChevronIcon: Icon(
          Icons.chevron_left,
          color: colorScheme.onSurfaceVariant,
        ),
        rightChevronIcon: Icon(
          Icons.chevron_right,
          color: colorScheme.onSurfaceVariant,
        ),
        formatButtonDecoration: BoxDecoration(
          color: accent.withValues(alpha: _todayFill),
          borderRadius: AppConstants.borderRadiusFull,
        ),
        formatButtonTextStyle: TextStyle(
          color: accent,
          fontSize: AppConstants.fontSize13,
          fontWeight: FontWeight.w600,
        ),
        decoration: const BoxDecoration(),
      ),
      daysOfWeekStyle: DaysOfWeekStyle(
        weekdayStyle: label.copyWith(color: colorScheme.onSurfaceVariant),
        weekendStyle: label.copyWith(color: colorScheme.onSurfaceVariant),
      ),
      calendarStyle: CalendarStyle(
        isTodayHighlighted: true,
        // The greyed-out spill from the neighbouring months reads as tappable
        // when it is not; the grid is easier to scan without it.
        outsideDaysVisible: false,
        cellMargin: const EdgeInsets.all(AppConstants.space4),
        defaultTextStyle: body,
        weekendTextStyle: body.copyWith(color: colorScheme.onSurfaceVariant),
        disabledTextStyle: body.copyWith(
          color: colorScheme.onSurface.withValues(alpha: _disabledOpacity),
        ),
        selectedTextStyle: body.copyWith(
          color: onAccent,
          fontWeight: FontWeight.w600,
        ),
        selectedDecoration: BoxDecoration(
          color: accent,
          shape: BoxShape.circle,
        ),
        todayTextStyle: body.copyWith(
          color: accent,
          fontWeight: FontWeight.w600,
        ),
        todayDecoration: BoxDecoration(
          color: accent.withValues(alpha: _todayFill),
          shape: BoxShape.circle,
        ),
        markerDecoration: BoxDecoration(
          color: accent,
          shape: BoxShape.circle,
        ),
        markersMaxCount: _maxDots,
        markerSize: _dotSize,
        markersAlignment: Alignment.bottomCenter,
        markerMargin: const EdgeInsets.symmetric(horizontal: 1),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../overlays/app_toast.dart';

/// Reports a notifier's one-shot `error` / `success` messages to the user.
/// Call it from `build`, like any other `ref.listen`.
///
/// ```dart
/// ref.listenAction<HomeState>(
///   context,
///   homeNotifierProvider,
///   errorOf: (state) => state.error,
///   successOf: (state) => state.success,
/// );
/// ```
///
/// [onError] / [onSuccess] replace the toast for that outcome rather than
/// adding to it, so a screen that navigates does not also flash a message.
extension ActionListener on WidgetRef {
  /// Listens to [provider] and reports whichever message the new state carries.
  /// [errorOf] and [successOf] are both optional.
  void listenAction<S>(
    BuildContext context,
    ProviderListenable<AsyncValue<S>> provider, {
    String? Function(S state)? errorOf,
    String? Function(S state)? successOf,
    void Function(String message)? onError,
    void Function(String message)? onSuccess,
  }) {
    listen<AsyncValue<S>>(provider, (previous, next) {
      // A load has no outcome yet, and a failed provider is the view's error
      // state to draw — not a toast on top of it.
      if (next.isLoading) return;
      final state = next.value;
      if (state == null) return;

      // An action can land in the same frame the route is popped.
      if (!context.mounted) return;

      final error = errorOf?.call(state);
      if (error != null && error.isNotEmpty) {
        if (onError != null) {
          onError(error);
        } else {
          AppToast.error(context, error);
        }
        // One outcome per action — falling through would toast a stale success.
        return;
      }

      final success = successOf?.call(state);
      if (success != null && success.isNotEmpty) {
        if (onSuccess != null) {
          onSuccess(success);
        } else {
          AppToast.success(context, success);
        }
      }
    });
  }
}

